begin;
    with j as (select * from jsonb_to_recordset($law7v023$[{"code_id":"NK_RF","article_number":"14","version_date":"2000-07-31","article_text":"К региональным налогам относятся:\n\n1) налог на имущество организаций;\n\n2) налог на игорный бизнес;\n\n3) транспортный налог.\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 14. Региональные налоги","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71fe4bfcd1ee742e041374e0f47b9664707f498cb02c4231f8c416f1236816de"},{"code_id":"NK_RF","article_number":"140","version_date":"2000-07-31","article_text":"1. В ходе рассмотрения жалобы (апелляционной жалобы) лицо, подавшее эту жалобу, до принятия по ней решения вправе представить дополнительные документы, подтверждающие его доводы.\n\nЛицо, подавшее жалобу (апелляционную жалобу), до принятия по ней решения вправе обратиться с ходатайством о приостановлении рассмотрения жалобы (апелляционной жалобы) полностью или в части в целях представления дополнительных документов (информации), но не более чем на шесть месяцев. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ течение пяти дней со дня получения указанного ходатайства вышестоящий налоговый орган, рассматривающий жалобу (апелляционную жалобу), принимает одно из следующих решений: (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nо приостановлении рассмотрения жалобы (апелляционной жалобы) полностью или в части; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nоб отказе в приостановлении рассмотрения жалобы (апелляционной жалобы). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nО принятом решении в течение трех дней со дня его принятия сообщается лицу, подавшему жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n2. Вышестоящий налоговый орган рассматривает жалобу (апелляционную жалобу), документы, подтверждающие доводы лица, подавшего жалобу (апелляционную жалобу), дополнительные документы, представленные в ходе рассмотрения жалобы (апелляционной жалобы), а также материалы, представленные нижестоящим налоговым органом, без участия лица, подавшего жалобу (апелляционную жалобу), за исключением случаев, предусмотренных настоящим пунктом.\n\nВ случае выявления в ходе рассмотрения жалобы (апелляционной жалобы) на решение о привлечении к ответственности за совершение налогового правонарушения или на решение об отказе в привлечении к ответственности за совершение налогового правонарушения противоречий между сведениями, содержащимися в представленных нижестоящим налоговым органом материалах, либо несоответствия сведений, представленных налогоплательщиком, сведениям, содержащимся в материалах нижестоящего налогового органа, вышестоящий налоговый орган рассматривает жалобу (апелляционную жалобу), документы, подтверждающие доводы лица, подавшего жалобу (апелляционную жалобу), дополнительные документы, представленные в ходе рассмотрения жалобы (апелляционной жалобы), а также материалы, представленные нижестоящим налоговым органом, с участием лица, подавшего жалобу (апелляционную жалобу).\n\nРуководитель (заместитель руководителя) вышестоящего налогового органа извещает лицо, подавшее жалобу (апелляционную жалобу), о времени и месте рассмотрения жалобы (апелляционной жалобы).\n\nРассмотрение жалобы (апелляционной жалобы) возможно с использованием видео-конференц-связи в порядке, утверждаемом федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nРассмотрение жалобы (апелляционной жалобы) может быть приостановлено по решению вышестоящего налогового органа, рассматривающего жалобу (апелляционную жалобу): (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nдо разрешения дела о том же предмете и по тем же основаниям арбитражным судом, судом общей юрисдикции; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nв случае невозможности рассмотрения жалобы (апелляционной жалобы) до разрешения другого дела судом в конституционном, гражданском, арбитражном, административном, уголовном судопроизводстве; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nдо рассмотрения заявления о проведении взаимосогласительной процедуры в порядке, предусмотренном главой 203 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nО принятом решении об указанном приостановлении рассмотрения жалобы (апелляционной жалобы) в течение трех дней со дня его принятия сообщается лицу, подавшему жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n3. По итогам рассмотрения жалобы (апелляционной жалобы) вышестоящий налоговый орган:\n\n1) оставляет жалобу (апелляционную жалобу) без удовлетворения;\n\n2) отменяет акт налогового органа ненормативного характера;\n\n3) отменяет решение налогового органа полностью или в части;\n\n4) отменяет решение налогового органа полностью и принимает по делу новое решение;\n\n5) признает действия или бездействие должностных лиц налоговых органов незаконными и выносит решение по существу.\n\nВышестоящий налоговый орган, установив по результатам рассмотрения жалобы на решение, вынесенное в порядке, предусмотренном статьей 1014 настоящего Кодекса, нарушение существенных условий процедуры рассмотрения материалов иных мероприятий налогового контроля, вправе отменить такое решение, рассмотреть указанные материалы, документы, подтверждающие доводы лица, подавшего жалобу, дополнительные документы, представленные в ходе рассмотрения жалобы, и материалы, представленные нижестоящим налоговым органом, в порядке, предусмотренном статьей 1014 настоящего Кодекса, и вынести решение, предусмотренное пунктом 3 настоящей статьи.\n\nРешение по жалобе, не указанной в абзаце первом настоящего пункта, принимается налоговым органом в течение 15 дней со дня ее получения. Указанный срок может быть продлен руководителем (заместителем руководителя) налогового органа для получения от нижестоящих налоговых органов документов (информации), необходимых для рассмотрения жалобы, или при представлении лицом, подавшим жалобу, дополнительных документов, но не более чем на 15 дней.\n\nРешение руководителя (заместителя руководителя) налогового органа о продлении срока рассмотрения жалобы (апелляционной жалобы) вручается или направляется лицу, подавшему жалобу (апелляционную жалобу), в течение трех дней со дня его принятия.\n\nРешение налогового органа по результатам рассмотрения жалобы (апелляционной жалобы) вручается или направляется лицу, подавшему жалобу (апелляционную жалобу), в течение трех дней со дня его принятия.\n\nВ случае представления лицом, подавшим жалобу (апелляционную жалобу), дополнительных документов сроки, установленные абзацами первым и вторым настоящего пункта, исчисляются с момента получения указанных документов вышестоящим налоговым органом, рассматривающим жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 140. Рассмотрение жалобы (апелляционной жалобы)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bf61b2f7f5b099f4ec69b8bdcd8a61d3d1a55d0fa0c60e07028226842afeaf6f"},{"code_id":"NK_RF","article_number":"140.1","version_date":"2000-07-31","article_text":"1. Жалобы, направленные в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика в формате и в соответствии с порядком представления жалоб в электронной форме, утвержденными федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, за исключением жалоб, поданных на решения налоговых органов, принятые в соответствии со статьями 101 и 1014 настоящего Кодекса, могут быть рассмотрены в упрощенном порядке в случае указания на это в жалобе.\n\n2. Рассмотрение жалобы в упрощенном порядке осуществляется налоговым органом, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются.\n\n3. Жалоба, предусмотренная настоящей статьей, рассматривается налоговым органом в течение семи дней со дня ее получения.\n\n4. По итогам рассмотрения жалобы в соответствии с настоящей статьей налоговый орган:\n\n1) принимает решение, предусмотренное подпунктами 2 - 5 пункта 3 статьи 140 настоящего Кодекса;\n\n2) принимает меры, предусмотренные пунктом 1 или пунктами 1 и 11 статьи 139 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 140.1. Особенности рассмотрения жалобы в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f3847f0de22106c749e4f6fd722e4c703f45f25b8d529e6908f2a3b8518b397"},{"code_id":"NK_RF","article_number":"141","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 141. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47cff44cc50fb2ec2ff27049b702903fd186972de20e3143a4ff6670b28b8079"},{"code_id":"NK_RF","article_number":"142","version_date":"2000-07-31","article_text":"Жалобы (исковые заявления) на акты налоговых органов, действия или бездействие их должностных лиц, поданные в суд, рассматриваются и раз\n\nрешаются в порядке, установленном гражданским процессуальным, арбитражным процессуальным законодательством, законодательством об административном судопроизводстве и иными федеральными законами. (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\nРАЗДЕЛ VII1. ВЫПОЛНЕНИЕ МЕЖДУНАРОДНЫХ ДОГОВОРОВ РОССИЙСКОЙ ФЕДЕРАЦИИ ПО ВОПРОСАМ НАЛОГООБЛОЖЕНИЯ И ВЗАИМНОЙ АДМИНИСТРАТИВНОЙ ПОМОЩИ ПО НАЛОГОВЫМ ДЕЛАМ\n\n(Дополнение разделом - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 142. Рассмотрение жалоб, поданных в суд","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cfc57961b16fd3f4a14d2771f93dbc6e08c3cd6cda2012aeff5d46b51219ddf"},{"code_id":"NK_RF","article_number":"142.1","version_date":"2000-07-31","article_text":"Для целей настоящего Кодекса при осуществлении автоматического обмена финансовой информацией с иностранными государствами (территориями) используются следующие понятия и термины:\n\n1) международный автоматический обмен финансовой информацией с компетентными органами иностранных государств (территорий) (далее - автоматический обмен финансовой информацией) - предоставление федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, компетентным органам иностранных государств (территорий) и получение федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от компетентных органов иностранных государств (территорий) информации, предусмотренной настоящей главой, на автоматической основе в соответствии с международными договорами Российской Федерации по вопросам налогообложения;\n\n2) организация финансового рынка - кредитная организация, страховщик, осуществляющий деятельность по добровольному страхованию жизни, профессиональный участник рынка ценных бумаг, осуществляющий брокерскую деятельность, и (или) деятельность по управлению ценными бумагами, и (или) депозитарную деятельность, управляющий по договору доверительного управления имуществом, негосударственный пенсионный фонд, акционерный инвестиционный фонд, управляющая компания инвестиционного фонда, паевого инвестиционного фонда или негосударственного пенсионного фонда, центральный контрагент, управляющий товарищ инвестиционного товарищества, иная организация или структура без образования юридического лица, которая в рамках своей деятельности принимает от клиентов денежные средства или иные финансовые активы для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n3) клиент организации финансового рынка (далее - клиент) - лицо, заключающее (заключившее) с организацией финансового рынка договор, предусматривающий оказание финансовых услуг;\n\n4) финансовые услуги - услуги, связанные с привлечением от клиентов и размещением организациями финансового рынка денежных средств или иных финансовых активов для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n5) финансовая информация - информация об операциях, счетах и вкладах клиентов, сумме обязательств страховщика, заключившего договор добровольного страхования жизни, перед клиентами или выгодоприобретателями, сумме денежных средств и стоимости имущества указанных лиц, находящегося в распоряжении организации финансового рынка в соответствии с договором о брокерском обслуживании или договором о доверительном управлении организации финансового рынка, стоимости имущества указанных лиц, учитываемого организацией финансового рынка, осуществляющей депозитарную деятельность, пенсионных счетах указанных лиц, обязательствах центральных контрагентов перед указанными лицами, а также о выплатах и операциях, совершенных в связи с указанными в настоящем подпункте счетами и вкладами, договором добровольного страхования жизни, договором доверительного управления имуществом (в том числе удостоверенным выдачей инвестиционного пая), договором о брокерском обслуживании, депозитарным договором, пенсионным договором, договором с центральным контрагентом и иными договорами, в рамках которых организация финансового рынка принимает от клиентов денежные средства или иные финансовые активы для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n6) выгодоприобретатель - лицо (структура без образования юридического лица), к выгоде которого действует клиент, в том числе на основании агентского договора, договора поручения, договора комиссии и договора доверительного управления;\n\n7) лицо, прямо или косвенно контролирующее клиента (выгодоприобретателя) - физическое лицо, которое в конечном счете прямо или косвенно (через третьих лиц) владеет (имеет преобладающее участие более 25 процентов в капитале) клиентом (выгодоприобретателем) либо имеет возможность контролировать действия клиента (выгодоприобретателя). Лицом, прямо или косвенно контролирующим клиента (выгодоприобретателя) - физическое лицо, считается само это лицо, за исключением случаев, если имеются основания полагать, что существуют иные физические лица, прямо или косвенно контролирующие клиента (выгодоприобретателя) - физическое лицо; (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)\n\n8) финансовые активы - денежные средства, ценные бумаги, производные финансовые инструменты, доли участия в уставном (складочном) капитале юридического лица или доли участия в иностранной структуре без образования юридического лица, права требования из договора страхования, а также иные активы, являющиеся предметом договора между клиентом и организацией финансового рынка, предусматривающего оказание финансовых услуг. При этом для целей настоящей главы не признаются финансовыми активами недвижимое имущество, драгоценные металлы (кроме драгоценных металлов на счетах, во вкладах или принятых для хранения с обезличением), а также ценности, принятые для хранения в индивидуальном банковском сейфе. (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)","article_title":"Статья 142.1. Понятия и термины, используемые при осуществлении автоматического обмена финансовой информацией с иностранными государствами (территориями)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f75888b735050e294de1b0919536f31e9a50599abf8a52790c6d0dce4b89767"},{"code_id":"NK_RF","article_number":"142.2","version_date":"2000-07-31","article_text":"Если на основании мероприятий, установленных пунктом 1 статьи 1424 настоящего Кодекса, или имеющейся у организации финансового рынка информации не выявлены клиенты, выгодоприобретатели и (или) лица, прямо или косвенно их контролирующие, которые являются налоговыми резидентами иностранных государств (территорий), организация финансового рынка обязана представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, информацию о невыявлении таких клиентов, выгодоприобретателей и (или) лиц, прямо или косвенно их контролирующих. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)\n\nУказанная в абзацах первом и втором настоящего пункта информация представляется организацией финансового рынка по установленным форматам в электронной форме. Условия, порядок и сроки представления такой информации организацией финансового рынка, ее состав устанавливаются Правительством Российской Федерации по согласованию с Центральным банком Российской Федерации. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)","article_title":"Статья 142.2. Обязанности организации финансового рынка по представлению информации в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d6b9715e91b0b7d9cf36f8b06369502eba2d84ec29ea93fe780616e8211845e"},{"code_id":"NK_RF","article_number":"142.3","version_date":"2000-07-31","article_text":"1. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в связи с осуществлением автоматического обмена финансовой информацией получает от организации финансового рынка информацию о клиентах, выгодоприобретателях и (или) лицах, прямо или косвенно их контролирующих, а также иную информацию, представляемую в соответствии с настоящей главой.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, передает такую информацию компетентным органам иностранных государств (территорий), включенных в перечень государств (территорий), с которыми осуществляется автоматический обмен финансовой информацией и налоговыми резидентами которых являются клиенты, выгодоприобретатели и (или) лица, прямо или косвенно их контролирующие.\n\nПеречень государств (территорий), с которыми осуществляется автоматический обмен финансовой информацией, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Порядок передачи финансовой информации компетентным органам иностранных государств (территорий), указанным в пункте 1 настоящей статьи, получения финансовой информации федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от таких компетентных органов, а также требования к защите передаваемой финансовой информации определяются Правительством Российской Федерации.\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, и территориальные налоговые органы вправе использовать финансовую информацию организаций финансового рынка и компетентных органов иностранных государств (территорий), полученную в соответствии с настоящей главой, при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n4. Финансовая информация в электронной форме от организаций финансового рынка и компетентных органов иностранных государств (территорий), поступившая в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, приравнивается к информации, полученной на бумажном носителе.","article_title":"Статья 142.3. Полномочия федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50c66503dfa766492cd7b4686c48e41b7b794edd8bd2d3a4881444bd26926394"},{"code_id":"NK_RF","article_number":"142.4","version_date":"2000-07-31","article_text":"1. В целях исполнения обязанностей, установленных настоящей главой, организация финансового рынка в порядке, установленном Правительством Российской Федерации по согласованию с Центральным банком Российской Федерации, запрашивает, обрабатывает, в том числе документально фиксирует, и анализирует полученную информацию, а также принимает, в том числе документально фиксирует, обоснованные и доступные в сложившихся обстоятельствах меры по установлению налогового резидентства клиентов, выгодоприобретателей и лиц, прямо или косвенно их контролирующих, включая проверку достоверности и полноты предоставленной клиентом информации.\n\n2. Клиенты обязаны представлять в организацию финансового рынка информацию в отношении самих себя, выгодоприобретателей и (или) лиц, прямо или косвенно их контролирующих, запрашиваемую организацией финансового рынка в соответствии с настоящей главой.\n\n3. При исполнении обязанностей, предусмотренных настоящей главой, организация финансового рынка вправе использовать имеющуюся у такой организации информацию, полученную в связи с исполнением требований законодательства Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма.\n\n4. В случае непредставления лицом, заключающим с организацией финансового рынка договор, предусматривающий оказание финансовых услуг, информации, запрашиваемой в соответствии с настоящей главой, организация финансового рынка вправе отказать в заключении такого договора с этим лицом.\n\n5. В случае непредставления клиентом запрашиваемой в соответствии с настоящей главой информации организация финансового рынка вправе отказать в совершении операций, осуществляемых в пользу или по поручению клиента по договору, предусматривающему оказание финансовых услуг (далее в настоящей главе - отказ в совершении операций), и (или) в случаях, предусмотренных настоящей главой, расторгнуть в одностороннем порядке договор, предусматривающий оказание финансовых услуг, уведомив об этом клиента не позднее одного рабочего дня, следующего за днем принятия решения.\n\n6. Отказ в совершении операций означает прекращение организацией финансового рынка операций по договору, предусматривающему оказание финансовых услуг, за исключением операций, осуществляемых в целях, предусмотренных абзацами вторым - пятым пункта 2 статьи 855 Гражданского кодекса Российской Федерации, а также операций по переводу денежных средств на банковский счет клиента, открытый в другой кредитной организации, или по выдаче денежных средств клиенту.\n\nВ случае поступления денежных средств для зачисления на счет (вклад) клиента в банке после принятия организацией финансового рынка, являющейся кредитной организацией, решения об отказе в совершении операций указанные денежные средства не подлежат зачислению на счет (вклад) клиента в банке и возвращаются организацией финансового рынка, являющейся кредитной организацией, на счета плательщиков в банках-отправителях. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)\n\n7. В случае непредставления клиентом в течение пятнадцати дней со дня отказа в совершении операций информации, запрашиваемой организацией финансового рынка в соответствии с настоящей главой, организация финансового рынка вправе в одностороннем порядке расторгнуть заключенный с ним договор, предусматривающий оказание финансовых услуг, с учетом положений Гражданского кодекса Российской Федерации.\n\nВ случае представления клиентом информации, запрашиваемой организацией финансового рынка, после отказа в совершении операций до момента, когда договор, предусматривающий оказание финансовых услуг, считается расторгнутым, организация финансового рынка вправе отменить принятое ранее решение о расторжении договора.\n\n8. Если в результате проведения мер, предусмотренных пунктом 1 настоящей статьи, организация финансового рынка выявит недостоверность или неполноту представленной клиентом информации либо придет к выводу о противоречии представленной клиентом информации сведениям, имеющимся в распоряжении организации финансового рынка, в том числе полученным из иных общедоступных источников информации, организация финансового рынка вправе отказать в заключении договора, предусматривающего оказание финансовых услуг, либо в одностороннем порядке расторгнуть заключенный договор, предусматривающий оказание финансовых услуг.\n\n9. Договор, предусматривающий оказание финансовых услуг, считается расторгнутым по истечении одного месяца со дня направления организацией финансового рынка клиенту уведомления о расторжении договора, предусматривающего оказание финансовых услуг, если иной срок не установлен договором, предусматривающим оказание финансовых услуг.","article_title":"Статья 142.4. Обязанности и права организаций финансового рынка и их клиентов в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fce876b02381807bf92a70debc3574bd24910e0cde7a9652191e2b6630cd919"},{"code_id":"NK_RF","article_number":"142.5","version_date":"2000-07-31","article_text":"1. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе передавать страновые отчеты, полученные согласно положениям главы 144-1 настоящего Кодекса, компетентным органам иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами в соответствии с международными договорами Российской Федерации. Перечень иностранных государств (территорий), с компетентными органами которых осуществляется автоматический обмен страновыми отчетами, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, принимает, обрабатывает, хранит и использует при осуществлении своих полномочий по контролю и надзору страновые отчеты, полученные от компетентных органов иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами в соответствии с международными договорами Российской Федерации.\n\n3. Порядок передачи страновых отчетов компетентным органам иностранных государств (территорий), получения страновых отчетов федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от компетентных органов таких государств (территорий), а также требования к защите передаваемой информации, содержащейся в страновых отчетах, устанавливаются Правительством Российской Федерации.","article_title":"Статья 142.5. Полномочия федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, при осуществлении автоматического обмена страновыми отчетами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3af9908b259c3ba719c24275295b279eff16ae4228c95a4ace89a88e6ab36f0a"},{"code_id":"NK_RF","article_number":"142.6","version_date":"2000-07-31","article_text":"1. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами, может быть использована федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, и его территориальными орган\n\nами при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.2. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках международного автоматического обмена страновыми отчетами, не является самостоятельным доказательством неуплаты или неполной уплаты сумм налога (сбора) без исследования иных доказательств.Глава 203. ВЗАИМОСОГЛАСИТЕЛЬНАЯ ПРОЦЕДУРА В СООТВЕТСТВИИ С МЕЖДУНАРОДНЫМ ДОГОВОРОМ РОССИЙСКОЙ ФЕДЕРАЦИИ ПО ВОПРОСАМ НАЛОГООБЛОЖЕНИЯ(Дополнение главой - Федеральный закон от 29.09.2019 № 325-ФЗ)Статья 1427. Общие положенияВ целях настоящего Кодекса взаимосогласительной процедурой в соответствии с международным договором Российской Федерации по вопросам налогообложения (далее в настоящей главе - взаимосогласительная процедура) признается процедура разрешения споров о порядке налогообложения лица в отношении его доходов, прибыли и имущества при применении положений международного договора Российской Федерации по вопросам налогообложения.Статья 1428. Порядок проведения взаимосогласительной процедуры1. Порядок проведения взаимосогласительной процедуры определяется Министерством финансов Российской Федерации с учетом положений международных договоров Российской Федерации по вопросам налогообложения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)2. Взаимосогласительная процедура может быть инициирована по заявлению лица, указанного в статье 1427 настоящего Кодекса, или по запросу компетентного органа иностранного государства (территории), являющегося стороной международного договора Российской Федерации по вопросам налогообложения.3. Порядок и сроки представления заявления о проведении взаимосогласительной процедуры, а также порядок и сроки рассмотрения указанного заявления определяются Министерством финансов Российской Федерации с учетом положений международных договоров Российской Федерации по вопросам налогообложения.Статья 1429. Представление документов, сведений и иной информации в связи с проведением взаимосогласительной процедуры1. Лицо, обратившееся в Министерство финансов Российской Федерации с заявлением о проведении взаимосогласительной процедуры, обязано представить по запросу должностного лица налогового органа по месту учета такого лица документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.Документы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в сроки, установленные статьей 931 настоящего Кодекса.2. Министерство финансов Российской Федерации вправе запросить у лица, обратившегося с заявлением о проведении взаимосогласительной процедуры, не представленные ранее документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.Документы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в Министерство финансов Российской Федерации в течение одного месяца со дня получения соответствующего запроса.(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)Президент Российской Федерации                              Б.ЕльцинМосква, Кремль31 июля 1998 года№ 146-ФЗ\n\nами при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n2. Информация из страновых отчетов, представляемая в соответствии с требованиями главы 144-1 настоящего Кодекса и (или) полученная от компетентных органов иностранных государств (территорий) в рамках международного автоматического обмена страновыми отчетами, не является самостоятельным доказательством неуплаты или неполной уплаты сумм налога (сбора) без исследования иных доказательств.\n\n(Дополнение главой - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 142.6. Ограничения использования информации, содержащейся в страновых отчетах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb19061769b4dc33823722eb6f40cee27c4bb8ac2dc780a900d61347cd3e7f0b"},{"code_id":"NK_RF","article_number":"142.7","version_date":"2000-07-31","article_text":"В целях настоящего Кодекса взаимосогласительной процедурой в соответствии с международным договором Российской Федерации по вопросам налогообложения (далее в настоящей главе - взаимосогласительная процедура) признается процедура разрешения споров о порядке налогообложения лица в отношении его доходов, прибыли и имущества при применении положений международного договора Российской Федерации по вопросам налогообложения.","article_title":"Статья 142.7. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"05e627e10e6c5a3c3d710d46dd7d6fe547dd549e3a8d2b1f4e33cd0211e1db7a"},{"code_id":"NK_RF","article_number":"142.9","version_date":"2000-07-31","article_text":"1. Лицо, обратившееся в Министерство финансов Российской Федерации с заявлением о проведении взаимосогласительной процедуры, обязано представить по запросу должностного лица налогового органа по месту учета такого лица документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.\n\nДокументы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в сроки, установленные статьей 931 настоящего Кодекса.\n\n2. Министерство финансов Российской Федерации вправе запросить у лица, обратившегося с заявлением о проведении взаимосогласительной процедуры, не представленные ранее документы, сведения и иную информацию, подтверждающие доводы и обстоятельства, изложенные в заявлении.\n\nДокументы, сведения и иная информация, указанные в абзаце первом настоящего пункта, представляются в Министерство финансов Российской Федерации в течение одного месяца со дня получения соответствующего запроса.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПрезидент Российской Федерации                              Б.Ельцин\n\nМосква, Кремль\n\n31 июля 1998 года","article_title":"Статья 142.9. Представление документов, сведений и иной информации в связи с проведением взаимосогласительной процедуры","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aaaa2a3ec577205bf9750d23d19cc93078b7914bb82e6f62b67d9bdcbf19c5a1"},{"code_id":"NK_RF","article_number":"15","version_date":"2000-07-31","article_text":"К местным налогам и сборам относятся:\n\n1) земельный налог;\n\n2) налог на имущество физических лиц;\n\n3) торговый сбор;\n\n4) туристический налог. (Дополнение пунктом - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 29.11.2014 № 382-ФЗ)","article_title":"Статья 15. Местные налоги и сборы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"def43125de3eec9949d5b156246e705991565b30617ddd9d3b36a688046cd437"},{"code_id":"NK_RF","article_number":"16","version_date":"2000-07-31","article_text":"(Статья в редакции Федерального закона от 29.06.2004 № 58-ФЗ)","article_title":"Статья 16. Информация о налогах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"032b5baf0f7f054f942849068e2b4f49ac78d5f24ba8891c113d47f1e39c312d"},{"code_id":"NK_RF","article_number":"17","version_date":"2000-07-31","article_text":"объект налогообложения;\n\nналоговая база;\n\nналоговый период (за исключением налогов разового характера); (В редакции  Федерального закона от 04.08.2023 № 415-ФЗ)\n\nналоговая ставка;\n\nпорядок исчисления налога;\n\nпорядок и сроки уплаты налога.","article_title":"Статья 17. Общие условия установления налогов и сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f22768d802a54ecdc362ae9b67d48c435fe3219677383440c4d81b18489ae122"},{"code_id":"NK_RF","article_number":"18","version_date":"2000-07-31","article_text":"Специальные налоговые режимы могут предусматривать особый порядок определения элементов налогообложения, а также освобождение от обязанности по уплате отдельных налогов и сборов, предусмотренных статьями 13 - 15 настоящего Кодекса.\n\n1) система налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог);\n\n2) упрощенная система налогообложения;\n\n3) (Подпункт утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n4) система налогообложения при выполнении соглашений о разделе продукции;\n\n5) патентная система налогообложения; (Дополнение подпунктом - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\n6) налог на профессиональный доход (в порядке эксперимента); (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 425-ФЗ)\n\n7) \"Автоматизированная упрощенная система налогообложения\" (в порядке эксперимента). (Дополнение подпунктом - Федеральный закон от 25.02.2022 № 18-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)\n\n(Дополнение главой - Федеральный закон от 03.07.2016 № 243-ФЗ)","article_title":"Статья 18. Специальные налоговые режимы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13bd04ecca278c5ffe172d70c91991b6a8c4d6ce19e8634fecf326813d8b68f0"},{"code_id":"NK_RF","article_number":"18.1","version_date":"2000-07-31","article_text":"1. В Российской Федерации настоящим Кодексом устанавливаются страховые взносы, которые являются федеральными и обязательны к уплате на всей территории Российской Федерации.\n\n2. Страховые взносы отменяются настоящим Кодексом.","article_title":"Статья 18.1. Страховые взносы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ae6ff853562341359590de817f392fb3bed3dde3322a2599ed6d0d2677b6bd13"},{"code_id":"NK_RF","article_number":"18.2","version_date":"2000-07-31","article_text":"1. При установлении страховых взносов определяются в соответствии с главой 34 настоящего Кодекса плательщики и следующие элементы обложения:\n\n1) объект обложения страховыми взносами;\n\n2) база для исчисления страховых взносов;\n\n3) расчетный период;\n\n4) тариф страховых взносов;\n\n5) порядок исчисления страховых взносов;\n\n6) порядок и сроки уплаты страховых взносов.\n\n2. Элементы обложения страховыми взносами, указанные в подпунктах 1 и 2 пункта 1 настоящей статьи, могут определяться применительно к отдельным категориям плательщиков страховых взносов.\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 18.2. Общие условия установления страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d966570a98e2cf6a98de6a7e0435fcb8c01cf612b76e87492a8370063eb8b20"},{"code_id":"NK_RF","article_number":"19","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНалогоплательщиками, плательщиками сборов, плательщиками страховых взносов признаются организации и физические лица, на которых в соответствии с настоящим Кодексом возложена обязанность уплачивать соответственно налоги, сборы, страховые взносы. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nВ порядке, предусмотренном настоящим Кодексом, филиалы и иные обособленные подразделения российских организаций исполняют обязанности этих организаций по уплате налогов, сборов, страховых взносов по месту нахождения этих филиалов и иных обособленных подразделений. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nВ случаях, предусмотренных настоящим Кодексом, налогоплательщиками признаются иностранные структуры без образования юридического лица. (Дополнение частью - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 19. Налогоплательщики, плательщики сборов, плательщики страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02f167f6ae00d1ce7afc9fde174831e3c152121676134601bb52d4012d95ca95"},{"code_id":"NK_RF","article_number":"20","version_date":"2000-07-31","article_text":"1) одна организация непосредственно и (или) косвенно участвует в другой организации, и суммарная доля такого участия составляет более 20 процентов. Доля косвенного участия одной ор\n\nганизации в другой через последовательность иных организаций определяется в виде произведения долей непосредственного участия организаций этой последовательности одна в другой; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) одно физическое лицо подчиняется другому физическому лицу по должностному положению;\n\n3) лица состоят в соответствии с семейным законодательством Российской Федерации в брачных отношениях, отношениях родства или свойства, усыновителя и усыновленного, а также попечителя и опекаемого.","article_title":"Статья 20. Взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea9edb5ce99d4b95bf39d454a4fdd1e909ccce6d3bf00377376d4845ec79816b"},{"code_id":"NK_RF","article_number":"21","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Налогоплательщики имеют право:\n\n1) получать по месту своего учета от налоговых органов бесплатную информацию (в том числе в письменной форме) о действующих налогах и сборах, законодательстве о налогах и сборах и принятых в соответствии с ним нормативных правовых актах, порядке исчисления и уплаты налогов и сборов, правах и обязанностях налогоплательщиков, полномочиях налоговых органов и их должностных лиц, а также получать формы налоговых деклараций (расчетов) и разъяснения о порядке их заполнения; (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n2) получать от Министерства финансов Российской Федерации письменные разъяснения по вопросам применения законодательства Российской Федерации о налогах и сборах, от финансовых органов субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" - по вопросам применения соответственно законодательства субъектов Российской Федерации о налогах и сборах, нормативных правовых актов муниципальных образований о местных налогах и сборах, нормативных правовых актов представительного органа федеральной территории \"Сириус\" о местных налогах и сборах; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n3) использовать налоговые льготы при наличии оснований и в порядке, установленном законодательством о налогах и сборах;\n\n4) получать отсрочку, рассрочку или инвестиционный налоговый кредит в порядке и на условиях, установленных настоящим Кодексом; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n5) на своевременный возврат денежных средств в размере, не превышающем положительное сальдо единого налогового счета налогоплательщика, в порядке, предусмотренном настоящим Кодексом, или зачет указанных денежных средств в счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов, в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) либо в счет исполнения решений налоговых органов, указанных в подпунктах 10 и 11 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, в порядке, предусмотренном настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n51) на осуществление сверки принадлежности сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, либо сумм денежных средств, перечисленных не в качестве единого налогового платежа, а также на получение акта такой сверки; (Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n52) на основании представленного в налоговый орган запроса получать справки о наличии по состоянию на дату такого запроса положительного, отрицательного или нулевого сальдо единого налогового счета налогоплательщика, справки о принадлежности сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, и справки об исполнении обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов на основании данных налогового органа с учетом положений подпункта 10 пункта 1 статьи 32 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n6) представлять свои интересы в отношениях, регулируемых законодательством о налогах и сборах, лично либо через своего представителя; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n7) представлять налоговым органам и их должностным лицам пояснения по исчислению и уплате налогов, а также по актам проведенных налоговых проверок;\n\n8) присутствовать при проведении выездной налоговой проверки;\n\n9) получать копии акта налоговой проверки и решений налоговых органов, а также налоговые уведомления и требования об уплате задолженности;  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) требовать от должностных лиц налоговых органов и иных уполномоченных органов соблюдения законодательства о налогах и сборах при совершении ими действий в отношении налогоплательщиков; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n11) не выполнять неправомерные акты и требования налоговых органов, иных уполномоченных органов и их должностных лиц, не соответствующие настоящему Кодексу или иным федеральным законам; (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\n\n12) обжаловать в установленном порядке акты налоговых органов, иных уполномоченных органов и действия (бездействие) их должностных лиц; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)\n\n13) на соблюдение и сохранение налоговой тайны; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n14) на возмещение в полном объеме убытков, причиненных незаконными актами налоговых органов или незаконными действиями (бездействием) их должностных лиц; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n15) на участие в процессе рассмотрения материалов налоговой проверки или иных актов налоговых органов в случаях, предусмотренных настоящим Кодексом. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nПри представлении налогоплательщиком - физическим лицом документов (сведений) в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг днем их представления считается дата их приема многофункциональным центром предоставления государственных и муниципальных услуг. При этом налогоплательщику - физическому лицу многофункциональным центром предоставления государственных и муниципальных услуг выдается расписка или иной документ, подтверждающий прием документов (сведений).\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nДокументы (сведения), которые налогоплательщики - физические лица вправе представлять в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг, а также документы (сведения), содержащие налоговую тайну, которые направляются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, налогоплательщикам - физическим лицам в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг, определяются настоящим Кодексом или перечнем, утверждаемым в соответствии с абзацем первым пункта 9 статьи 31 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nПри представлении налогоплательщиком - физическим лицом документов (сведений) в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг днем их представления считается дата их направления налогоплательщиком - физическим лицом в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг. Информация о дне представления налогоплательщиком - физическим лицом документов (сведений) в налоговый орган в электронной форме с использованием единого портала государственных и муниципальных услуг размещается в личном кабинете на едином портале государственных и муниципальных услуг.\n\nДля прекращения получения от налоговых органов документов (сведений), используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг налогоплательщики - физические лица направляют в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг уведомление о прекращении получения документов (сведений) от налоговых органов в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг (далее - уведомление о прекращении получения документов с использованием единого портала государственных и муниципальных услуг). (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nПолучение от налоговых органов документов (сведений), используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг прекращается по истечении трех дней со дня представления налогоплательщиком - физическим лицом в налоговый орган уведомления о прекращении получения документов с использованием единого портала государственных и муниципальных услуг. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nНалогоплательщики - физические лица, ранее прекратившие получение от налоговых органов документов (сведений), не содержащих налоговую тайну, используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг в соответствии с абзацем четвертым настоящего пункта, в случае направления в налоговые органы в электронной форме с использованием единого портала государственных и муниципальных услуг уведомления о необходимости получения документов с использованием единого портала государственных и муниципальных услуг получают от налоговых органов в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг документы (сведения), используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, как содержащие, так и не содержащие налоговую тайну. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nУведомление о необходимости получения документов с использованием единого портала государственных и муниципальных услуг, уведомление о прекращении получения документов с использованием единого портала государственных и муниципальных услуг подписываются усиленной неквалифицированной электронной подписью, сертификат ключа проверки которой создан и используется в инфраструктуре, обеспечивающей информационно-технологическое взаимодействие информационных систем, используемых для предоставления государственных и муниципальных услуг в электронной форме, в установленном Правительством Российской Федерации порядке.\n\nФорма уведомления о необходимости получения документов с использованием единого портала государственных и муниципальных услуг, форма уведомления о прекращении получения документов с использованием единого портала государственных и муниципальных услуг, порядки заполнения таких форм и форматы представления таких уведомлений в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере информационных технологий.\n\n(Дополнение пунктом - Федеральный закон от 14.04.2023 № 125-ФЗ)\n\n2. Налогоплательщики имеют также иные права, установленные настоящим Кодексом и другими актами законодательства о налогах и сборах.","article_title":"Статья 21. Права налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a00c2c593c17e36db2e44692f4efd9bf16e2aa18d81f00d61bac62087b4dbd32"},{"code_id":"NK_RF","article_number":"22","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nПорядок защиты прав и законных интересов налогоплательщиков (плательщиков сборов, плательщиков страховых взносов) определяется настоящим Кодексом и иными федеральными законами. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nНеисполнение или ненадлежащее исполнение обязанностей по обеспечению прав налогоплательщиков (плательщиков сборов, плательщиков страховых взносов) влечет ответственность, предусмотренную федеральными законами. (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 22. Обеспечение и защита прав налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4078d56f01e1b328819d99dd7719f0277963ef7c21877217c3b7db57af7e53ef"},{"code_id":"NK_RF","article_number":"23","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Налогоплательщики обязаны:\n\n1) уплачивать законно установленные налоги;\n\n2) встать на учет в налоговых органах, если такая обязанность предусмотрена настоящим Кодексом;\n\n3) вести в установленном порядке учет своих доходов (расходов) и объектов налогообложения, если такая обязанность предусмотрена законодательством о налогах и сборах;\n\n4) представлять в установленном порядке в налоговый орган по месту учета налоговые декларации (расчеты), уведомления об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов, уплаченных (перечисленных) в качестве единого налогового платежа, если такая обязанность предусмотрена законодательством о налогах и сборах; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) представлять в налоговый орган по месту жительства индивидуального предпринимателя, нотариуса, занимающегося частной практикой, адвоката, учредившего адвокатский кабинет, по запросу налогового органа книгу учета доходов и расходов и хозяйственных операций. В случае, если эти лица отнесены к категории крупнейших налогоплательщиков, книга учета доходов и расходов и хозяйственных операций представляется ими по запросу налогового органа в налоговый орган по месту их постановки на учет в качестве крупнейших налогоплательщиков; (В редакции  федеральных законов от 28.11.2018 № 447-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n51) представлять в налоговый орган по месту нахождения организации, у которой отсутствует обязанность представлять годовую бухгалтерскую (финансовую) отчетность, составляющую государственный информационный ресурс бухгалтерской (финансовой) отчетности в соответствии с Федеральным законом от 6 декабря 2011 года № 402-ФЗ \"О бухгалтерском учете\", годовую бухгалтерскую (финансовую) отчетность не позднее трех месяцев после окончания отчетного года, за исключением случаев, когда организация в соответствии с указанным Федеральным законом не обязана вести бухгалтерский учет, или является религиозной организацией, или является организацией, представляющей в Центральный банк Российской Федерации годовую бухгалтерскую (финансовую) отчетность, если иное не предусмотрено настоящим подпунктом.\n\nЦентральный банк Российской Федерации представляет в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, годовую бухгалтерскую (финансовую) отчетность Центрального банка Российской Федерации в составе годового баланса и отчета о финансовых результатах не позднее 15 мая года, следующего за отчетным годом;\n\n(Дополнение подпунктом - Федеральный закон от 28.11.2018 № 447-ФЗ)\n\n6) представлять в налоговые органы и их должностным лицам в случаях и в порядке, которые предусмотрены настоящим Кодексом, документы, необходимые для исчисления и уплаты налогов;\n\n7) выполнять законные требования налогового органа об устранении выявленных нарушений законодательства о налогах и сборах, а также не препятствовать законной деятельности должностных лиц налоговых органов при исполнении ими своих служебных обязанностей;\n\n8) в течение пяти лет обеспечивать сохранность данных бухгалтерского и налогового учета и других документов, необходимых для исчисления и уплаты налогов, в том числе документов, подтверждающих получение доходов, осуществление расходов (для организаций и индивидуальных предпринимателей), а также уплату (удержание) налогов, если иное не предусмотрено настоящим Кодексом; (В редакции федеральных законов от 30.09.2013 № 267-ФЗ, от 17.02.2021 № 6-ФЗ)\n\n9) нести иные обязанности, предусмотренные законодательством о налогах и сборах.\n\n2. Нал\n\nогоплательщики - организации и индивидуальные предприниматели помимо обязанностей, предусмотренных пунктом 1 настоящей статьи, обязаны сообщать в налоговый орган соответственно по месту нахождения организации, месту жительства индивидуального предпринимателя: (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n1) (Подпункт утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n11) (Дополнение подпунктом - Федеральный закон от 27.06.2011 № 162-ФЗ) (Утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n2) о своем участии в российских организациях (за исключением случаев участия в хозяйственных товариществах и обществах с ограниченной ответственностью) в случае, если доля прямого участия превышает 10 процентов, - в срок не позднее одного месяца со дня начала такого участия; (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\n3) обо всех обособленных подразделениях российской организации, созданных на территории Российской Федерации (за исключением филиалов и представительств), и изменениях в ранее сообщенные в налоговый орган сведения о таких обособленных подразделениях:\n\nв течение одного месяца со дня создания обособленного подразделения российской организации;\n\nв течение трех дней со дня изменения соответствующего сведения об обособленном подразделении российской организации;\n\n(Подпункт в редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n31) обо всех обособленных подразделениях российской организации на территории Российской Федерации, через которые прекращается деятельность этой организации (которые закрываются этой организацией):\n\nв течение трех дней со дня принятия российской организацией решения о прекращении деятельности через филиал или представительство (закрытии филиала или представительства);\n\nв течение трех дней со дня прекращения деятельности российской организации через иное обособленное подразделение (закрытия иного обособленного подразделения);\n\n(Дополнение подпунктом - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n4) (Подпункт утратил силу - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\nУказанное сообщение с приложением копий правоустанавливающих (правоудостоверяющих) документов на объекты недвижимого имущества и (или) документов, подтверждающих государственную регистрацию транспортных средств, представляется в налоговый орган в отношении каждого объекта налогообложения однократно в срок до 31 декабря года, следующего за истекшим налоговым периодом.\n\nСообщение о наличии объекта налогообложения, указанное в абзаце первом настоящего пункта, не представляется в налоговый орган в случаях, если физическое лицо получало налоговое уведомление об уплате налога в отношении этого объекта или если не получало налоговое уведомление в связи с предоставлением ему налоговой льготы.\n\nСообщение о наличии объекта налогообложения и прилагаемые к нему копии документов, указанных в настоящем пункте, могут быть представлены в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\nСообщение о наличии объекта налогообложения с приложением копий документов, подтверждающих государственную регистрацию транспортных средств, и (или) правоустанавливающих (правоудостоверяющих) документов на объекты недвижимого имущества представляется в налоговый орган в отношении каждого объекта налогообложения однократно в срок до 31 декабря года, следующего за истекшим налоговым периодом. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nСообщение о наличии объекта налогообложения не представляется в налоговый орган в случае, если организации было передано (направлено) сообщение об исчисленных налоговым органом суммах транспортного налога, налога на имущество организаций, земельного налога в отношении этого объекта или если организация применяет налоговую льготу в отношении соответствующего объекта налогообложения. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n1) о своем участии в иностранных организациях (в случае, если доля такого участия превышает 10 процентов). В целях настоящего подпункта доля участия в иностранной организации определяется в порядке, установленном статьей 1052 настоящего Кодекса;\n\n2) об учреждении иностранных структур без образования юридического лица; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n3) о контролируемых иностранных компаниях, в отношении которых они являются контролирующими лицами.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nПри наличии у иностранной организации (иностранной структуры без образования юридического лица) нескольких оснований для постановки на учет в налоговом органе сообщение представляется в налоговый орган по месту постановки на учет по выбору такой иностранной организации (иностранной структуры без образования юридического лица).\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\n34. Плательщики страховых взносов обязаны:\n\n1) уплачивать установленные настоящим Кодексом страховые взносы;\n\n2) вести учет объектов обложения страховыми взносами, сумм исчисленных страховых взносов по каждому физическому лицу, в пользу которого осуществлялись выплаты и иные вознаграждения, в соответствии с главой 34 настоящего Кодекса;\n\n3) представлять в установленном порядке в налоговый орган по месту учета расчеты по страховым взносам;\n\n4) представлять в налоговые органы и их должностным лицам в случаях и порядке, которые предусмотрены настоящим Кодексом, документы, необходимые для исчисления и уплаты страховых взносов;\n\n5) представлять в налоговые органы и их должностным лицам в случаях и порядке, которые предусмотрены настоящим Кодексом, сведения о застрахованных лицах в системе индивидуального (персонифицированного) учета;\n\n6) в течение шести лет обеспечивать сохранность документов, необходимых для исчисления и уплаты страховых взносов;\n\n7) сообщать в налоговый орган по месту нахождения российской организации - плательщика страховых взносов о наделении обособленного подразделения (включая филиал, представительство), созданного на территории Российской Федерации, которому открыт счет в банке, полномочиями (о лишении полномочий) начислять и производить выплаты и вознаграждения в пользу физических лиц в течение одного месяца со дня наделения его соответствующими полномочиями (лишения полномочий); (В редакции федеральных законов от 30.11.2016 № 401-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n8) нести иные обязанности, предусмотренные законодательством Российской Федерации о налогах и сборах.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nОбязанность лица, предусмотренная абзацем первым настоящего пункта, считается исполненной при наличии у него договора с оператором электронного документооборота на оказание услуг по обеспечению электронного документооборота (о передаче прав на использование программного обеспечения, предназначенного для обеспечения электронного документооборота) с указанным налоговым органом по месту учета этого лица и квалифицированного сертификата ключа проверки электронной подписи или при наличии такого договора и квалифицированного сертификата ключа проверки электронной подписи у уполномоченного представителя лица, которому предоставлены полномочия на получение документов от указанного налогового органа.\n\nВ случае, если получение от налогового органа документов осуществляется через уполномоченного представителя лица, на которое возложена обязанность, предусмотренная абзацем первым настоящего пункта, такая обязанность считается исполненной при наличии в указанном налоговом органе также документов, подтверждающих полномочия уполномоченного представителя лица - владельца указанного квалифицированного сертификата ключа проверки электронной подписи на получение документов от указанного налогового органа. При этом, если уполномоченным представителем лица является юридическое лицо, такая обязанность считается исполненной при наличии в указанном налоговом органе также документов, подтверждающих полномочия физического лица - владельца указанного сертификата ключа проверки электронной подписи на получение документов от указанного налогового органа (за исключением случаев, если физическое лицо является законным представителем такого юридического лица).\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nУказанное в абзаце первом настоящего пункта иностранное лицо должно обеспечить получение от налогового органа в электронной форме через личный кабинет налогоплательщика документов, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах.\n\nВ период, когда личный кабинет налогоплательщика не может использоваться таким иностранным лицом для представления в налоговый орган документов (информации), сведений, документы (информация), сведения, представление которых предусмотрено настоящим Кодексом, представляются таким иностранным лицом в налоговый орган в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nЕсли указанные сообщения переданы в электронной форме по телекоммуникационным каналам связи, такие сообщения должны быть заверены усиленной квалифицированной электронной подписью лица, представившего их, или усиленной квалифицированной электронной подписью его представителя. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 04.11.2014 № 347-ФЗ)\n\nФормы и форматы сообщений, представляемых на бумажном носителе или в электронной форме, а также порядок заполнения форм указанных сообщений утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nПорядок представления сообщений, предусмотренных пунктами 2, 21 и подпунктом 7 пункта 34 настоящей статьи, в электронной форме по телекоммуникационным каналам связи утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 02.04.2014 № 52-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 23. Обязанности налогоплательщиков (плательщиков сборов, плательщиков страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"867fdb2a895798a54a796605d747962b1fc6e7b47c8c8b6cffc2dc705d51ad37"},{"code_id":"NK_RF","article_number":"24","version_date":"2000-07-31","article_text":"Обеспечение и защита прав налоговых агентов осуществляются в соответствии со статьей 22 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n1) правильно и своевременно исчислять, удерживать из денежных средств, выплачиваемых налогоплательщикам, и перечислять налоги в бюджетную систему Российской Федерации на соответствующие счета Федерального казначейства; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n2) письменно сообщать в налоговый орган по месту своего учета о невозможности удержать налог и о сумме задолженности налогоплательщика в течение одного месяца со дня, когда налоговому агенту стало известно о таких обстоятельствах; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n3) вести учет начисленных и выплаченных налогоплательщикам доходов, исчисленных, удержанных и перечисленных в бюджетную систему Российской Федерации налогов, в том числе по каждому налогоплательщику; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n4) представлять в налоговый орган по месту своего учета документы, необходимые для осуществления контроля за правильностью исчисления, удержания и перечисления налогов;\n\n5) в течение пяти лет обеспечивать сохранность документов, необходимых для исчисления, удержания и перечисления налогов. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nние возложенных на него обязанностей налоговый агент несет ответственность в соответствии с законодательством Российской Федерации. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 24. Налоговые агенты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"875b1555248d972acf13c322e6e54cd93ff43f832394644360f5b6153c243443"},{"code_id":"NK_RF","article_number":"24.1","version_date":"2000-07-31","article_text":"1. Каждый налогоплательщик самостоятельно исполняет обязанности по уплате налога на прибыль организаций, налога на доходы физических лиц, возникающие в связи с его участием в договоре инвестиционного товарищества, с учетом особенностей, предусмотренных настоящей статьей и иными положениями настоящего Кодекса.\n\n2. Обязанность по уплате налогов и сборов, не указанных в пункте 1 настоящей статьи, но возникающих в связи с выполнением договора инвестиционного товарищества, возлагается на участника такого договора - управляющего товарища, ответственного за ведение налогового учета (далее в настоящей статье - управляющий товарищ, ответственный за ведение налогового учета).\n\n3. Управляющий товарищ, ответственный за ведение налогового учета, признается налоговым агентом по доходам иностранных лиц от участия в инвестиционном товариществе.\n\n4. Управляющий товарищ, ответственный за ведение налогового учета, обязан:\n\n1) направлять в налоговый орган по месту своего учета копию договора инвестиционного товарищества (за исключением инвестиционной декларации), сообщать о его прекращении, сообщать о выполнении, прекращении выполнения функций управляющего товарища в срок не позднее пяти дней со дня заключения указанного договора, его прекращения, начала, прекращения выполнения функций управляющего товарища;\n\n2) вести обособленный налоговый учет по операциям инвестиционного товарищества в порядке, установленном главой 25 настоящего Кодекса;\n\n3) представлять в налоговый орган по месту своего учета расчет финансового результата инвестиционного товарищества.\n\nФорма расчета финансового результата инвестиционного товарищества утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\nРасчет финансового результата инвестиционного товарищества представляется в налоговый орган в сроки, установленные настоящим Кодексом для представления налоговой декларации (расчета) по налогу на прибыль организаций;\n\n4) (Подпункт утратил силу - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n5) в порядке и в сроки, установленные договором инвестиционного товарищества, но не позднее пятнадцати дней до окончания срока представления в налоговый орган налоговых деклараций (расчетов) по налогу на прибыль организаций, установленных настоящим Кодексом, предоставлять участникам договора копию расчета финансового результата инвестиционного товарищества и сведения о приходящейся на каждого из них доле прибыли (убытка) инвестиционного товарищества.\n\nУправляющий товарищ предоставляет товарищам сведения о доле прибыли (убытка) инвестиционного товарищества, приходящейся на каждого из них, по каждому виду операций, доходы (расходы) по которым в соответствии с настоящим Кодексом определяются отдельно; (В редакции  Федерального закона от 10.07.2023 № 318-ФЗ)\n\n6) предоставлять участникам договора инвестиционного товарищества сведения, предусмотренные Федеральным законом \"Об инвестиционных товариществах\";\n\n7) в случае, если в расчет финансового результата инвестиционного товарищества вносятся уточнения, представлять уточненный расчет в налоговый орган по месту своего учета и предоставлять участникам договора копию уточненного расчета финансового результата инвестиционного товарищества в течение пяти дней с даты внесения уточнений.\n\n5. Управляющий товарищ, ответственный за ведение налогового учета, в отношениях, связанных с ведением дел инвестиционного товарищества, имеет те же права, что и налогоплательщики.\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 24.1. Участие налогоплательщика в договоре инвестиционного товарищества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d3d0f4c814e2288a7c87043571116c48d9abbee98d04d2aeaa0781006ff1b9d"},{"code_id":"NK_RF","article_number":"24.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n1) международная компания зарегистрирована в порядке редомициляции иностранной организации, которая была создана в соответствии со своим личным законом до 1 марта 2022 года, и с даты ее создания до даты регистрации международной компании в указанном порядке прошло не менее трех лет; (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n2) международная компания не позднее 15 дней со дня ее регистрации представила в налоговый орган по месту постановки на учет следующие документы и сведения:\n\nфинансовая отчетность иностранной организации, в порядке редомициляции которой зарегистрирована международная компания, за последний завершившийся до даты регистрации финансовый год, составленная в соответствии со стандартами, установленными личным законом такой иностранной организации, если иное не предусмотрено настоящим абзацем. В случае, если личным законом иностранной организации не установлен стандарт составления финансовой отчетности, такая отчетность должна быть составлена в соответствии с Международными стандартами финансовой отчетности либо иными международно признанными стандартами составления финансовой отчетности, принимаемыми иностранными фондовыми биржами и иностранными депозитарно-клиринговыми организациями, включенными в перечень иностранных финансовых посредников, для принятия решения о допуске ценных бумаг к торгам. При этом в случае, если на момент регистрации международной компании финансовая отчетность за последний завершившийся финансовый год еще не утверждена, представляется финансовая отчетность за предшествующий финансовый год; (В редакции Федерального закона от 25.12.2018 № 490-ФЗ)\n\nаудиторское заключение к финансовой отчетности, указанной в настоящем подпункте, которое не содержит отрицательного мнения или отказа в выражении мнения;\n\nсведения о контролирующих лицах международной компании, предусмотренные пунктом 5 настоящей статьи, за исключением международных компаний, указанных в пункте 4 настоящей статьи. (В редакции федеральных законов от 25.12.2018 № 490-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nДля международной компании, зарегистрированной в порядке редомициляции иностранной организации в период с 1 марта 2022 года по 31 декабря 2023 года, положения настоящего подпункта считаются выполненными, если предусмотренные настоящим подпунктом документы и сведения (за исключением сведений о контролирующих лицах международной компании) представлены такой международной компанией не позднее двенадцати месяцев со дня ее регистрации; (Дополнение абзацем - Федеральный закон от 26.03.2022 № 66-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n3) на дату регистрации международной компании в порядке редомициляции совокупная доля прямого и (или) косвенного участия контролирующих лиц составляет не менее 75 процентов от совокупной доли прямого и (или) косвенного участия контролирующих лиц иностранной организации, являвшихся таковыми по состоянию на 1 марта 2022 года и (или) ставших таковыми в период с 1 марта 2022 года до даты регистрации этой международной компании в порядке редомициляции иностранной организации в результате наследования лиц, являвшихся контролирующими лицами этой иностранной организации в период до 1 марта 2022 года.\n\nПоложения настоящего подпункта не применяются к международной компании, зарегистрированной в порядке редомициляции до 1 марта 2022 года (включительно). (Дополнение абзацем - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\n(Подпункт в редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n11. Если иное не предусмотрено пунктом 4 настоящей статьи, в целях настоящего Кодекса статус международной холдинговой компании приобретает российская организация, если она одновременно удовлетворяет следующим условиям:\n\n1) организация создана до 1 марта 2022 года и место ее нахождения на момент подачи заявления, указанного в подпункте 2 настоящего пункта, расположено на территории специального административного района, определяемого в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\" (далее в настоящем Кодексе - территория специального административного района), а также с даты создания такой организации до даты подачи указанного заявления прошло не менее трех лет; (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n2) организация представила в налоговый орган по месту постановки на учет следующие документы и сведения:\n\nзаявление о приобретении статуса международной холдинговой компании по форме (формату) и в порядке, которые утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\nдокументы, подтверждающие направление организацией уведомления, предусмотренного пунктом 12 настоящей статьи, а также документы, подтверждающие получение указанного уведомления высшим исполнительным органом субъекта Российской Федерации, на территории которого располагалось место нахождения организации до его изменения на территорию специального административного района; (В редакции  федеральных законов от 26.03.2022 № 66-ФЗ, от 19.12.2023 № 595-ФЗ)\n\nсведения о контролирующих лицах организации, указанных в пункте 5 настоящей статьи (с учетом положений пункта 13 настоящей статьи), за исключением организаций, указанных в пункте 4 настоящей статьи; (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n3) на дату подачи заявления о приобретении статуса международной холдинговой компании отсутствует поступившее в соответствии с пунктом 12 настоящей статьи от высшего исполнительного органа субъекта Российской Федерации, на территории которого располагалось место нахождения организации до его изменения на территорию специального административного района, возражение относительно приобретения организацией статуса международной холдинговой компании; (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n4) на дату подачи заявления о приобретении статуса международной холдинговой компании совокупная доля прямого и (или) косвенного участия контролирующих лиц составляет не менее 75 процентов от совокупной доли прямого и (или) косвенного участия контролирующих лиц организации, являвшихся таковыми по состоянию на 1 марта 2022 года и (или) ставших таковыми в период с 1 марта 2022 года до даты подачи такого заявления в результате наследования лиц, являвшихся контролирующими лицами этой организации в период до 1 марта 2022 года. При этом совокупная доля прямого и (или) косвенного участия контролирующих лиц организации, являвшихся таковыми по состоянию на 1 марта 2022 года, должна быть не менее 75 процентов уставного капитала этой организации по состоянию на указанную дату. (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 25.02.2022 № 18-ФЗ)\n\nВысший исполнительный орган субъекта Российской Федерации вправе направить организации и в налоговый орган по месту нахождения организации возражение относительно приобретения ею статуса международной холдинговой компании в случае, если доля поступлений от уплаты организацией налога на прибыль организаций в общей сумме доходов от поступления налога на прибыль организаций в бюджет этого субъекта Российской Федерации составляет более 1 процента (для городов федерального значения Москвы, Санкт-Петербурга и Севастополя - более 0,1 процента) хотя бы в одном из трех календарных лет, предшествующих календарному году, в котором изменено место нахождения организации на территорию специального административного района. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nОрганизация, указанная в пункте 11 настоящей статьи, у которой за каждый из трех календарных лет, предшествующих календарному году, в котором такой организацией принято решение об изменении места ее нахождения на территорию специального административного района, доля поступлений от уплаты такой организацией налога на прибыль организаций в общей сумме доходов от поступления налога на прибыль организаций в бюджет субъекта Российской Федерации, на территории которого располагается (располагалось) место нахождения организации до его изменения на территорию специального административного района, составляет менее 1 процента (для городов федерального значения Москвы, Санкт-Петербурга и Севастополя - менее 0,1 процента), вправе направить уведомление, указанное в абзаце первом настоящего пункта, в высший исполнительный орган этого субъекта Российской Федерации не позднее чем за один месяц до даты подачи заявления о приобретении статуса международной холдинговой компании. (Дополнение абзацем - Федеральный закон от 19.12.2023 № 595-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 25.02.2022 № 18-ФЗ)\n\n1) в случае принятия международной холдинговой компанией решения о реорганизации в форме присоединения (в том числе в форме присоединения к ней другого юридического лица) или слияния, за исключением случая присоединения или слияния с другой международной холдинговой компанией, которая на дату принятия решения о реорганизации отвечает условиям, предусмотренным пунктом 1 или 11 настоящей статьи; (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\n2) в случае, если в течение 365 календарных дней после регистрации международной компании в составе контролирующих лиц такой международной компании появилось новое контролирующее лицо, которое не было признано контролирующим лицом международной компании на дату ее регистрации (за исключением случая появления нового контролирующего лица (лиц) в результате наследования, реорганизации в форме выделения, разделения или преобразования лиц, которые являлись контролирующими лицами международной компании на дату ее регистрации, и случая, если новое контролирующее лицо признается налоговым резидентом Российской Федерации или является гражданином Российской Федерации); (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n21) в случае, если в течение 365 календарных дней с даты подачи организацией, указанной в пункте 11 настоящей статьи, заявления о приобретении статуса международной холдинговой компании в составе контролирующих лиц такой организации появилось новое контролирующее лицо, не признаваемое контролирующим лицом этой организации на дату подачи указанного заявления (за исключением случая появления нового контролирующего лица (лиц) в результате наследования, реорганизации в форме выделения, разделения или преобразования лиц, которые являлись контролирующими лицами этой организации на дату подачи такого заявления, и случая, если новое контролирующее лицо признается налоговым резидентом Российской Федерации или является гражданином Российской Федерации); (Дополнение подпунктом - Федеральный закон от 25.02.2022 № 18-ФЗ) (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n3) в случае прекращения статуса международной компании в соответствии с Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\"; (В редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n4) в случае, если в отношении иностранной организации, в порядке редомициляции которой зарегистрирована международная компания, не соблюдено требование, предусмотренное частью 14 статьи 5 Федерального закона от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\"; (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n5) в случае внесения в единый государственный реестр юридических лиц записи об изменении места нахождения организации, указанной в пункте 11 настоящей статьи, на территорию за пределами территории специального административного района. (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nВ случае, установленном подпунктом 4 пункта 2 настоящей статьи, международная компания утрачивает статус международной холдинговой компании по истечении срока, указанного в части 14 статьи 5 Федерального закона от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\".\n\nВ случаях, установленных подпунктами 1, 21 и 5 пункта 2 настоящей статьи, организация, указанная в пункте 11 настоящей статьи, утрачивает статус международной холдинговой компании с даты наступления наиболее раннего из событий, определенных указанными подпунктами.\n\n(Пункт в редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n1) международных компаний (организаций, указанных в пункте 11 настоящей статьи), которые по состоянию на 1 марта 2022 года являются публичными компаниями; (В редакции федеральных законов от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\nародных компаний (организаций, указанных в пункте 11 настоящей статьи), в которых совокупная доля прямого и (или) косвенного участия публичных компаний составляет 100 процентов.\n\nПоложение настоящего подпункта считается выполненным, если в отношении публичных компаний, прямо и (или) косвенно участвующих в международных компаниях, одновременно выполняются следующие условия:\n\nакции (депозитарные расписки на акции) таких публичных компаний допущены к обращению на одной или нескольких фондовых биржах, в том числе фондовых биржах, расположенных на территориях иностранных государств (за исключением государств (территорий), включенных в установленный статьей 2513-1 настоящего Кодекса перечень государств (территорий), не обеспечивающих обмен информацией для целей налогообложения с Российской Федерацией); (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\nдоля обыкновенных акций (депозитарных расписок на акции), допущенных к обращению на фондовых биржах в совокупности по всем указанным фондовым биржам, превышает 25 процентов уставного капитала, сформированного за счет обыкновенных акций (депозитарных расписок на акции), таких публичных компаний.\n\nПоложение настоящего подпункта считается выполненным, если в отношении публичных компаний, прямо и (или) косвенно участвующих в организациях, указанных в пункте 11 настоящей статьи, выполняется условие, установленное абзацем четвертым настоящего подпункта;\n\n(Подпункт в редакции Федерального закона от 26.03.2022 № 66-ФЗ)\n\n3) международных компаний (организаций, указанных в пункте 11 настоящей статьи), в которых в отношении одного или нескольких их контролирующих лиц, совокупная доля прямого и (или) косвенного участия которых по состоянию на 1 марта 2022 года составляла не менее 25 процентов, после указанной даты действовали меры ограничительного характера, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза, перечень которых определяется в соответствии с пунктом 4 статьи 207 настоящего Кодекса. Для применения положений настоящего подпункта в отношении таких контролирующих лиц в налоговый орган в порядке и сроки, указанные в подпункте 2 пункта 1 настоящей статьи, должны быть представлены сведения, предусмотренные подпунктами 1 - 3 пункта 5 настоящей статьи, с указанием доли их участия в международной компании (организации, указанной в пункте 11 настоящей статьи), указанной в настоящем подпункте, по состоянию на 1 марта 2022 года; (Дополнение подпунктом - Федеральный закон от 25.12.2018 № 490-ФЗ) (В редакции федеральных законов от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\n4) международных компаний, в которых в отношении одного или нескольких их контролирующих лиц, совокупная доля прямого и (или) косвенного участия которых по состоянию на дату регистрации соответствующей международной компании в порядке редомициляции составляла не менее 25 процентов, после указанной даты действовали меры ограничительного характера, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза, заключающиеся в установлении запретов и (или) ограничений на проведение расчетов и (или) осуществление финансовых операций, запретов или ограничений на проведение операций, связанных с заемным финансированием и (или) приобретением либо отчуждением ценных бумаг (долей в уставных капиталах). Для применения положений настоящего подпункта в отношении таких контролирующих лиц в налоговый орган в порядке и сроки, указанные в подпункте 2 пункта 1 настоящей статьи, должны быть представлены сведения, предусмотренные подпунктами 1 - 3 пункта 5 настоящей статьи, с указанием доли их участия в международной компании, указанной в настоящем подпункте, по состоянию на дату регистрации этой международной компании в порядке редомициляции. (Дополнение подпунктом - Федеральный закон от 01.05.2022 № 120-ФЗ)\n\n1) полное наименование организации или фамилия, имя, отчество (при его наличии) физического лица, являющихся контролирующим лицом международной компании (организации, указанной в пункте 11 настоящей статьи); (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\n2) регистрационный номер (номера), присвоенный контролирующему лицу в государстве (на территории) регистрации (инкорпорации, проживания), код (коды) контролирующего лица в качестве налогоплательщика в государстве (на территории) регистрации (инкорпорации, проживания) (их аналоги), адрес в государстве (на территории) регистрации (инкорпорации, проживания) контролирующего лица (при их наличии) - в отношении иностранных контролирующих лиц;\n\n3) основной государственный регистрационный номер организации, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - в отношении российских контролирующих лиц;\n\n4) доля участия контролирующего лица в международной компании (организации, указанной в пункте 11 настоящей статьи), раскрытие порядка участия контролирующего лица в международной компании (организации, указанной в пункте 11 настоящей статьи) при наличии косвенного участия с указанием следующей информации: (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nинформация, предусмотренная подпунктами 1 и 2 настоящего пункта, - в отношении каждой последующей организации, через которую (с использованием которой) реализовано косвенное участие в международной компании (организации, указанной в пункте 11 настоящей статьи); (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nдоля участия в каждой последующей организации, через которую реализовано косвенное участие в международной компании (организации, указанной в пункте 11 настоящей статьи); (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nнаименование, основной государственный регистрационный номер, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - российской организации, через которую реализовано косвенное участие в международной компании (организации, указанной в пункте 11 настоящей статьи); (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\nорганизационная форма иностранной структуры без образования юридического лица, наименование и реквизиты документа об учреждении иностранной структуры без образования юридического лица, дата учреждения (регистрации) иностранной структуры без образования юридического лица, регистрационный номер (иной идентификатор) в государстве учреждения (регистрации) иностранной структуры без образования юридического лица (при их наличии) (их аналоги) - при наличии косвенного участия в международной компании (организации, указанной в пункте 11 настоящей статьи) с использованием иностранной структуры без образования юридического лица; (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\n5) описание оснований для признания лица контролирующим лицом международной компании (организации, указанной в пункте 11 настоящей статьи); (В редакции Федерального закона от 25.02.2022 № 18-ФЗ)\n\n6) указание на то, являлось ли контролирующее лицо иностранной организации, зарегистрированной в качестве международной компании (организации, указанной в пункте 11 настоящей статьи), таковым ранее 1 марта 2022 года. (В редакции федеральных законов от 25.02.2022 № 18-ФЗ, от 26.03.2022 № 66-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 03.08.2018 № 294-ФЗ)","article_title":"Статья 24.2. Международные холдинговые компании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cf9b69552ae88418a75557ee0027e372b0802fe01bc2c35538d9b8e35090ebb"},{"code_id":"NK_RF","article_number":"25","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n(Дополнение главой - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 25. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8d4e37a9256c4ca1b2126d80a494ea26e42f46e81d2cc21cc0a6c87018bbb54"},{"code_id":"NK_RF","article_number":"25.1","version_date":"2000-07-31","article_text":"1. Консолидированной группой налогоплательщиков признается добровольное объединение налогоплательщиков налога на прибыль организаций на основе договора о создании консолидированной группы налогоплательщиков в порядке и на условиях, которые предусмотрены настоящим Кодексом, в целях исчисления и уплаты налога на прибыль организаций с учетом совокупного финансового результата хозяйственной деятельности указанных налогоплательщиков (далее - налог на прибыль организаций по консолидированной группе налогоплательщиков).\n\n2. Участником консолидированной группы налогоплательщиков признается организация, которая является стороной действующего договора о создании консолидированной группы налогоплательщиков, соответствует критериям и условиям, предусмотренным настоящим Кодексом для участников консолидированной группы налогоплательщиков.\n\n3. Ответственным участником консолидированной группы налогоплательщиков признается участник консолидированной группы налогоплательщиков, на которого в соответствии с договором о создании консолидированной группы налогоплательщиков возложены обязанности по исчислению и уплате налога на прибыль организаций по консолидированной группе налогоплательщиков и который в правоотношениях по исчислению и уплате указанного налога осуществляет те же права и несет те же обязанности, что и налогоплательщики налога на прибыль организаций.\n\n4. Документом, подтверждающим полномочия ответственного участника консолидированной группы налогоплательщиков, является договор о создании консолидированной группы налогоплательщиков, заключенный в соответствии с настоящим Кодексом и гражданским законодательством Российской Федерации.","article_title":"Статья 25.1. Общие положения о консолидированной группе налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb0f3a252216f917ee4b4d9461b997ce55a16a63ba306325a664ff2719ca9ff7"},{"code_id":"NK_RF","article_number":"25.10","version_date":"2000-07-31","article_text":"1. Реестр участников региональных инвестиционных проектов (далее в настоящей главе - реестр) ведется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, на основании решений и сведений, направляемых в порядке, предусмотренном настоящей статьей, налоговым органом по месту нахождения налогоплательщика - участника регионального инвестиционного проекта (по месту учета в качестве крупнейшего налогоплательщика) и уполномоченным органом государственной власти соответствующего субъекта Российской Федерации.\n\nВ реестре отражаются сведения об участниках региональных инвестиционных проектов, а также сведения о региональных инвестиционных проектах, содержащиеся в соответствующих инвестиционных декларациях. Порядок ведения реестра, состав сведений, содержащихся в реестре, и форма инвестиционной декларации устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Решения о включении организации в реестр, а также о внесении изменений в реестр принимаются уполномоченным органом государственной власти субъекта Российской Федерации с учетом положений статьи 2511 и пунктов 1 - 3 статьи 2512 настоящего Кодекса.\n\nРешение о прекращении статуса участника регионального инвестиционного проекта принимается налоговым органом по месту нахождения налогоплательщика - участника регионального инвестиционного проекта (по месту учета в качестве крупнейшего налогоплательщика) по основаниям, установленным пунктом 4 статьи 2512 настоящего Кодекса.\n\n3. Указанные в пункте 2 настоящей статьи решения, а также иные необходимые сведения направляются в электронной форме в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в течение трех рабочих дней со дня принятия соответствующего решения.","article_title":"Статья 25.10. Реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aa8994e12c124a860a5d3c3748c5816fd52ab9daa37953ea2cbaf883d598f9c3"},{"code_id":"NK_RF","article_number":"25.11","version_date":"2000-07-31","article_text":"1. Для включения в реестр организация направляет в уполномоченный орган государственной власти субъекта Российской Федерации составленное в произвольной форме заявление о включении в реестр с приложением следующих документов:\n\n1) копии учредительных документов организации, удостоверенные в установленном порядке;\n\n2) копия документа, подтверждающего факт внесения записи о государственной регистрации организации в Единый государственный реестр юридических лиц;\n\n3) копия свидетельства о постановке организации на учет в налоговом органе;\n\n4) инвестиционная декларация (с приложением инвестиционного проекта);\n\n5) иные документы, подтверждающие соответствие требованиям к региональным инвестиционным проектам и (или) их участникам, установленным настоящим Кодексом и (или) законами соответствующих субъектов Российской Федерации.\n\n2. В случае реализации регионального инвестиционного проекта на территориях нескольких субъектов Российской Федерации в соответствии с пунктом 2 статьи 258 настоящего Кодекса заявление о включении в реестр подается организацией в уполномоченный орган государственной власти того субъекта Российской Федерации, в котором организация стоит на учете в налоговом органе по месту своего нахождения.\n\n3. В случае, если документы, указанные в подпунктах 2 и 3 пункта 1 настоящей статьи, не представлены организацией, то по межведомственному запросу уполномоченного органа государственной власти субъекта Российской Федерации федеральный орган исполнительной власти, осуществляющий государственную регистрацию юридических лиц, физических лиц в качестве индивидуальных предпринимателей и крестьянских (фермерских) хозяйств, представляет сведения, подтверждающие факт внесения записи о государственной регистрации этой организации в Единый государственный реестр юридических лиц, а федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, представляет сведения, подтверждающие факт постановки такой организации на учет в налоговом органе.\n\n1) о принятии указанного заявления к рассмотрению;\n\n2) об отказе в принятии указанного заявления к рассмотрению в случае непредставления документов, указанных в подпунктах 1, 4 и 5 пункта 1 настоящей статьи.\n\nВ случае реализации регионального инвестиционного проекта на территориях нескольких субъектов Российской Федерации в соответствии с пунктом 2 статьи 258 настоящего Кодекса уполномоченный орган государственной власти субъекта Российской Федерации, принявший заявление о включении в реестр к рассмотрению, по согласованию с уполномоченными органами государственной власти субъектов Российской Федерации, на территориях которых реализуется региональный инвестиционный проект, принимает одно из решений, указанных в абзаце первом настоящего пункта, в течение сорока дней со дня направления организации решения о принятии заявления о включении в реестр к рассмотрению.","article_title":"Статья 25.11. Порядок включения организации в реестр","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"82b846078122d559b22820b0215e831bec727e3c901f5ed51cfdda2d0314cbe1"},{"code_id":"NK_RF","article_number":"25.12","version_date":"2000-07-31","article_text":"1. Решение о внесении изменений в реестр, не связанных с прекращением статуса участника регионального инвестиционного проекта, принимается в случае внесения изменений в инвестиционную декларацию в порядке и на условиях, которые устанавливаются законом субъекта Российской Федерации в соответствии с настоящей статьей, при условии соблюдения требований, предъявляемых к региональным инвестиционным проектам и (или) их участникам, установленных настоящим Кодексом и (или) законами соответствующих субъектов Российской Федерации.\n\n2. Внесение в инвестиционную декларацию изменений, касающихся условий реализации регионального инвестиционного проекта, осуществляется уполномоченным органом государственной власти субъекта Российской Федерации на основании заявления участника регионального инвестиционного проекта, составленного в произвольной форме, содержащего обоснование необходимости внесения таких изменений, в порядке, предусмотренном статьей 2511 настоящего Кодекса для включения организации в реестр.\n\n1) изменение цели регионального инвестиционного проекта;\n\n2) снижение общего объема финансирования регионального инвестиционного проекта в совокупности более чем на 10 процентов по отношению к уровню, заявленному в первоначальной инвестиционной декларации;\n\n3) изменение графика ежегодного объема инвестиций, исключающее возможность реализации регионального инвестиционного проекта с соблюдением установленных требований;\n\n4) в результате вносимых изменений региональный инвестиционный проект перестанет удовлетворять иным требованиям, предусмотренным настоящим Кодексом и (или) законами соответствующих субъектов Российской Федерации.\n\n1) на основании заявления участника регионального инвестиционного проекта о прекращении статуса участника регионального инвестиционного проекта - со дня, указанного в заявлении;\n\n2) на основании вступившего в силу решения по результатам налоговой проверки, проведенной в порядке, установленном настоящим Кодексом, выявившей несоответствие регионального инвестиционного проекта и (или) его участника требованиям, установленным настоящим Кодексом и (или) законодательством субъекта Российской Федерации, а также невыполнение участником регионального инвестиционного проекта обязательств, предусмотренных инвестиционной декларацией, в том числе в части сумм финансирования капитальных вложений регионального инвестиционного проекта, - со дня включения организации в реестр; (В редакции Федерального закона от 19.11.2021 № 371-ФЗ)\n\n3) в случае внесения в Единый государственный реестр юридических лиц записи о том, что организация - участник регионального инвестиционного проекта находится в процессе ликвидации, - со дня, следующего за днем внесения соответствующей записи в Единый государственный реестр юридических лиц;\n\n4) в случае прекращения деятельности организации - участника регионального инвестиционного проекта в результате реорганизации в форме слияния, разделения, присоединения к другому юридическому лицу или преобразования - со дня, следующего за днем внесения соответствующей записи в Единый государственный реестр юридических лиц;\n\n5) на основании вступившего в законную силу решения арбитражного суда о признании должника банкротом - со дня, следующего за днем вступления в законную силу такого решения.","article_title":"Статья 25.12. Внесение изменений в сведения, содержащиеся в реестре, и прекращение статуса участника регионального инвестиционного проекта","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2640e36af12f88b225557466f570a37a3d8e72b3fa5f3dc4ad5c5d43fb0662a0"},{"code_id":"NK_RF","article_number":"25.12-1","version_date":"2000-07-31","article_text":"я налоговых льгот участниками региональных инвестиционных проектов, для которых не требуется включение в реестр\n\n1. Для применения налоговых льгот по налогу на прибыль организаций и (или) по налогу на добычу полезных ископаемых организация, указанная в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, направляет в налоговый орган по месту ее нахождения (в случае, если местом ее нахождения является территория субъекта Российской Федерации, в котором реализуется региональный инвестиционный проект) либо по месту нахождения обособленного подразделения организации, расположенного на территории субъекта Российской Федерации, в котором реализуется региональный инвестиционный проект, заявления о применении налоговых льгот с указанием полного наименования налогоплательщика, его идентификационного номера и кода причины постановки на учет, а также следующих параметров инвестиционного проекта:\n\nобъем произведенных капитальных вложений в рамках регионального инвестиционного проекта;\n\nсрок, в течение которого было выполнено требование о минимальном объеме капитальных вложений в соответствии с подпунктом 41 пункта 1 статьи 258 настоящего Кодекса;\n\nнаименование товаров (группы товаров), производство которых планируется осуществлять и (или) осуществляется в результате такого инвестиционного проекта.\n\nФорма и форматы заявления о применении налоговой льготы и порядок его передачи в электронной форме по телекоммуникационным каналам связи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Заявления о применении налоговых льгот направляются организациями не позднее даты представления налоговой декларации по соответствующему налогу за налоговый период, в котором впервые заявлены пониженные налоговые ставки.\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, направляют заявления о применении налоговых льгот в налоговый орган по месту учета в качестве крупнейших налогоплательщиков.\n\n(Дополнение статьей - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n(Дополнение главой - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 25.12-1. Применение и прекращение применени","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2069432ceda4825600747d87e479d4c98b3fd71f770ea24abea67c4e47015bc2"},{"code_id":"NK_RF","article_number":"25.13","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса контролируемой иностранной компанией признается иностранная организация, удовлетворяющая одновременно всем следующим условиям:\n\n1) организация не признается налоговым резидентом Российской Федерации;\n\n2) контролирующим лицом организации являются организация и (или) физическое лицо, признаваемые налоговыми резидентами Российской Федерации.\n\n2. В целях настоящего Кодекса контролируемой иностранной компанией также признается иностранная структура без образования юридического лица, контролирующим лицом которой являются организация и (или) физическое лицо, признаваемые налоговыми резидентами Российской Федерации.\n\n3. Если иное не предусмотрено настоящей статьей, в целях настоящего Кодекса контролирующим лицом иностранной организации признаются следующие лица:\n\n1) физическое или юридическое лицо, доля участия которого в этой организации составляет более 25 процентов;\n\n2) физическое или юридическое лицо, доля участия которого в этой организации (для физических лиц - совместно с супругами и несовершеннолетними детьми) составляет более 10 процентов, если доля участия всех лиц, признаваемых налоговыми резидентами Российской Федерации, в этой организации (для физических лиц - совместно с супругами и несовершеннолетними детьми) составляет более 50 процентов.\n\n4. Лицо не признается контролирующим лицом иностранной организации, если его участие в этой иностранной организации реализовано одним из следующих способов или их комбинацией:\n\n1) через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, являющихся российскими организациями;\n\n2) через прямое и (или) косвенное участие в одной или нескольких иностранных организациях, акции которых допущены к обращению на одной или нескольких иностранных фондовых биржах, расположенных на территориях иностранных государств, являющихся членами Организации экономического сотрудничества и развития (за исключением государств (территорий), включенных в установленный статьей 2513-1 настоящего Кодекса перечень государств (территорий), не обеспечивающих обмен информацией для целей налогообложения с Российской Федерацией), и при выполнении одновременно следующих условий:\n\nдоля прямого и (или) косвенного участия контролирующего лица в каждой иностранной организации, указанной в настоящем подпункте, не превышает 50 процентов;\n\nдоля обыкновенных акций, допущенных к обращению на иностранных фондовых биржах в совокупности по всем указанным иностранным фондовым биржам, превышает 25 процентов уставного капитала, сформированного за счет обыкновенных акций, для каждой иностранной организации, указанной в настоящем подпункте.\n\nПоложения настоящего пункта не применяются в период до 1 января 2029 года в отношении иностранных организаций, участие лица в которых реализовано исключительно через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, признаваемых международными холдинговыми компаниями в соответствии со статьей 242 настоящего Кодекса.\n\n(Пункт в редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n5. Для целей пункта 3 настоящей статьи доля участия организации в другой организации или физического лица в организации определяется в соответствии с порядком, предусмотренным статьей 1052 настоящего Кодекса. При этом при определении доли физического лица в организации учитываются единоличное участие и участие совместно с супругами и несовершеннолетними детьми.\n\n1) такое лицо не вправе получать (требовать получения) прямо или косвенно прибыль (доход) этой структуры полностью или частично;\n\n2) такое лицо не вправе распоряжаться прибылью (доходом) этой структуры или ее частью;\n\n3) такое лицо не сохранило за собой права на имущество, переданное этой структуре (имущество передано этой структуре на условиях безотзывности).\n\nУсловие, установленное настоящим подпунктом в отношении лица - учредителя (основателя) иностранной структуры без образования юридического лица, признается выполненным, если это лицо не имеет права на получение активов такой структуры полностью или частично в свою собственность в соответствии с личным законом и (или) учредительными документами этой структуры на протяжении всего периода существования этой структуры, а также в случае ее прекращения (ликвидации, расторжения договора);\n\n4) такое лицо не осуществляет над этой структурой контроль в соответствии с пунктом 8 настоящей статьи.\n\n1) такое лицо имеет фактическое право на доход (его часть), получаемый такой структурой;\n\n2) такое лицо вправе распоряжаться имуществом такой структуры;\n\n3) такое лицо вправе получить имущество такой структуры в случае ее прекращения (ликвидации, расторжения договора).\n\nДля целей настоящего пункта управляющими лицами иностранного инвестиционного фонда (паевого фонда или иной формы осуществления коллективных инвестиций) признаются управляющая компания, являющаяся российской или иностранной организацией, управляющий партнер, являющийся физическим лицом или организацией, а также иные лица, осуществляющие функции по управлению активами, прямо или косвенно принадлежащими такому иностранному инвестиционному фонду (паевому фонду или иной форме осуществления коллективных инвестиций).\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n(Статья в редакции Федерального закона от 08.06.2015 № 150-ФЗ)","article_title":"Статья 25.13. Контролируемые иностранные компании и контролирующие лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9cd9da993f8975c419e6cde83d06c37e424a9659b4692a4da52dd2373a188775"},{"code_id":"NK_RF","article_number":"25.13-1","version_date":"2000-07-31","article_text":"1) она является некоммерческой организацией, которая в соответствии со своим личным законом не распределяет полученную прибыль (доход) между акционерами (участниками, учредителями) или иными лицами;\n\n2) она образована в соответствии с законодательством государства - члена Евразийского экономического союза и имеет постоянное местонахождение в этом государстве;\n\n3) эффективная ставка налогообложения доходов (прибыли) для этой иностранной организации, определяемая в соответствии с настоящей статьей по итогам периода, за который в соответствии с личным законом такой организации составляется финансовая отчетность за финансовый год, составляет не менее 75 процентов средневзвешенной налоговой ставки по налогу на прибыль организаций;\n\n4) она является одной из следующих контролируемых иностранных компаний:\n\nактивной иностранной компанией;\n\nактивной иностранной холдинговой компанией;\n\nактивной иностранной субхолдинговой компанией;\n\n5) она является банком или страховой организацией, осуществляющими деятельность в соответствии со своим личным законом на основании лицензии или иного специального разрешения на осуществление банковской или страховой деятельности;\n\n6) она является одной из следующих иностранных организаций:\n\nэмитентом обращающихся облигаций;\n\nабзац; (Утратил силу - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nорганизацией, которой были уступлены права и обязанности по выпущенным обращающимся облигациям, эмитентом которых является другая иностранная организация;\n\n7) она участвует в проектах по добыче полезных ископаемых, осуществляемых в соответствии с соглашениями о разделе продукции, концессионными соглашениями, лицензионными соглашениями или иными соглашениями (контрактами) на условиях риска.\n\nПрибыль контролируемых иностранных компаний, указанных в настоящем подпункте, освобождается от налогообложения при одновременном соблюдении всех следующих условий:\n\nиностранная организация является стороной соглашений (контрактов), указанных в абзаце первом настоящего подпункта, либо создание иностранной организации предусмотрено этими соглашениями (контрактами) и она осуществляет деятельность по добыче полезных ископаемых исключительно на основании и в соответствии с условиями указанных соглашений (контрактов);\n\nсоглашения (контракты), указанные в абзаце первом настоящего подпункта, заключены с иностранным государством (территорией), правительством соответствующего государства (территории) или с уполномоченными этим правительством институтами (органами государственной власти, государственными компаниями) либо деятельность в рамках таких соглашений (контрактов) осуществляется на основании лицензии на пользование участком недр (иного аналогичного разрешения, выданного уполномоченным органом такого государства); (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\nдоля доходов, полученных в связи с участием в соглашениях (контрактах), указанных в абзаце первом настоящего подпункта, за период, за который в соответствии с личным законом иностранной организации формируется финансовая отчетность за финансовый год, составляет не менее 90 процентов общей суммы доходов такой организации по данным ее финансовой отчетности за указанный период либо доходы у такой организации за указанный период отсутствуют или состоят исключительно из доходов в виде курсовых разниц, а также доходов, указанных в пункте 3 статьи 3091 настоящего Кодекса; (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n(Подпункт в редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n8) она является оператором нового морского месторождения углеводородного сырья или непосредственным акционером (участником) оператора нового морского месторождения углеводородного сырья;\n\n9) контролируемая иностранная компания на дату, определяемую в соответствии с пунктом 3 статьи 2515 настоящего Кодекса, признается международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 294-ФЗ)\n\n1) эффективная ставка налогообложения доходов (прибыли) иностранной организации определяется по следующей формуле:\n\nгде в целях настоящего подпункта:\n\nСтэфф - эффективная ставка налогообложения доходов (прибыли) иностранной организации;\n\nН - сумма налога с дохода (прибыли), исчисленного иностранной организацией и ее обособленными подразделениями в соответствии со своим личным законом, и налога на доходы, удержанного с доходов (прибыли) такой организации у источника выплаты таких доходов, если иное не предусмотрено подпунктом 3 настоящего пункта, за исключением налога на доходы, удержанного у источника выплаты в отношении доходов, указанных в подпункте 1 пункта 4 статьи 3091 настоящего Кодекса, источником выплаты которых являются российские организации, если контролирующее лицо такой иностранной организации имеет фактическое право на такие доходы с учетом положений статьи 312 настоящего Кодекса; (В редакции федеральных законов от 28.12.2017 № 436-ФЗ, от 09.11.2020 № 368-ФЗ)\n\nП - сумма дохода (прибыли) иностранной организации, определяемая в соответствии с абзацем первым пункта 1 статьи 2515 настоящего Кодекса, уменьшенная на сумму доходов, указанных в подпункте 1 пункта 4 статьи 3091 настоящего Кодекса, источником выплаты которых являются российские организации, если контролирующее лицо такой иностранной организации имеет фактическое право на такие доходы с учетом положений статьи 312 настоящего Кодекса. (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nПри расчете показателя Н налогоплательщик вправе произвести корректировку этого показателя на сумму налогов, которые относятся к доходам (прибыли), учтенным при расчете показателя П, и подлежат исчислению в соответствии с личным законом иностранной организации и (или) удержанию в иных периодах, отличных от периода, за который исчислен показатель П.\n\nВ случае, если по итогам налогового периода по налогу у инос\n\nтранной организации (иностранной структуры без образования юридического лица) отсутствуют доходы или если величина показателя П является отрицательной величиной либо равна нулю, расчет эффективной ставки не производится, а такая иностранная организация (иностранная структура без образования юридического лица) признается контролируемой иностранной компанией;\n\n2) средневзвешенная налоговая ставка по налогу на прибыль организаций определяется по следующей формуле:\n\nгде в целях настоящего пункта:\n\nП1 - сумма прибыли иностранной организации, определяемая в соответствии с абзацем первым пункта 1 статьи 2515 настоящего Кодекса, за вычетом доходов, указанных в подпункте 1 пункта 4 статьи 3091 настоящего Кодекса. В случае, если при исчислении показатель П1 принимает отрицательное значение, он принимается равным нулю;\n\nП2 - сумма доходов иностранной организации, указанных в подпункте 1 пункта 4 статьи 3091 настоящего Кодекса, уменьшенная на сумму доходов, источником выплаты которых являются российские организации, если контролирующее лицо этой иностранной организации имеет фактическое право на такие доходы с учетом положений статьи 312 настоящего Кодекса; (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nСт1 - ставка налога на прибыль организаций, установленная абзацем первым пункта 1 статьи 284 настоящего Кодекса;\n\nСт2 - ставка налога на прибыль организаций, установленная подпунктом 2 пункта 3 статьи 284 настоящего Кодекса;\n\n3) в случае, если контролируемая иностранная компания входит в состав консолидированной группы налогоплательщиков, созданной в соответствии с законодательством иностранного государства, либо в соответствии со своим личным законом определяет налоговую базу для исчисления и уплаты суммы налога с доходов (прибыли) совместно с иными лицами (за исключением случаев, если при определении налоговой базы сумма налога с дохода (прибыли), исчисленного непосредственно в отношении прибыли данной контролируемой иностранной компании, определяется в ее налоговой отчетности), не формируя консолидированную группу налогоплательщиков (далее в настоящем Кодексе - иностранная консолидированная группа налогоплательщиков), показатель Н для такой контролируемой иностранной компании определяется налогоплательщиком как часть суммы налога, исчисленной в отношении соответствующей иностранной консолидированной группы налогоплательщиков. При этом указанная часть суммы налога рассчитывается в порядке, устанавливаемом таким налогоплательщиком самостоятельно в учетной политике для целей налогообложения в отношении каждой иностранной консолидированной группы налогоплательщиков, на основании показателей финансовой отчетности контролируемой иностранной компании или агрегированных финансовых показателей по консолидированной группе налогоплательщиков в соответствии с одним из следующих способов:\n\nпропорционально доле выручки (дохода) контролируемой иностранной компании в совокупной выручке (доходе) иностранной консолидированной группы налогоплательщиков;\n\nпропорционально доле прибыли до налогообложения контролируемой иностранной компании в совокупной прибыли до налогообложения участников иностранной консолидированной группы налогоплательщиков, не имевших за соответствующий период убытка;\n\nпропорционально доле чистых активов контролируемой иностранной компании в совокупных чистых активах иностранной консолидированной группы налогоплательщиков.\n\nИзменение способа определения показателя Н в соответствии с настоящим подпунктом допускается не чаще одного раза в 10 лет.\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\nПри этом финансовой отчетностью для целей настоящего Кодекса признается неконсолидированная финансовая отчетность организации.\n\n1) доля прямого участия российской организации - контролирующего лица в уставном (складочном) капитале (фонде) этой иностранной организации составляет не менее 75 процентов;\n\n2) доля участия этой иностранной организации хотя бы в одной иностранной организации составляет не менее 50 процентов;\n\n3) доля участия этой иностранной организации в иных иностранных организациях (при наличии) составляет не менее 15 процентов;\n\n4) период владения долями, указанными в подпунктах 1 - 3 настоящего пункта, составляет не менее чем 365 последовательных календарных дней на дату окончания финансового года в соответствии с личным законом этой иностранной организации.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n1) доля прямого участия иностранной холдинговой компании в уставном (складочном) капитале (фонде) этой иностранной организации составляет не менее 75 процентов;\n\n2) доля участия этой иностранной организации хотя бы в одной иностранной организации составляет не менее 50 процентов;\n\n3) доля участия этой иностранной организации в иных иностранных организациях (при наличии) составляет не менее 15 процентов;\n\n4) период владения долями, указанными в подпунктах 1 - 3 настоящего пункта, составляет не менее чем 365 последовательных календарных дней на дату окончания финансового года в соответствии с личным законом этой иностранной организации.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nдивиденды от активных иностранных компаний и (или) активных иностранных субхолдинговых компаний;\n\nдивиденды от иностранных организаций, в отношении которых выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи;\n\nдоходы от реализации или иного выбытия акций (долей) активных иностранных компаний, активных иностранных субхолдинговых компаний и (или) иностранных организаций, в отношении которых выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи.\n\nПри определении доли доходов, указанной в абзаце первом настоящего пункта, налогоплательщик имеет право исключить дивиденды от иностранных организаций, указанных в абзацах втором и третьем настоящего пункта, только при условии, что доля прямого участия этой иностранной холдинговой компании в уставном (складочном) капитале (фонде) каждой иностранной организации, дивиденды от которой подлежат исключению, составляет не менее 50 процентов в течение периода, составляющего не менее чем 365 последовательных календарных дней на дату окончания финансового года в соответствии с личным законом этой иностранной холдинговой компании. Выполнение указанного условия о доле участия иностранной холдинговой компании в уставном (складочном) капитале (фонде) иностранной организации не требуется в случае, если в отношении иностранной организации выполняется условие, предусмотренное подпунктом 2 пункта 1 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nдивиденды от активных иностранных компаний;\n\nдивиденды от иностранных организаций, в отношении которых выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи;\n\nдоходы от реализации или иного выбытия акций (долей) активных иностранных компаний и (или) иностранных организаций, в отношении которых выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи.\n\nПри определении доли доходов, указанной в абзаце первом настоящего пункта, налогоплательщик имеет право исключить дивиденды от иностранных организаций, указанных в абзацах втором и третьем настоящего пункта, только при условии, что доля прямого участия этой иностранной субхолдинговой компании в уставном (складочном) капитале (фонде) каждой иностранной организации, дивиденды от которой подлежат исключению, составляет не менее 50 процентов в течение периода, составляющего не менее чем 365 последовательных календарных дней на дату окончания финансового года в соответствии с личным законом этой иностранной субхолдинговой компании. Выполнение указанного условия о доле участия иностранной субхолдинговой компании в уставном (складочном) капитале (фонде) иностранной организации не требуется в случае, если в отношении иностранной организации выполняется условие, предусмотренное подпунктом 2 пункта 1 настоящей статьи.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nОпределение доходов, указанных в абзацах втором - четвертом пункта 6 настоящей статьи, осуществляется по данным финансовой отчетности активных иностранных компаний и (или) иностранных организаций, в отношении которых выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи, составленной за год, совпадающий с финансовым годом в соответствии с личным законом иностранной субхолдинговой компании.\n\nВ случае, если контролирующее лицо прекратило участие в активной иностранной компании, активной иностранной субхолдинговой компании и (или) иностранной организации, в отношении которой выполняется хотя бы одно из условий, предусмотренных подпунктами 1 - 3 и (или) 5 - 8 пункта 1 настоящей статьи, до завершения года, совпадающего с финансовым годом в соответствии с личным законом иностранной холдинговой компании и (или) иностранной субхолдинговой компании, определение доходов, указанных в настоящем пункте, осуществляется по данным финансовой отчетности, составленной за предшествующий финансовый год.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\nПеречень государств (территорий), не обеспечивающих обмен информацией для целей налогообложения с Российской Федерацией, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nЕсли иное не предусмотрено законодательством о налогах и сборах, прибыль контролируемой иностранной компании освобождается от налогообложения в соответствии с настоящим Кодексом в случаях, установленных пунктами 5 и 6 настоящей статьи, если государство (территория) постоянного местонахождения иностранных холдинговых компаний или иностранных субхолдинговых компаний, указанных в пункте 4 настоящей статьи, не включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nПрибыль активной иностранной холдинговой компании, указанной в абзаце первом настоящего пункта, освобождается от налогообложения также у иных контролирующих лиц этой иностранной холдинговой компании, прямо или косвенно участвующих в российской организации - контролирующем лице, указанном в пункте 4 настоящей статьи, в размере, соответствующем доле участия таких лиц в указанной российской организации - контролирующем лице.\n\nПоложения настоящего пункта применяются также в отношении суммы прибыли активной иностранной субхолдинговой компании, освобождаемой от налогообложения у ее контролирующих лиц.\n\nУказанные в настоящем пункте документы представляются в срок, предусмотренный пунктом 2 статьи 2514 настоящего Кодекса, и подлежат переводу на русский язык в части, необходимой для подтверждения соблюдения условий для освобождения прибыли контролируемой иностранной компании от налогообложения. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nНалогоплательщик - контролирующее лицо вправе не представлять документы, предусмотренные настоящим пунктом, если такие документы были представлены иным налогоплательщиком - контролирующим лицом этой контролируемой иностранной компании, являющимся российской организацией, через которую реализовано косвенное участие налогоплательщика, использующего право, предусмотренное настоящим абзацем, в такой контролируемой иностранной компании. Налогоплательщик - контролирующее лицо может воспользоваться таким правом при условии указания им в уведомлении о контролируемых иностранных компаниях, представляемом в соответствии с пунктом 2 статьи 2514 настоящего Кодекса, сведений об организации, представившей документы, предусмотренные настоящим пунктом. (Дополнение абзацем - Федеральный закон от 28.12.2017 № 436-ФЗ)\n\n10. Прибыль контролируемых иностранных компаний, указанных в подпункте 6 пункта 1 настоящей статьи, освобождается от налогообложения при условии одновременного соблюдения всех следующих требований к таким компаниям, обращающимся облигациям и долговым обязательствам, возникшим в связи с размещением таких обращающихся облигаций:\n\n1) обращающиеся облигации, указанные в подпункте 6 пункта 1 настоящей статьи, отвечают требованиям, установленным к таким облигациям подпунктом 1 пункта 21 статьи 310 настоящего Кодекса;\n\n2) долговые обязательства российских и иностранных организаций перед иностранными организациями, указанными в подпункте 6 пункта 1 настоящей статьи, возникли в связи с размещением обращающихся облигаций, указанных в подпункте 1 настоящего пункта, что подтверждается хотя бы одним из следующих документов:\n\nдоговором, которым оформлено соответствующее долговое обязательство;\n\nусловиями выпуска соответствующих обращающихся облигаций;\n\nпроспектом эмиссии соответствующих обращающихся облигаций;\n\n3) иностранные организации, указанные в подпункте 6 пункта 1 настоящей статьи, имеют постоянное местонахождение в государствах, с которыми Российская Федерация имеет международные договоры, регулирующие вопросы налогообложения доходов организаций и физических лиц;\n\n4) доля процентных расходов по обращающимся облигациям, указанным в подпункте 6 пункта 1 настоящей статьи, осуществленных за период, за который в соответствии с личным законом иностранной организации составляется финансовая отчетность за финансовый год, составляет не менее 90 процентов в сумме всех расходов такой организации по данным ее финансовой отчетности за указанный период.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 08.06.2015 № 150-ФЗ)","article_title":"Статья 25.13-1. Освобождение от налогообложения прибыли контролируемой иностранной компании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8a7c4c11fb5150dff5fdb83d5f77fcdd09f42a061855c0054c5b3edcafeb682"},{"code_id":"NK_RF","article_number":"25.14","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n1. Налогоплательщики, признаваемые налоговыми резидентами Российской Федерации, в случаях и порядке, предусмотренных настоящим Кодексом, уведомляют налоговый орган:\n\n1) о своем участии в иностранных организациях (об учреждении иностранных структур без образования юридического лица);\n\n2) о контролируемых иностранных компаниях, контролирующими лицами которых они являются.\n\n2. Если иное не предусмотрено настоящей статьей, уведомление о контролируемых иностранных компаниях представляется:\n\nналогоплательщиками-организациями в срок не позднее 20 марта года, следующего за налоговым периодом, в котором контролирующим лицом признается доход в виде прибыли контролируемой иностранной компании в соответствии с главой 25 настоящего Кодекса либо который следует за годом, по итогам которого определен убыток контролируемой иностранной компании;\n\nналогоплательщиками - физическими лицами в срок не позднее 30 апреля года, следующего за налоговым периодом, в котором контролирующим лицом признается доход в виде прибыли контролируемой иностранной компании в соответствии с главой 23 настоящего Кодекса либо который следует за годом, по итогам которого определен убыток контролируемой иностранной компании.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n3. Если иное не предусмотрено настоящей статьей, уведомление об участии в иностранных организациях (об учреждении иностранных структур без образования юридического лица) (далее в настоящем\n\nКодексе - уведомление об участии в иностранных организациях) представляется в срок не позднее трех месяцев с даты возникновения (изменения доли) участия в такой иностранной организации (даты учреждения иностранной структуры без образования юридического лица), являющегося основанием для представления такого уведомления, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 19.02.2018 № 34-ФЗ)\n\nЕсли физическое лицо, не являвшееся налоговым резидентом Российской Федерации в момент возникновения оснований для представления уведомления об участии в иностранных организациях, указанных в абзаце первом настоящего пункта, признается налоговым резидентом Российской Федерации по итогам этого календарного года, то уведомление об участии в иностранных организациях представляется таким физическим лицом в срок не позднее 1 марта года, следующего за указанным календарным годом. Указанное уведомление представляется физическим лицом при наличии у него на 31 декабря календарного года, по итогам которого такое физическое лицо признается налоговым резидентом Российской Федерации, доли участия в иностранной организации, размер которой превышает размер, установленный подпунктом 1 пункта 31 статьи 23 настоящего Кодекса, либо при наличии учрежденной (зарегистрированной) таким физическим лицом на указанную дату иностранной структуры без образования юридического лица. Сведения и информация, предусмотренные пунктом 5 настоящей статьи, указываются в уведомлении об участии в иностранных организациях по состоянию на 31 декабря соответствующего календарного года.\n\nДля целей представления уведомления об участии в иностранных организациях в связи с изменением доли участия в иностранной организации применяется значение изменения доли участия в такой иностранной организации с точностью до двух знаков после запятой, при этом округление второго знака после запятой производится по правилам математического округления. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ случае, если после представления уведомления об участии в иностранных организациях основания для представления такого уведомления не изменились, повторные уведомления не представляются.\n\nВ случае прекращения участия в иностранных организациях (прекращения (ликвидации) иностранных структур без образования юридического лица) налогоплательщик информирует об этом налоговый орган в срок не позднее трех месяцев с даты прекращения участия (с указанием даты окончания участия в иностранной организации (даты прекращения (ликвидации) иностранной структуры без образования юридического лица).\n\nПоложения настоящего пункта не распространяются на налогоплательщиков, участие которых в иностранных организациях реализовано исключительно через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, являющихся российскими организациями. Освобождение от применения положений настоящего пункта, установленное настоящим абзацем, не применяется при представлении уведомления об участии в иностранных организациях за периоды до 1 января 2029 года в случае, если участие налогоплательщиков в иностранных организациях реализовано исключительно через прямое и (или) косвенное участие в одной или нескольких публичных компаниях, признаваемых международными холдинговыми компаниями в соответствии со статьей 242 настоящего Кодекса. (В редакции Федерального закона от 03.08.2018 № 294-ФЗ)\n\nМеждународная компания в течение одного месяца со дня ее регистрации представляет уведомление об участии в иностранных организациях в отношении долей участия в иностранных организациях (учреждения иностранных структур без образования юридического лица) по состоянию на дату государственной регистрации такой международной компании. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 294-ФЗ)\n\nЕсли в отношении иностранной организации или налогоплательщика, являющегося контролирующим лицом указанной иностранной организации, действуют введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, приводящие к введению принудительного внешнего управления над иностранной организацией, налогоплательщик вправе уведомить налоговый орган о прекращении участия в указанной иностранной организации. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n4. Налогоплательщики представляют уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях в налоговый орган по месту своего нахождения (месту жительства).\n\nНалогоплательщики, отнесенные в соответствии со статьей 83 настоящего Кодекса к категории крупнейших налогоплательщиков, представляют уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях в налоговый орган по месту своего учета в качестве крупнейших налогоплательщиков.\n\nУведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях представляются в налоговый орган налогоплательщиками по установленным формам (форматам) в электронной форме. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nНалогоплательщики - физические лица вправе представить указанные уведомления на бумажном носителе.\n\nФормы (форматы) уведомления об участии в иностранных организациях и уведомления о контролируемых иностранных компаниях, а также порядок заполнения форм и порядок представления уведомления об участии в иностранных организациях и о контролируемых иностранных компаниях в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n5. В уведомлении об участии в иностранных организациях указываются следующие сведения и информация:\n\n1) дата возникновения основания для представления уведомления;\n\n2) наименование иностранной организации (иностранной структуры без образования юридического лица), уведомление об участии в которой (об учреждении которой) представлено налогоплательщиком;\n\n3) регистрационный номер (номера), присвоенный иностранной организации в государстве (на территории) ее регистрации (инкорпорации), код (коды) иностранной организации в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) иностранной организации при их наличии;\n\n4) организационная форма иностранной структуры без образования юридического лица, наименование и реквизиты документа об учреждении иностранной структуры без образования юридического лица, дата учреждения (регистрации) иностранной структуры без образования юридического лица, регистрационный номер (иной идентификатор) в государстве учреждения (регистрации) иностранной структуры без образования юридического лица при их наличии (или их аналоги);\n\n5) доля участия налогоплательщика в иностранной организации, раскрытие порядка участия налогоплательщика в иностранной организации при наличии косвенного участия, в том числе через российскую организацию и (или) с использованием иностранной структуры без образования юридического лица, в случае, если налогоплательщик признается контролирующим лицом такой иностранной структуры без образования юридического лица, с указанием следующих сведений:\n\nсведения, предусмотренные подпунктами 2, 3 и 4 настоящего пункта, - в отношении каждой последующей организации (иностранной структуры без образования юридического лица), через которую (с использованием которой) реализовано косвенное участие в иностранной организации;\n\nдоля участия в каждой последующей организации, через которую реализовано косвенное участие в иностранной организации;\n\nнаименование, основной государственный регистрационный номер, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - российской организации, через которую реализовано косвенное участие в иностранной организации;\n\n6) информация о том, является ли налогоплательщик - учредитель (основатель) иностранной структуры без образования юридического лица контролирующим лицом такой структуры (в случае, если уведомление представляется налогоплательщиком в отношении учрежденной им иностранной структуры без образования юридического лица).\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n6. В уведомлении о контролируемых иностранных компаниях указываются следующие сведения и информация:\n\n1) период, за который представляется уведомление;\n\n11) дата представления в налоговый орган уведомления о переходе на уплату налога на доходы физических лиц с фиксированной прибыли (при наличии); (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n12) дата представления в налоговый орган уведомления об отказе от уплаты налога на доходы физических лиц с фиксированной прибыли (при наличии); (Дополнение подпунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n2) наименование иностранной организации (иностранной структуры без образования юридического лица), уведомление об участии в которой (об учреждении которой) представлено налогоплательщиком;\n\n3) регистрационный номер (номера), присвоенный иностранной организации в государстве (на территории) ее регистрации (инкорпорации), код (коды) иностранной организации в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) иностранной организации при их наличии;\n\n4) организационная форма иностранной структуры без образования юридического лица, наименование и реквизиты документа об учреждении иностранной структуры без образования юридического лица, дата учреждения (регистрации) иностранной структуры без образования юридического лица, регистрационный номер (иной идентификатор) в государстве учреждения (регистрации) иностранной структуры без образования юридического лица при их наличии (или их аналоги);\n\n5) дата, являющаяся последним днем периода, за который составляется финансовая отчетность организации (иностранной структуры без образования юридического лица) за финансовый год в соответствии с ее личным законом;\n\n6) дата составления финансовой отчетности организации (иностранной структуры без образования юридического лица) за финансовый год в соответствии с ее личным законом;\n\n7) дата составления аудиторского заключения по финансовой отчетности иностранной организации (иностранной структуры без образования юридического лица) за финансовый год (если в соответствии с личным законом или учредительными (корпоративными) документами этой иностранной организации (иностранной структуры без образования юридического лица) установлено обязательное проведение аудита такой финансовой отчетности или такой аудит осуществляется иностранной организацией (иностранной структурой без образования юридического лица) добровольно);\n\n8) доля участия налогоплательщика в иностранной организации, раскрытие порядка участия налогоплательщика в иностранной организации при наличии косвенного участия, в том числе через российскую организацию и (или) с использованием иностранной структуры без образования юридического лица, в случае, если налогоплательщик признается контролирующим лицом такой иностранной структуры без образования юридического лица, с указанием следующих сведений:\n\nсведения, предусмотренные подпунктами 2, 3 и 4 настоящего пункта, - в отношении каждой последующей организации (иностранной структуры без образования юридического лица), через которую (с использованием которой) реализовано косвенное участие в иностранной организации;\n\nнаименование, основной государственный регистрационный номер, идентификационный номер налогоплательщика, код причины постановки на учет налогоплательщика - российской организации, через которую реализовано косвенное участие в иностранной организации;\n\nдоля участия в каждой последующей организации, через которую реализовано косвенное участие в иностранной организации;\n\n9) описание оснований для признания налогоплательщика контролирующим лицом иностранной компании;\n\n10) описание оснований для освобождения прибыли контролируемой иностранной компании от налогообложения в соответствии с настоящим Кодексом.\n\nВ случае, если налогоплательщик воспользовался правом не представлять документы, предусмотренные пунктом 9 статьи 2513-1 настоящего Кодекса, в уведомлении о контролируемых иностранных компаниях при раскрытии информации, предусмотренной подпунктом 8 настоящего пункта, отражается информация о налогоплательщике - контролирующем лице, являющемся российской организацией, через которую реализовано косвенное участие налогоплательщика в контролируемой иностранной компании, представившем документы, предусмотренные пунктом 9 статьи 2513-1 настоящего Кодекса;\n\n(Подпункт в редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n11) о соблюдении условий освобождения от применения положений статьи 2515 настоящего Кодекса в отношении прибыли контролируемой иностранной компании в соответствии с пунктом 81 статьи 2515 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n7. В случае обнаружения неполноты сведений, неточностей либо ошибок в заполнении представленного уведомления об участии в иностранных организациях или уведомления о контролируемых иностранных компаниях налогоплательщик вправе представить уточненное уведомление.\n\nВ случае подачи уточненного уведомления до момента, когда налогоплательщик узнал об установлении налоговым органом факта отражения в уведомлении недостоверных сведений, налогоплательщик освобождается от ответственности, предусмотренной статьей 1296 настоящего Кодекса.\n\n1) наименование (фамилия, имя, отчество) налогоплательщика, которому направляется требование; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n2) наименование иностранных организаций (иностранных структур без образования юридического лица), в отношении которых у налогового органа имеется информация, свидетельствующая о том, что налогоплательщик является их контролирующим лицом;\n\n3) регистрационный номер (номера), присвоенный иностранной организации (иностранной структуре без образования юридического лица), в отношении которой у налогового органа имеется информация, свидетельствующая о том, что налогоплательщик является ее контролирующим лицом; (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n4) описание оснований, имеющихся у налогового органа, для признания налогоплательщика контролирующим лицом иностранной организации (иностранной структуры без образования юридического лица);\n\n5) период, за который налогоплательщику необходимо представить уведомление, предусмотренное пунктом 6 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nВ случае признания налогоплательщика контролирующим лицом на основании подпункта 2 пункта 3 статьи 2513 настоящего Кодекса налогоплательщик вправе представить в налоговый орган одновременно с уведомлением о контролируемых иностранных компаниях соответствующие пояснения и (или) документы, подтверждающие, что ему не было известно о том, что в календарном году, за который не было представлено уведомление о контролируемых иностранных компаниях, доля участия в иностранной организации всех лиц, признаваемых налоговыми резидентами Российской Федерации (для физических лиц - совместно с супругами и несовершеннолетними детьми), составляла более 50 процентов.\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nНалогоплательщик, признаваемый контролирующим лицом на основании подпункта 2 пункта 3 статьи 2513 настоящего Кодекса, освобождается от ответственности, предусмотренной статьями 1295 и 1296 настоящего Кодекса, в случае представления в установленный налоговым органом срок уведомления о контролируемых иностранных компаниях, информация о которых содержится в требовании. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nзации, в порядке редомициляции которой зарегистрирована международная компания, освобождается от ответственности, предусмотренной статьей 1296 настоящего Кодекса за непредставление уведомления о контролируемых иностранных компаниях, в случае, если такая иностранная организация в соответствии с ее личным законом признается фактически прекратившей свою деятельность (недействующим юридическим лицом).\n\nДля применения положений настоящего пункта налогоплательщик представляет документы, подтверждающие признание указанной в абзаце первом настоящего пункта иностранной организации в соответствии с ее личным законом фактически прекратившей свою деятельность (недействующим юридическим лицом). Такие документы представляются в срок, предусмотренный пунктом 2 настоящей статьи, и подлежат переводу на русский язык в части, необходимой для подтверждения соблюдения условия применения положений настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 595-ФЗ)","article_title":"Статья 25.14. Уведомление об участии в иностранных организациях и уведомление о контролируемых иностранных компаниях. Порядок признания налогоплательщиков контролирующими лицами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ea8538d76de7f51b28b87659b1bf4911889228dfa5b075ab3e02541e77d1c99"},{"code_id":"NK_RF","article_number":"25.14-1","version_date":"2000-07-31","article_text":"Предусмотренные настоящим пунктом документы не могут быть истребованы у налогоплательщика - контролирующего лица, являющегося физическим лицом, который представил в налоговый орган уведомление о переходе на уплату налога на доходы физических лиц с фиксированной прибыли в порядке и на условиях, которые установлены главой 23 настоящего Кодекса, если указанные документы относятся к налоговым периодам, в течение которых таким налогоплательщиком применялся установленный статьей 2272 настоящего Кодекса порядок уплаты налога на доходы физических лиц с фиксированной прибыли.\n\nНалоговый орган вправе истребовать у налогоплательщика - контролирующего лица документы, относящиеся к налоговым периодам, предшествующим году направления требования, но не более чем за три календарных года.\n\n(Дополнение статьей - Федеральный закон от 09.11.2020 № 368-ФЗ)","article_title":"Статья 25.14-1. Истребование у налогоплательщиков - контролирующих лиц документов в отношении контролируемых ими иностранных компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b0765dc847dd35f9ddbf174e2f59f25a0838d5cafceb8260f8a99edcabbbb957"},{"code_id":"NK_RF","article_number":"25.15","version_date":"2000-07-31","article_text":"1. Прибылью (убытком) контролируемой иностранной компании в целях настоящего Кодекса признается сумма прибыли (убытка) этой компании, рассчитанная в соответствии со статьей 3091 настоящего Кодекса.\n\nПрибыль контролируемой иностранной компании уменьшается на величину дивидендов, выплаченных этой иностранной компанией в календарном году, следующем за годом, за который в соответствии с личным законом такой компании составляется финансовая отчетность, с учетом промежуточных дивидендов, выплаченных в течение финансового года, за который составляется эта финансовая отчетность, с учетом особенностей, предусмотренных статьей 3091 настоящего Кодекса. В случае, если финансовая отчетность компании в соответствии с ее личным законом не составляется, для целей настоящего абзаца применяется календарный год.\n\nПри определении прибыли контролируемой иностранной компании не учитываются доходы, указанные в пункте 1 статьи 309 настоящего Кодекса, источником выплаты которых являются российские организации, если контролирующее лицо этой контролируемой иностранной компании имеет фактическое право на такие доходы с учетом положений статьи 312 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nПрибыль контролируемой иностранной компании, являющейся иностранной структурой без образования юридического лица или иностранным юридическим лицом, для которого в соответствии с его личным законом не предусмотрено участие в капитале, уменьшается на величину распределенной прибыли. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n(Пункт в редакции Федерального закона от 08.06.2015 № 150-ФЗ)\n\n11. При определении прибыли контролируемой иностранной компании, являющейся структурой без образования юридического лица, не учитываются доходы в виде имущества (включая денежные средства) и (или) имущественных прав, которые получены в качестве взноса (вклада) от учредителя (основателя) данной структуры и (или) лиц, являющихся членами его семьи и (или) близкими родственниками в соответствии с Семейным кодексом Российской Федерации (супругами, родителями и детьми, в том числе усыновителями и усыновленными, дедушками, бабушками и внуками, полнородными и неполнородными (имеющими общих отца или мать) братьями и сестрами), а также от иной контролируемой иностранной компании (в том числе иностранной структуры без образования юридического лица), в отношении которой хотя бы одно из указанных выше лиц является контролирующим лицом. При этом, если передающая сторона является контролируемой иностранной компанией, при определении прибыли этой контролируемой иностранной компании не учитываются расходы в виде переданного имущества (включая денежные средства) и (или) имущественных прав.\n\nПоложения настоящего пункта не применяются при передаче имущества и (или) имущественных прав контролируемой иностранной компанией (получении имущества и (или) имущественных прав от контролируемой иностранной компании), источником формирования которых являлась прибыль передающей стороны за финансовый год, в котором осуществлена ее ликвидация (прекращение).\n\nВ целях настоящего пункта к иностранным структурам без образования юридического лица приравниваются иностранные юридические лица, для которых в соответствии с их личным законом не предусмотрено участие в капитале.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\n12. В целях осуществления корректировок прибыли контролируемой иностранной компании, предусмотренных абзацами вторым и четвертым пункта 1 настоящей статьи, налогоплательщик - контролирующее лицо, являющийся российской организацией, вправе учесть вместо величины дивидендов (распределенной прибыли), указанных в абзаце втором или четвертом пункта 1 настоящей статьи, величину, равную сумме прибыли указанной компании, рассчитанной в соответствии со статьей 3091 настоящего Кодекса, если указанная компания одновременно удовлетворяет всем следующим условиям:\n\n1) в отношении такого налогоплательщика и (или) указанной компании либо в отношении иной контролируемой налогоплательщиком иностранной компании, являющейся акционером (участником) указанной компании, по состоянию на дату окончания календарного года, следующего за годом, за который составляется финансовая отчетность, действовали введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на проведение расчетов и (или) осуществление (исполнение) операций (сделок) и препятствующие принятию решений о распределении прибыли, объявлению и (или) осуществлению выплаты дивидендов (распределенной прибыли) указанной компанией и (или) иной контролируемой налогоплательщиком иностранной компанией, являющейся акционером (участником) указанной компании;\n\n2) выплата соответствующих дивидендов (распределенной прибыли) (в том числе в неденежной форме) указанной компанией по состоянию на дату окончания календарного года, следующего за годом, за который составляется финансовая отчетность, не производилась;\n\n3) государство (территория) постоянного места нахождения указанной компании не включено в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны), если иное не предусмотрено законодательством о налогах и сборах. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\nВ случае прекращения выполнения хотя бы одного из условий, установленных пунктом 12 настоящей статьи в отношении контролируемой иностранной компании, суммы прибыли указанной иностранной компании, которые ранее не были учтены при определении налоговой базы у налогоплательщика - контролирующего лица в результате применения положений пункта 12 настоящей статьи, подлежат учету при определении налоговой базы такого налогоплательщика за налоговый период, в котором перестало выполняться соответствующее условие (а в случае прекращения выполнения условия, указанного в подпункте 1 пункта 12 настоящей статьи, в период с 1 октября по 31 декабря за налоговый период, следующий за годом, в котором перестало выполняться это условие), в порядке, предусмотренном главой 25 настоящего Кодекса, с учетом особенностей, установленных настоящей статьей. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\nВ случае утраты налогоплательщиком, указанным в абзаце первом пункта 12 настоящей статьи, статуса контролирующего лица (за исключением случаев утраты такого статуса в результате введенных иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями мер ограничительного характера, заключающихся в лишении указанного налогоплательщика прав на прибыль (доходы) и имущество контролируемой иностранной компании) либо в случае принятия решения о ликвидации указанного налогоплательщика или контролируемой иностранной компании (за исключением случаев ликвидации контролируемой иностранной компании в результате введенных иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями мер ограничительного характера, заключающихся в лишении указанного налогоплательщика прав на прибыль (доходы) и имущество контролируемой иностранной компании) суммы прибыли, которые ранее не были учтены при определении налоговой базы у указанного налогоплательщика в результате применения положений настоящего пункта, подлежат учету при определении налоговой базы такого налогоплательщика за налоговый период, в котором произошла утрата статуса контролирующего лица либо принято решение о ликвидации, в порядке, предусмотренном главой 25 настоящего Кодекса, с учетом особенностей, установленных настоящей статьей. (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n2. Прибыль контролируемой иностранной компании, определяемая в соответствии с настоящим Кодексом, приравнивается к прибыли организации (доходу физических лиц) (далее в настоящей главе - прибыль и доход соответственно), полученной налогоплательщиком, признаваемым контролирующим лицом этой контролируемой иностранной компании, и учитывается при определении налоговой базы по налогам у налогоплательщиков, признаваемых контролирующими лицами этой контролируемой иностранной компании в соответствии с главами части второй настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\nПри невозможности определения доли прибыли контролируемой иностранной компании в соответствии с абзацем первым настоящего пункта прибыль такой контролируемой иностранной компании учитывается при определении налоговой базы у налогоплательщика - контролирующего лица исходя из суммы прибыли, на которую имеет (будет иметь) право налогоплательщик в случае ее распределения между лицами, которые обладают фактическим правом на такую прибыль. При этом такая сумма прибыли определяется на 31 декабря календарного года, следующего за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года контролируемой иностранной компании. (В редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\nВ случае, если доля участия налогоплательщика - контролирующего лица в контролируемой иностранной организации отличается от доли в прибыли, на которую налогоплательщик в случае ее распределения имеет право (в соответствии с ее личным законом, уставными документами либо соглашением между ее акционерами (участниками), прибыль контролируемой иностранной компании учитывается при определении налоговой базы у налогоплательщика - контролирующего лица в доле, соответствующей доле в прибыли контролируемой иностранной компании, на которую это лицо имеет право на дату принятия решения о распределении прибыли, принятого в календарном году, следующем за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года в соответствии с личным законом этой контролируемой иностранной компании, а в случае, если такое решение не принято, то на 31 декабря календарного года, следующего за налоговым периодом по соответствующему налогу для налогоплательщика - контролирующего лица, на который приходится дата окончания финансового года контролируемой иностранной компании. (Дополнение абзацем - Федеральный закон от 15.02.2016 № 32-ФЗ)\n\nПри этом если в результате применения абзаца первого настоящего пункта сумма прибыли контролируемой иностранной компании, подлежащая учету при определении налоговой базы у налогоплательщика - контролирующего лица, равна нулю, налогоплательщик вправе не отражать такой результат и сведения о такой контролируемой иностранной компании в налоговой декларации по налогу на прибыль организаций (налогу на доходы физических лиц). (В редакции федеральных законов от 15.02.2016 № 32-ФЗ; от 28.12.2017 № 436-ФЗ)\n\n1) финансовая отчетность контролируемой иностранной компании, составленная в соответствии с личным законом такой компании за финансовый год, или в случае отсутствия финансовой отчетности иные документы, подтверждающие прибыль (убыток) такой компании за финансовый год;\n\n2) аудиторское заключение по финансовой отчетности контролируемой иностранной компании, указанной в подпункте 1 настоящего пункта, если в соответствии с личным законом или учредительными (корпоративными) документами этой контролируемой иностранной компании установлено обязательное проведение аудита такой финансовой отчетности или аудит осуществляется иностранной организацией добровольно.\n\nУказанные в настоящем пункте документы представляются независимо от наличия обязанности по учету дохода в виде прибыли контролируемой иностранной компании в налоговой базе контролирующего лица по соответствующему налогу в следующие сроки:\n\nналогоплательщиками-организациями вместе с налоговой декларацией по налогу на прибыль организаций;\n\nналогоплательщиками - физическими лицами вместе с уведомлением о контролируемых иностранных компаниях.\n\n(Пункт в редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\nпункте 5 настоящей статьи, составленные на иностранном языке, должны быть переведены на русский язык.\n\nВ случае невозможности представления аудиторского заключения по финансовой отчетности одновременно с представлением налоговой декларации в соответствии с пунктом 5 настоящей статьи указанное аудиторское заключение представляется в срок не позднее одного месяца со дня, отраженного в уведомлении о контролируемых иностранных компаниях в качестве даты составления аудиторского заключения по финансовой отчетности.\n\n1) указанная структура в соответствии со своим личным законом является формой осуществления коллективных инвестиций;\n\n2) прибыль (доходы) указанной структуры в соответствии с ее личным законом не подлежит налогообложению;\n\n3) распределенная указанной структурой прибыль (выплаченные ею доходы) в пользу своих участников (пайщиков и иных лиц) либо бенефициаров подлежит учету при определении налоговой базы по налогам у налогоплательщиков, признаваемых контролирующими лицами этой структуры, в соответствии с главами части второй настоящего Кодекса.\n\nВ целях предусмотренного настоящим пунктом освобождения от применения положений настоящей статьи в отношении прибыли контролируемой иностранной компании налогоплательщик - контролирующее лицо представляет в налоговый орган по месту своего нахождения документы, подтверждающие соблюдение условий для такого освобождения. Указанные документы представляются в срок, предусмотренный пунктом 2 статьи 2514 настоящего Кодекса, и подлежат переводу на русский язык в части, необходимой для подтверждения соблюдения условий для освобождения от применения положений настоящей статьи в отношении прибыли контролируемой иностранной компании в соответствии с настоящим пунктом.\n\nНалогоплательщик - контролирующее лицо вправе не представлять документы, предусмотренные настоящим пунктом, если такие документы были представлены иным налогоплательщиком - контролирующим лицом этой контролируемой иностранной компании, являющимся российской организацией, через которую реализовано косвенное участие налогоплательщика, использующего право, предусмотренное настоящим абзацем, в такой контролируемой иностранной компании. Налогоплательщик - контролирующее лицо может воспользоваться данным правом при условии указания им в уведомлении о контролируемых иностранных компаниях, представляемом в соответствии с пунктом 2 статьи 2514 настоящего Кодекса, сведений об организации, представившей документы, предусмотренные настоящим пунктом.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение главой - Федеральный закон от 02.08.2019 № 269-ФЗ)","article_title":"Статья 25.15. Порядок учета прибыли контролируемой иностранной компании при налогообложении","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"68e00c866ad35c82f691f39e4695ca786d64ef3c4b9c55a680fcb1c28cecc083"},{"code_id":"NK_RF","article_number":"25.16","version_date":"2000-07-31","article_text":"Лицо приобретает статус налогоплательщика - участника специального инвестиционного контракта со дня включения сведений о заключении специального инвестиционного контракта в реестр специальных инвестиционных контрактов, предусмотренный пунктом 73 части 1 статьи 6 Федерального закона от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\" (далее в настоящей главе - реестр).\n\n1) прекращение действия специального инвестиционного контракта - со дня прекращения действия такого контракта;\n\n2) расторжение специального инвестиционного контракта - со дня включения сведений о расторжении специального инвестиционного контракта в реестр.\n\n(Дополнение главой - Федеральный закон от 28.06.2022 № 225-ФЗ)","article_title":"Статья 25.16. Налогоплательщики - участники специальных инвестиционных контрактов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"830cd8f0ffc29e987c50c59cd9b7507b4d71c5051c54a9451878028c8b512f92"},{"code_id":"NK_RF","article_number":"25.17","version_date":"2000-07-31","article_text":"1. Налогоплательщиком - участником соглашения о защите и поощрении капиталовложений для целей настоящего Кодекса признается организация, заключившая в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" соглашение о защите и поощрении капиталовложений, сведения о заключении которого включены в предусмотренный статьей 5 указанного Федерального закона реестр соглашений о защите и поощрении капиталовложений.\n\n2. Организация приобретает статус налогоплательщика - участника соглашения о защите и поощрении капиталовложений со дня включения сведений о заключении указанного соглашения в реестр соглашений о защите и поощрении капиталовложений.\n\n3. Организация утрачивает статус налогоплательщика - участника соглашения о защите и поощрении капиталовложений:\n\n1) с даты, с которой действие соглашения о защите и поощрении капиталовложений прекращается или считается прекратившимся, - в случае прекращения действия указанного соглашения согласно положениям Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\", если иное не установлено подпунктом 2 настоящего пункта;\n\n2) с даты получения статуса налогоплательщика - участника соглашения о защите и поощрении капиталовложений - в случае, если указанное соглашение расторгается по основаниям, предусмотренным частями 13 и 14 статьи 11 Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\", или признается недействительным в соответствии с гражданским законодательством.\n\n4. В случае утраты организацией статуса налогоплательщика - участника соглашения о защите и поощрении капиталовложений по основанию, предусмотренному подпунктом 2 пункта 3 настоящей статьи, суммы налогов (авансовых платежей по налогам), не уплаченные организацией в связи с применением положений пункта 43 статьи 5 настоящего Кодекса, а также в связи с применением такой организацией налоговых вычетов в порядке, установленном статьей 2518 настоящего Кодекса, подлежат восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих пеней.","article_title":"Статья 25.17. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"187d29fb1923db638c613f0cbf1335b0159146ddee71bdee4db61e0d08f805ee"},{"code_id":"NK_RF","article_number":"25.18","version_date":"2000-07-31","article_text":"1. Налогоплательщик - участник соглашения о защите и поощрении капиталовложений, одной из сторон которого является Российская Федерация, в случаях и порядке, которые предусмотрены положениями настоящей статьи и соответствующих глав части второй настоящего Кодекса, вправе уменьшать подлежащие уплате в бюджет суммы налогов (авансовых платежей по налогам) на налоговые вычеты в размере фактически осуществленных затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки (далее в целях настоящего Кодекса - налоговый вычет для СЗПК).\n\n2. В целях применения налогового вычета для СЗПК уполномоченный федеральный орган исполнительной власти, который от имени Российской Федерации подписывает соглашение о защите и поощрении капиталовложений, представляет в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомление о налоговом вычете для СЗПК. Уведомление о налоговом вычете для СЗПК должно содержать следующие сведения:\n\n1) реквизиты налогоплательщика - участника соглашения о защите и поощрении капиталовложений: полное наименование организации, адрес ее места нахождения, идентификационный номер налогоплательщика, код причины постановки на учет;\n\n2) перечень объектов учета, затраты по которым будут возмещаться за счет налогового вычета для СЗПК, формируемый раздельно по:\n\nобъектам обеспечивающей инфраструктуры, определяемым в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nобъектам сопутствующей инфраструктуры, определяемым в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nкредитам, займам;\n\nоблигационным займам;\n\nдемонтажу объектов, расположенных на территориях военных городков (в части жилищного строительства);\n\n3) общая сумма затрат, которые подлежат возмещению, с распределением их по объектам учета;\n\n4) распределение сумм налоговых вычетов для СЗПК по налогам с указанием срока применения налоговых вычетов для СЗПК. При этом в части налога на прибыль организаций суммы налоговых вычетов для СЗПК должны быть распределены в части налога на прибыль организаций, подлежащего зачислению в федеральный бюджет, и в части налога на прибыль организаций, зачисляемого в бюджет субъекта Российской Федерации. В части налога на имущество организаций и земельного налога суммы налоговых вычетов для СЗПК должны быть распределены по объектам налогообложения;\n\n5) кадастровые номера (при их отсутствии иные идентификационные номера, присвоенные в соответствии с законодательством Российской Федерации) объектов недвижимого имущества, в отношении которых будет применен налоговый вычет для СЗПК (если налоговый вычет для СЗПК применяется по налогу на имущество организаций);\n\n6) кадастровые номера земельных участков, в отношении которых будет применен налоговый вычет для СЗПК (если налоговый вычет для СЗПК применяется по земельному налогу).\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в течение десяти дней со дня получения уведомления о налоговом вычете для СЗПК направляет его в налоговый орган по месту нахождения налогоплательщика - участника соглашения о защите и поощрении капиталовложений (по месту учета в качестве крупнейшего налогоплательщика).\n\n4. Форма уведомления о налоговом вычете для СЗПК и порядок ее заполнения утверждаются Правительством Российской Федерации.\n\nФормат уведомления о налоговом вычете для СЗПК и порядок его передачи в электронной форме по телекоммуникационным каналам связи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.","article_title":"Статья 25.18. Общие вопросы применения налогоплательщиком - участником соглашения о защите и поощрении капиталовложений налоговых вычетов для соглашений о защите и поощрении капиталовложений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3dedae94aa4ce144014789e9daf11746eca722624452d34c2142a638d1b15152"},{"code_id":"NK_RF","article_number":"25.2","version_date":"2000-07-31","article_text":"1. Российские организации, соответствующие условиям, предусмотренным настоящей статьей, вправе создать консолидированную группу налогоплательщиков.\n\nУсловия, которым должны соответствовать участники консолидированной группы налогоплательщиков, предусмотренные настоящей статьей, применяются в течение всего срока действия договора о создании указанной группы, если иное не предусмотрено настоящим Кодексом.\n\n2. Консолидированная группа налогоплательщиков может быть создана организациями при условии, что одна организация непосредственно и (или) косвенно участвует в уставном (складочном) капитале других организаций и доля такого участия в каждой такой организации составляет не менее 90 процентов. Указанное условие должно соблюдаться в течение всего срока действия договора о создании консолидированной группы налогоплательщиков.\n\nДоля участия одной организации в другой организации определяется в порядке, установленном настоящим Кодексом.\n\n3. Организация - сторона договора о создании консолидированной группы налогоплательщиков должна соответствовать следующим условиям:\n\n1) организация не находится в процессе реорганизации или ликвидации, если иное не предусмотрено настоящим Кодексом; (В редакции Федерального закона от 28.11.2015 № 325-ФЗ)\n\n2) в отношении организации на дату регистрации договора о создании консолидированной группы налогоплательщиков либо на дату присоединения такой организации к существующей консолидированной группе налогоплательщиков не возбуждено производство по делу о несостоятельности (банкротстве); (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n21) в отношении организации не введена ни одна из процедур банкротства (за исключением наблюдения), предусмотренных законодательством Российской Федерации о несостоятельности (банкротстве); (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n3) размер чистых активов организации, рассчитанный на основании бухгалтерской (финансовой) отчетности на последнюю отчетную дату, предшествующую дате представления в налоговый орган документов для регистрации договора о создании (изменении) консолидированной группы налогоплательщиков, превышает размер ее уставного (складочного) капитала. Если на момент представления в налоговый орган договора о создании (изменении) консолидированной группы налогоплательщиков срок составления бухгалтерской (финансовой) отчетности на последнюю отчетную дату еще не наступил, то определение размера чистых активов или уставного (складочного) капитала производится на основании бухгалтерской (финансовой) отчетности, составленной на предшествующую отчетную дату. (В редакции федеральных законов от 29.06.2012 № 97-ФЗ; от 03.08.2018 № 302-ФЗ)\n\n4. Присоединение новой организации к существующей консолидированной группе налогоплательщиков возможно при условии, что присоединяемая организация соответствует условиям, предусмотренным пунктом 3 настоящей статьи, на дату своего присоединения.\n\n5. Все в совокупности организации, являющиеся участниками консолидированной группы налогоплательщиков, должны соответствовать следующим условиям:\n\n1) совокупная сумма налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых, уплаченная в течение календарного года, предшествующего году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, без учета сумм налогов, уплаченных в связи с перемещением товаров через таможенную границу Таможенного союза, составляет не менее 10 миллиардов рублей;\n\n2) суммарный объем выручки от продажи товаров, продукции, выполнения работ и оказания услуг, а также от прочих доходов по данным бухгалтерской (финансовой) отчетности за календарный год, предшествующий году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, составляет не менее 100 миллиардов рублей; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n3) совокупная стоимость активов по данным бухгалтерской (финансовой) отчетности на 31 декабря календарного года, предшествующего году, в котором представляются в налоговый орган документы для регистрации договора о создании консолидированной группы налогоплательщиков, составляет не менее 300 миллиардов рублей. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n6. Участниками консолидированной группы налогоплательщиков не могут являться следующие организации:\n\n1) организации, являющиеся резидентами особых экономических зон;\n\n2) организации, применяющие специальные налоговые режимы;\n\n3) банки, за исключением случая, когда все другие организации, входящие в эту группу, являются банками;\n\n4) страховые организации, за исключением случая, когда все другие организации, входящие в эту группу, являются страховыми организациями;\n\n5) негосударственные пенсионные фонды, за исключением случая, когда все другие организации, входящие в эту группу, являются негосударственными пенсионными фондами;\n\n6) профессиональные участники рынка ценных бумаг, не являющиеся банками, за исключением случая, когда все другие организации, входящие в эту группу, являются профессиональными участниками рынка ценных бумаг, не являющимися банками;\n\n7) организации, являющиеся участниками иной консолидированной группы налогоплательщиков;\n\n8) организации, не признаваемые налогоплательщиками налога на прибыль организаций, а также использующие право на освобождение от обязанностей налогоплательщика налога на прибыль организаций в соответствии с главой 25 настоящего Кодекса;\n\n9) организации, осуществляющие образовательную и (или) медицинскую деятельность и применяющие налоговую ставку 0 процентов по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса;\n\n10) организации, являющиеся налогоплательщиками налога на игорный бизнес;\n\n11) клиринговые организации;\n\n12) кредитные потребительские кооперативы; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\n13) микрофинансовые организации; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\n14) организации, являющиеся участниками свободной экономической зоны. (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 379-ФЗ)","article_title":"Статья 25.2. Условия создания консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"20b0e0ffc39d06b21fd907ba8deeeed8338a1f98c5a0342000af9bed77d921f6"},{"code_id":"NK_RF","article_number":"25.3","version_date":"2000-07-31","article_text":"1. В соответствии с договором о создании консолидированной группы налогоплательщиков организации, соответствующие условиям, установленным статьей 252 настоящего Кодекса, объединяются на добровольной основе без создания юридического лица в целях исчисления и уплаты налога на прибыль организаций по консолидированной группе налогоплательщиков в порядке и на условиях, которые установлены настоящим Кодексом.\n\n2. Договор о создании консолидированной группы налогоплательщиков должен содержать следующие положения:\n\n1) предмет договора о создании консолидированной группы налогоплательщиков;\n\n2) перечень и реквизиты организаций - участников консолидированной группы налогоплательщиков;\n\n3) наименование организации - ответственного участника консолидированной группы налогоплательщиков;\n\n4) перечень полномочий, которые участники консолидированной группы налогоплательщиков передают ответственному участнику этой группы в соответствии с настоящей главой;\n\n5) порядок и сроки исполнения обязанностей и осуществления прав ответственным участником и другими участниками консолидированной группы налогоплательщиков, не предусмотренных настоящим Кодексом, ответственность за невыполнение установленных обязанностей;\n\n6) срок, исчисляемый в календарных годах, на который создается консолидированная группа налогоплательщиков, если она создается на определенный срок, либо указание на отсутствие определенного срока, на который создается эта группа;\n\n7) показатели, необходимые для определения налоговой базы и уплаты налога на прибыль организаций по каждому участнику консолидированной группы налогоплательщиков с учетом особенностей, предусмотренных статьей 288 настоящего Кодекса. При этом выбранные показатели не подлежат изменению в течение всего срока действия договора о создании консолидированной группы налогоплательщиков. (В редакции Федерального закона от 28.11.2015 № 325-ФЗ)\n\n3. К правоотношениям, основанным на договоре о создании консолидированной группы налогоплательщиков, применяется законодательство о налогах и сборах, а в части, не урегулированной законодательством о налогах и сборах, - гражданское законодательство Российской Федерации.\n\nЛюбые положения договора о создании консолидированной группы налогоплательщиков (включая сам такой договор), если они не соответствуют законодательству Российской Федерации, могут быть признаны недействительными в судебном порядке участником этой группы или налоговым органом.\n\n4. Договор о создании консолидированной группы налогоплательщиков действует до наступления наиболее ранней из следующих дат:\n\n1) даты прекращения действия указанного договора, предусмотренной этим договором и (или) настоящим Кодексом;\n\n2) даты расторжения договора;\n\nо числа налогового периода по налогу на прибыль организаций, следующего за датой отказа налоговым органом в регистрации указанного договора.\n\n5. Договор о создании консолидированной группы налогоплательщиков подлежит регистрации в налоговом органе по месту нахождения организации - ответственного участника консолидированной группы налогоплательщиков.\n\nВ случае, если ответственный участник консолидированной группы налогоплательщиков в соответствии со статьей 83 настоящего Кодекса отнесен к категории крупнейших налогоплательщиков, договор о создании консолидированной группы налогоплательщиков подлежит регистрации в налоговом органе по месту учета указанного ответственного участника консолидированной группы в качестве крупнейшего налогоплательщика.\n\n6. Для регистрации договора о создании консолидированной группы налогоплательщиков ответственный участник этой группы представляет в налоговый орган следующие документы:\n\n1) подписанное уполномоченными лицами всех участников создаваемой консолидированной группы заявление о регистрации договора о создании консолидированной группы налогоплательщиков;\n\n2) два экземпляра договора о создании консолидированной группы налогоплательщиков;\n\n3) документы, подтверждающие выполнение условий, предусмотренных пунктами 2, 3 и 5 статьи 252 настоящего Кодекса, заверенные ответственным участником консолидированной группы налогоплательщиков, в том числе копии платежных поручений на уплату налога на добавленную стоимость, акцизов, налога на прибыль организаций и налога на добычу полезных ископаемых (копии решений налогового органа о проведении зачета по перечисленным выше налогам), бухгалтерских балансов, отчетов о финансовых результатах за предшествующий календарный год для каждого из участников группы; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n4) документы, подтверждающие полномочия лиц, подписавших договор о создании консолидированной группы налогоплательщиков.\n\n7. Документы, указанные в пункте 6 настоящей статьи, представляются в налоговый орган не позднее 30 октября года, предшествующего налоговому периоду, начиная с которого исчисляется и уплачивается налог на прибыль организаций по консолидированной группе налогоплательщиков.\n\n8. Руководитель (заместитель руководителя) налогового органа в течение одного месяца со дня представления в налоговый орган документов, указанных в пункте 6 настоящей статьи, производит регистрацию договора о создании консолидированной группы налогоплательщиков либо принимает мотивированное решение об отказе в его регистрации.\n\nПри обнаружении нарушений, устранимых в пределах срока, установленного настоящим пунктом, налоговый орган обязан уведомить о них ответственного участника консолидированной группы налогоплательщиков.\n\nДо истечения срока, установленного настоящим пунктом, ответственный участник консолидированной группы налогоплательщиков вправе устранить выявленные нарушения.\n\n9. При соблюдении условий, предусмотренных статьей 252 настоящего Кодекса и пунктами 1 - 7 настоящей статьи, налоговый орган обязан зарегистрировать договор о создании консолидированной группы налогоплательщиков и в течение пяти дней с даты его регистрации выдать один экземпляр этого договора с отметкой о его регистрации ответственному участнику консолидированной группы налогоплательщиков лично под расписку или иным способом, свидетельствующим о дате получения.\n\nВ течение пяти дней с даты регистрации договора о создании консолидированной группы налогоплательщиков информация о регистрации договора о создании консолидированной группы налогоплательщиков направляется налоговым органом в налоговые органы по месту нахождения организаций - участников консолидированной группы налогоплательщиков, а также по месту нахождения обособленных подразделений организаций - участников консолидированной группы налогоплательщиков.\n\n10. Консолидированная группа налогоплательщиков признается созданной с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором налоговым органом зарегистрирован договор о создании этой группы.\n\n11. Отказ налогового органа в регистрации договора о создании консолидированной группы налогоплательщиков допускается исключительно при наличии хотя бы одного из следующих обстоятельств:\n\n1) несоответствия условиям создания консолидированной группы налогоплательщиков, предусмотренным статьей 252 настоящего Кодекса;\n\n2) несоответствия договора о создании консолидированной группы налогоплательщиков требованиям, указанным в пункте 2 настоящей статьи;\n\n3) непредставления (представления не в полном объеме) или нарушения срока представления в уполномоченный налоговый орган документов для регистрации договора о создании консолидированной группы налогоплательщиков, предусмотренных пунктами 5 - 7 настоящей статьи;\n\n4) в случае подписания документов не уполномоченными на это лицами.\n\n12. В случае отказа налогового органа в регистрации договора о создании консолидированной группы налогоплательщиков ответственный участник консолидированной группы налогоплательщиков вправе повторно представить документы о регистрации такого договора.\n\n13. Копия решения об отказе в регистрации договора о создании консолидированной группы налогоплательщиков в течение пяти дней со дня его принятия передается налоговым органом уполномоченному представителю лица, указанного в таком договоре в качестве ответственного участника консолидированной группы налогоплательщиков, лично под расписку или иным способом, свидетельствующим о дате получения.\n\n14. Отказ в регистрации договора о создании консолидированной группы налогоплательщиков может быть обжалован лицом, указанным в таком договоре в качестве ответственного участника консолидированной группы налогоплательщиков, в порядке и сроки, которые установлены настоящим Кодексом для обжалования актов, действий или бездействия налоговых органов и их должностных лиц.\n\nПри удовлетворении заявления (жалобы), если для регистрации договора о создании консолидированной группы налогоплательщиков не имеется иных препятствий, установленных настоящей главой, налоговый орган обязан зарегистрировать указанный договор, а указанная группа признается созданной с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором такая группа подлежала регистрации в соответствии с пунктом 8 настоящей статьи.","article_title":"Статья 25.3. Договор о создании консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"098c1b7b91d9f2459d99ea7cc2c195a5b7a408ad13cf68686fa658ce7cd9cf87"},{"code_id":"NK_RF","article_number":"25.4","version_date":"2000-07-31","article_text":"1. Договор о создании консолидированной группы налогоплательщиков может быть изменен в порядке и на условиях, которые предусмотрены настоящей статьей.\n\n2. Стороны договора о создании консолидированной группы налогоплательщиков обязаны внести изменения в указанный договор в случае:\n\n1) принятия решения о ликвидации одной или нескольких организаций - участников консолидированной группы налогоплательщиков;\n\n2) принятия решения о реорганизации (в форме слияния, присоединения, выделения и разделения) одной или нескольких организаций - участников консолидированной группы налогоплательщиков;\n\n3) присоединения организации к консолидированной группе налогоплательщиков;\n\n4) выхода организации из консолидированной группы налогоплательщиков (в том числе в случаях, когда такая организация перестает удовлетворять условиям, предусмотренным статьей 252 настоящего Кодекса, включая случаи ее слияния с организацией, не являющейся участником указанной группы, разделения (выделения) организации, являющейся участником этой группы);\n\n5) принятия решения о продлении срока действия договора о создании консолидированной группы налогоплательщиков.\n\n3. Соглашение об изменении договора о создании консолидированной группы налогоплательщиков (решение о продлении срока действия указанного договора) принимается всеми участниками такой группы, включая вновь присоединяющихся участников и исключая участников, выходящих из группы.\n\n4. Соглашение об изменении договора о создании консолидированной группы налогоплательщиков (решение о продлении срока действия указанного договора) представляется для регистрации в налоговый орган в следующие сроки:\n\n1) не позднее одного месяца до начала очередного налогового периода по налогу на прибыль организаций - при внесении изменений, связанных с присоединением к группе новых участников (за исключением случаев реорганизации участников указанной группы);\n\n2) не позднее одного месяца до истечения срока действия договора о создании консолидированной группы налогоплательщиков - при принятии решения о продлении срока действия указанного договора;\n\n3) в течение одного месяца со дня возникновения обстоятельств для изменения договора о создании консолидированной группы налогоплательщиков - в прочих случаях.\n\n5. Для регистрации соглашения об изменении договора о создании консолидированной группы налогоплательщиков (решения о продлении срока действия указанного договора) ее ответственный участник представляет в налоговый орган следующие документы:\n\n1) уведомление о внесении изменений в договор;\n\n2) подписанные уполномоченными лицами участников консолидированной группы налогоплательщиков два экземпляра соглашения об изменении договора;\n\n3) документы, подтверждающие полномочия лиц, подписавших соглашение о внесении изменений в договор;\n\n4) документы, подтверждающие выполнение условий, предусмотренных статьей 252 настоящего Кодекса, с учетом внесенных изменений в договор;\n\n5) два экземпляра решения о продлении срока действия договора.\n\n6. Налоговый орган обязан зарегистрировать изменения договора о создании консолидированной группы налогоплательщиков в течение 10 дней со дня представления документов, указанных в пункте 5 настоящей статьи, и выдать уполномоченному представителю ответственного участника указанной группы один экземпляр изменений с отметкой о его регистрации.\n\n7. Основаниями для отказа в регистрации изменений договора о создании консолидированной группы налогоплательщиков являются:\n\n1) невыполнение условий, предусмотренных статьей 252 настоящего Кодекса, в отношении хотя бы одного участника консолидированной группы налогоплательщиков;\n\n2) подписание документов не уполномоченными на это лицами;\n\n3) нарушение срока представления документов на изменение указанного договора;\n\n4) непредставление (представление не в полном объеме) документов, предусмотренных пунктом 5 настоящей статьи.\n\n8. Изменения договора о создании консолидированной группы налогоплательщиков вступают в силу в следующем порядке:\n\n1) изменения договора о создании консолидированной группы налогоплательщиков, связанные с присоединением к такой группе новых организаций (за исключением случаев реорганизации участников группы), вступают в силу не ранее 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором соответствующие изменения договора зарегистрированы налоговым органом;\n\n2) изменения договора о создании консолидированной группы налогоплательщиков, связанные с выходом участников из состава такой группы, вступают в силу с 1-го числа налогового периода по налогу на прибыль организаций, в котором возникли обстоятельства для внесения соответствующих изменений в договор (если иное не предусмотрено подпунктом 3 настоящего пункта);\n\n3) изменения договора о создании консолидированной группы налогоплательщиков, связанные с выходом участников из состава такой группы, которые на момент регистрации налоговым органом соответствующих изменений договора соответствуют условиям, предусмотренным статьей 252 настоящего Кодекса, вступают в силу с 1-го числа налогового периода по налогу на прибыль организаций, следующего за календарным годом, в котором соответствующие изменения договора зарегистрированы налоговым органом;\n\n4) в прочих случаях изменения договора о создании консолидированной группы налогоплательщиков вступают в силу с даты, указанной его сторонами, но не ранее даты регистрации соответствующих изменений налоговым органом.\n\n9. Уклонение от внесения обязательных изменений в договор о создании консолидированной группы налогоплательщиков влечет прекращение действия договора с 1-го числа налогового периода по налогу на прибыль организаций, в котором соответствующие обязательные изменения договора должны были бы вступить в силу.","article_title":"Статья 25.4. Изменение договора о создании консолидированной группы налогоплательщиков и продление срока его действия","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b635c03bd04917965629637c40ba44ad855ef1f6b15adacf981b7b15447e93c"},{"code_id":"NK_RF","article_number":"25.5","version_date":"2000-07-31","article_text":"1. Ответственный участник консолидированной группы налогоплательщиков, если иное не предусмотрено настоящим Кодексом, осуществляет права и несет обязанности, предусмотренные настоящим Кодексом для налогоплательщиков налога на прибыль организаций, в отношениях, регулируемых законодательством о налогах и сборах, возникающих в связи с действием консолидированной группы налогоплательщиков.\n\n2. Ответственный участник консолидированной группы налогоплательщиков имеет право:\n\n1) представлять налоговым органам и их должностным лицам любые пояснения по исчислению и уплате налога на прибыль организаций (авансовых платежей) по консолидированной группе налогоплательщиков;\n\n2) присутствовать при проведении выездных налоговых проверок, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, по месту нахождения любого участника такой группы и его обособленных подразделений;\n\n3) получать копии актов налоговых проверок и решений налогового органа, вынесенных по результатам проверок, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, а также получать требования об уплате налога на прибыль организаций (авансовых платежей) и иные документы, связанные с действием консолидированной группы налогоплательщиков;\n\n4) участвовать при рассмотрении руководителем (заместителем руководителя) налогового органа материалов налоговых проверок и дополнительных мероприятий налогового контроля, проводимых в связи с уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков, в случаях и порядке, которые предусмотрены статьей 101 настоящего Кодекса;\n\n5) получать от налоговых органов сведения об участниках консолидированной группы налогоплательщиков, составляющие налоговую тайну;\n\n6) обжаловать в установленном порядке акты налоговых органов, иных уполномоченных органов и действия или бездействие их должностных лиц, в том числе в интересах отдельных участников консолидированной группы налогоплательщиков в связи с исполнением ими обязанностей (осуществлением прав) при исчислении налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n7) обращаться в налоговый орган с заявлением о зачете (возврате) излишне уплаченного налога на прибыль организаций по консолидированной группе налогоплательщиков.\n\n3. Ответственный участник консолидированной группы налогоплательщиков обязан:\n\n1) представлять в порядке и сроки, которые предусмотрены настоящим Кодексом, в налоговый орган для регистрации договор о создании консолидированной группы налогоплательщиков, изменения договора о создании консолидированной группы налогоплательщиков, решение или уведомление о прекращении действия консолидированной группы налогоплательщиков;\n\n2) вести налоговый учет, исчислять и уплачивать налог на прибыль организаций (авансовые платежи) по консолидированной группе налогоплательщиков в порядке, установленном главой 25 настоящего Кодекса;\n\n3) представлять в налоговый орган налоговую декларацию по налогу на прибыль организаций по консолидированной группе налогоплательщиков, а также документы, полученные от других участников этой группы, в порядке и сроки, которые установлены настоящим Кодексом;\n\n4) в случаях прекращения действия консолидированной группы налогоплательщиков и (или) выхода организации из состава консолидированной группы налогоплательщиков представлять другим участникам этой группы (в том числе вышедшим из состава группы или реорганизованным) сведения, необходимые для исчисления и уплаты налога на прибыль организаций (авансовых платежей) и составления налоговых деклараций за соответствующие отчетные и налоговый периоды, в порядке и сроки, которые предусмотрены договором о создании консолидированной группы налогоплательщиков;\n\n5) уплачивать недоимку, пени и штрафы, возникающие в связи с исполнением обязанностей налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n6) информировать участников консолидированной группы налогоплательщиков о получении требования об уплате налогов и сборов в течение пяти дней со дня его получения;\n\n7) истребовать у участников консолидированной группы налогоплательщиков документы, пояснения и иную информацию, необходимую для осуществления налоговыми органами мероприятий налогового контроля и исполнения обязанностей налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n8) представлять первичные документы, регистры налогового учета и иную информацию по консолидированной группе налогоплательщиков, истребованную в рамках мероприятий налогового контроля налоговым органом, которым зарегистрирован договор о создании указанной группы;\n\n9) представлять в налоговый орган по месту своего учета информацию о прогнозируемых поступлениях от консолидированной группы налогоплательщиков по налогу на прибыль организаций в бюджеты субъектов Российской Федерации в текущем финансовом году, на очередной финансовый год и плановый период и о факторах, оказывающих влияние на планируемые поступления налога на прибыль организаций. Указанная информация представляется по требованию налогового органа в срок не позднее 30 календарных дней со дня получения соответствующего требования. (Дополнение подпунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n4. Ответственный участник консолидированной группы налогоплательщиков в пределах предоставленных ему полномочий имеет иные права и несет другие обязанности налогоплательщика, предусмотренные настоящим Кодексом.\n\n5. Участники консолидированной группы налогоплательщиков обязаны:\n\n1) представлять (в том числе в электронной форме) ответственному участнику консолидированной группы налогоплательщиков расчеты налоговой базы по налогу на прибыль организаций в отношении полученных ими доходов и расходов, данные регистров налогового учета и иные документы, необходимые ответственному участнику указанной группы для исполнения им обязанностей и осуществления прав налогоплательщика налога на прибыль организаций по консолидированной группе налогоплательщиков; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n2) представлять в налоговые органы в установленные настоящим Кодексом сроки и порядке истребуемые документы и иную информацию при осуществлении налоговым органом мероприятий налогового контроля в связи с действием консолидированной группы налогоплательщиков;\n\n3) исполнять обязанность по уплате налога на прибыль организаций (авансовых платежей) по консолидированной группе налогоплательщиков, соответствующих пеней и штрафов в случае неисполнения или ненадлежащего исполнения такой обязанности ответственным участником этой группы в порядке, установленном статьями 45 - 47 настоящего Кодекса;\n\n4) осуществлять все действия и предоставлять все документы, необходимые для регистрации договора о создании консолидированной группы налогоплательщиков и\n\nего изменений;\n\n5) в случае несоблюдения условий, предусмотренных статьей 252 настоящего Кодекса, незамедлительно уведомить ответственного участника консолидированной группы налогоплательщиков и налоговый орган, в котором зарегистрирован договор о создании указанной группы;\n\n6) вести налоговый учет в порядке, предусмотренном главой 25 настоящего Кодекса.\n\n6. В случае неисполнения или ненадлежащего исполнения ответственным участником консолидированной группы налогоплательщиков обязанности по уплате налога на прибыль организаций (авансовых платежей, соответствующих пеней и штрафов) участник (участники) этой группы, исполнивший (исполнившие) указанную обязанность, приобретает (приобретают) право регрессного требования в размерах и порядке, которые предусмотрены гражданским законодательством Российской Федерации и договором о создании указанной группы.\n\n7. Участники консолидированной группы налогоплательщиков вправе:\n\n1) получать от ответственного участника указанной группы копии актов, решений, требований, актов сверки и иных документов, предоставленных ответственному участнику налоговым органом в связи с действием консолидированной группы налогоплательщиков;\n\n2) самостоятельно обжаловать в вышестоящий налоговый орган или в суд акты налоговых органов, действия или бездействие их должностных лиц с учетом особенностей, предусмотренных настоящим Кодексом;\n\n3) добровольно исполнять обязанность ответственного участника консолидированной группы налогоплательщиков по уплате налога на прибыль организаций по консолидированной группе налогоплательщиков;\n\n4) присутствовать при проведении налоговых проверок, проводимых в связи с исчислением и уплатой налога на прибыль организаций по консолидированной группе налогоплательщиков у такого участника, а также участвовать при рассмотрении материалов таких налоговых проверок.\n\n8. Организация при выходе из состава консолидированной группы налогоплательщиков обязана:\n\n1) внести изменения в налоговый учет с начала налогового периода по налогу на прибыль организаций, с 1-го числа которого указанная организация вышла из состава консолидированной группы налогоплательщиков, направленные на соблюдение требований главы 25 настоящего Кодекса по налоговому учету налогоплательщика, не являющегося участником консолидированной группы налогоплательщиков;\n\n2) исчислить и уплатить налог на прибыль организаций (авансовые платежи) исходя из фактически полученной прибыли за соответствующие отчетные и налоговый периоды в сроки, установленные главой 25 настоящего Кодекса применительно к налоговому периоду, с 1-го числа которого организация вышла из состава консолидированной группы налогоплательщиков;\n\n3) по окончании налогового периода, с 1-го числа которого указанная организация вышла из состава консолидированной группы налогоплательщиков, представить в налоговый орган по месту своего учета налоговую декларацию по налогу на прибыль организаций в сроки, предусмотренные главой 25 настоящего Кодекса.\n\n9. Ответственный участник консолидированной группы налогоплательщиков при выходе из состава указанной группы одного или нескольких участников обязан:\n\n1) внести соответствующие изменения в налоговый учет с начала налогового периода по налогу на прибыль организаций, в котором участник (участники) вышел (вышли) из состава консолидированной группы налогоплательщиков;\n\n2) произвести перерасчет авансовых платежей по налогу на прибыль организаций по истекшим отчетным периодам и представить в налоговый орган по месту учета уточненные налоговые декларации по налогу на прибыль организаций по консолидированной группе налогоплательщиков.\n\n10. Выход организации из состава консолидированной группы налогоплательщиков не освобождает ее от исполнения в соответствии со статьями 45 - 47 настоящего Кодекса обязанности по уплате налога на прибыль организаций, соответствующих пеней и штрафов, возникших в период, когда организация являлась участником такой группы.\n\nНастоящее положение применяется независимо от того, было или не было известно указанной организации до ее выхода из состава консолидированной группы налогоплательщиков о неисполнении указанной обязанности или нарушении законодательства Российской Федерации о налогах и сборах либо соответствующие обстоятельства стали известны организации после ее выхода из состава консолидированной группы налогоплательщиков.\n\n11. Пункты 8 - 10 настоящей статьи применяются также в случае прекращения действия консолидированной группы налогоплательщиков до истечения срока, на который она была создана.","article_title":"Статья 25.5. Права и обязанности ответственного участника и других участников консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c1c9ff474a2cfbcfd2467bb786ef9c5c89a15b141e67880725ef4be330e4c896"},{"code_id":"NK_RF","article_number":"25.6","version_date":"2000-07-31","article_text":"1. Консолидированная группа налогоплательщиков прекращает действовать при наличии хотя бы одного из следующих обстоятельств:\n\n1) окончание срока действия договора о создании консолидированной группы налогоплательщиков;\n\n2) расторжение договора о создании консолидированной группы налогоплательщиков по соглашению сторон;\n\n3) вступление в законную силу решения суда о признании договора о создании консолидированной группы налогоплательщиков недействительным;\n\n4) непредставление в налоговый орган в установленные сроки соглашения об изменении договора о создании консолидированной группы налогоплательщиков в связи с выходом из состава указанной группы организации, нарушившей условия, установленные статьей 252 настоящего Кодекса;\n\n5) реорганизация (за исключением реорганизации в форме преобразования), ликвидация ответственного участника консолидированной группы налогоплательщиков;\n\n6) введение в отношении ответственного участника консолидированной группы налогоплательщиков одной из процедур банкротства (за исключением наблюдения), предусмотренных законодательством Российской Федерации о несостоятельности (банкротстве); (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n7) несоответствие ответственного участника консолидированной группы налогоплательщиков условиям, предусмотренным статьей 252 настоящего Кодекса;\n\n8) уклонение от внесения обязательных изменений в договор о создании консолидированной группы налогоплательщиков.\n\n2. Приобретение (продажа) акций (долей) в уставном (складочном) капитале (фонде) организации - участника консолидированной группы налогоплательщиков, не приводящее к нарушению условий, предусмотренных пунктом 2 статьи 252 настоящего Кодекса, не влечет прекращения действия консолидированной группы налогоплательщиков.\n\n3. При наличии обстоятельства, указанного в подпункте 2 пункта 1 настоящей статьи, ответственный участник консолидированной группы налогоплательщиков обязан направить в налоговый орган, зарегистрировавший договор о создании этой группы, решение о прекращении действия такой группы, подписанное уполномоченными представителями всех организаций - участников консолидированной группы налогоплательщиков, в срок не позднее пяти дней со дня принятия соответствующего решения.\n\nПри наличии обстоятельств, указанных в подпунктах 1, 3 - 7 пункта 1 настоящей статьи, ответственный участник консолидированной группы налогоплательщиков обязан направить в налоговый орган, зарегистрировавший договор о создании этой группы, уведомление, составленное в произвольной форме, с указанием даты возникновения таких обстоятельств.\n\nВ течение пяти дней с даты получения документов, указанных в абзацах первом и втором настоящего пункта, информация о прекращении действия консолидированной группы налогоплательщиков направляется налоговым органом в налоговые органы по месту нахождения организаций - участников консолидированной группы налогоплательщиков, а также по месту нахождения обособленных подразделений организаций - участников консолидированной группы налогоплательщиков.\n\n4. Консолидированная группа налогоплательщиков прекращает действие с 1-го числа налогового периода по налогу на прибыль организаций, следующего за налоговым периодом, в котором возникли обстоятельства, указанные в пункте 1 настоящей статьи, если иное не предусмотрено настоящим Кодексом.\n\n5. При наличии основания, предусмотренного подпунктом 3 пункта 1 настоящей статьи, консолидированная группа налогоплательщиков прекращает действие с 1-го числа отчетного периода по налогу на прибыль организаций, в котором вступило в законную силу решение суда, указанное в подпункте 3 пункта 1 настоящей статьи.\n\n6. При наличии основания, предусмотренного подпунктом 4 пункта 1 настоящей статьи, консолидированная группа налогоплательщиков прекращает действие с 1-го числа налогового периода по налогу на прибыль организаций, в котором участник этой группы нарушил условия, установленные статьей 252 настоящего Кодекса.\n\n(Дополнение главой - Федеральный закон от 30.09.2013 № 268-ФЗ)","article_title":"Статья 25.6. Прекращение действия консолидированной группы налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b921b9c77b0d086fde707f032fab66a7d64d5dc584db44a3d0587d544a1b5cd6"},{"code_id":"NK_RF","article_number":"25.7","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса организация признается оператором нового морского месторождения углеводородного сырья в случае, если такая организация одновременно удовлетворяет следующим условиям:\n\n1) в уставном капитале организации прямо или косвенно участвует организация, владеющая лицензией на пользование участком недр, в границах которого предполагается осуществлять поиск, оценку, разведку и (или) разработку нового морского месторождения углеводородного сырья, либо организация, являющаяся взаимозависимым лицом с организацией, владеющей такой лицензией;\n\n2) организация осуществляет хотя бы один из видов деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, собственными силами и (или) с привлечением подрядных организаций;\n\n3) организация осуществляет деятельность, связанную с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, на основе договора, заключенного с владельцем лицензии в отношении нового морского месторождения углеводородного сырья и (или) участка недр, указанного в подпункте 1 настоящего пункта, и такой договор предусматривает выплату организации-оператору вознаграждения, размер которого зависит в том числе от объема добытого углеводородного сырья на соответствующем морском месторождении углеводородного сырья и (или) выручки от реализации этого сырья (далее в настоящем Кодексе - операторский договор).\n\n2. Организация признается оператором нового морского месторождения углеводородного сырья с даты заключения операторского договора, указанного в подпункте 3 пункта 1 настоящей статьи, если налоговый орган был уведомлен о заключении договора в соответствии с пунктом 3 настоящей статьи.\n\n3. Организация - владелец лицензии на пользование участком недр, указанная в подпункте 3 пункта 1 настоящей статьи, в течение десяти рабочих дней с даты заключения операторского договора уведомляет налоговый орган по месту своего учета о заключении операторского договора путем представления в налоговый орган следующих документов:\n\n1) уведомления о заключении операторского договора с указанием информации о новых морских месторождениях углеводородного сырья (при наличии такой информации на дату представления уведомления);\n\n2) заверенной копии подписанного операторского договора;\n\n3) копии лицензии на пользование участком недр, в границах которого осуществляются поиск, оценка, разведка и (или) разработка новых морских месторождений углеводородного сырья или расположено (расположены) новое морское месторождение (новые морские месторождения) углеводородного сырья.\n\n4. В целях настоящего Кодекса не допускается, чтобы одновременно на одном и том же новом морском месторождении углеводородного сырья осуществляли деятельность, связанную с добычей углеводородного сырья на указанном новом морском месторождении углеводородного сырья, два и более оператора нового морского месторождения углеводородного сырья.\n\nВ случае заключения организацией - владельцем лицензии на пользование участком недр, в границах которого осуществляются поиск, оценка, разведка и (или) разработка нового морского месторождения углеводородного сырья, нового операторского договора с иной организацией, одновременно удовлетворяющей условиям, установленным пунктом 1 настоящей статьи, указанная иная организация получает статус оператора нового морского месторождения углеводородного сырья в целях настоящего Кодекса с даты уведомления налогового органа о заключении операторского договора в соответствии с пунктом 3 настоящей статьи.\n\n5. Для целей настоящего Кодекса организация утрачивает статус оператора нового морского месторождения углеводородного сырья при наступлении наиболее ранней из следующих дат:\n\n1) даты прекращения действия операторского договора, предусмотренной указанным договором;\n\n2) даты истечения срока лицензии на пользование участком недр, в границах которого расположено указанное новое морское месторождение углеводородного сырья, или прекращения права пользования таким участком недр по иным основаниям, предусмотренным законом;\n\n3) даты ликвидации организации - владельца лицензии на пользование участком недр, в границах которого расположено указанное новое морское месторождение углеводородного сырья.\n\n(Дополнение главой - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 25.7. Оператор нового морского месторождения углеводородного сырья","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f440652f0aeef172371557725dfe3f13d199c874e33069263153b5763ebaf42"},{"code_id":"NK_RF","article_number":"25.8","version_date":"2000-07-31","article_text":"1) производство товаров в результате реализации такого инвестиционного проекта осуществляется, если иное не предусмотрено настоящей статьей, исключительно на территории одного из следующих субъектов Российской Федерации:\n\nРеспублика Бурятия,\n\nРеспублика Саха (Якутия),\n\nРеспублика Тыва,\n\nАбзац, (Утратил силу - Федеральный закон от 03.08.2018 № 279-ФЗ)\n\nЗабайкальский край,\n\nКамчатский край,\n\nКрасноярский край,\n\nПриморский край,\n\nХабаровский край,\n\nАмурская область,\n\nИркутская область,\n\nМагаданская область,\n\nСахалинская область,\n\nЕврейская автономная область,\n\nЧукотский автономный округ;\n\n(Подпункт в редакции Федерального закона от 04.06.2014 № 139-ФЗ)\n\n11) производство товаров в результате реализации такого инвестиционного проекта осуществляется, если иное не предусмотрено настоящей статьей, исключительно на территории одного из субъектов Российской Федерации, не указанных в подпункте 1 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n2) региональный инвестиционный проект не может быть направлен на следующие цели:\n\nдобыча и (или) переработка нефти, добыча природного газа и (или) газового конденсата, оказание услуг по транспортировке нефти и (или) нефтепродуктов, газа и (или) газового конденсата;\n\nпроизводство подакцизных товаров (за исключением легковых автомобилей, мотоциклов, стали жидкой, этана, сжиженного углеводородного газа, нефтяного сырья, состоящего из одного компонента - газового конденсата стабильного и полученного в рамках единого технологического процесса по производству этана и (или) сжиженного углеводородного газа); (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nосуществление деятельности, по которой применяется налоговая ставка по налогу на прибыль организаций в размере 0 процентов;\n\n3) (Подпункт утратил силу - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n4) объем капитальных вложений, определяющих сумму финансирования регионального инвестиционного проекта, в соответствии с инвестиционной декларацией не может быть менее: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n50 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий трех лет со дня включения организации в реестр участников региональных инвестиционных проектов;\n\n500 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий пяти лет со дня включения организации в реестр участников региональных инвестиционных проектов;\n\n41) объем капитальных вложений, определяющих сумму финансирования регионального инвестиционного проекта и осуществленных российскими организациями, указанными в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, не может быть менее: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n50 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий трех лет со дня начала осуществления капитальных вложений в рамках реализации регионального инвестиционного проекта, но не ранее 1 января 2013 года и не ранее трех лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса;\n\n500 миллионов рублей при условии осуществления капитальных вложений в срок, не превышающий пяти лет со дня начала осуществления капитальных вложений в рамках реализации регионального инвестиционного проекта, но не ранее 1 января 2013 года и не ранее пяти лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 23.05.2016 № 144-ФЗ)\n\n5) каждый региональный инвестиционный проект реализуется единственным участником.\n\n1) региональный инвестиционный проект предусматривает производство товаров участником регионального инвестиционного проекта в рамках единого технологического процесса на территориях нескольких указанных только в подпункте 1 или только в подпункте 11 пункта 1 настоящей статьи субъектов Российской Федерации.\n\nЕдиным технологическим процессом для целей настоящего подпункта признается совокупность взаимосвязанных технологических операций, необходимых для производства товаров при реализации регионального инвестиционного проекта с использованием имущества, указанного в абзаце первом пункта 3 настоящей статьи, расходы на которое\n\nсоставляют объем капитальных вложений, осуществленных участником регионального инвестиционного проекта;\n\n(Подпункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n2) региональный инвестиционный проект направлен на добычу полезных ископаемых и соответствующий участок недр частично расположен за пределами территорий указанных только в подпункте 1 или только в подпункте 11 пункта 1 настоящей статьи субъектов Российской Федерации;  (В редакции федеральных законов от 23.05.2016 № 144-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n3) региональный инвестиционный проект, направленный на добычу драгоценных металлов, предусматривает их последующий аффинаж в специализированных организациях, перечень которых установлен в соответствии с Федеральным законом от 26 марта 1998 года № 41-ФЗ \"О драгоценных металлах и драгоценных камнях\". (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПри этом не учитываются:\n\nполученные участником регионального инвестиционного проекта машины, оборудование, транспортные средства и иное амортизируемое имущество, затраты на которые ранее включались в объем капитальных вложений участниками других региональных инвестиционных проектов;\n\nзатраты, понесенные российскими организациями, указанными в подпункте 1 пункта 1 статьи 259 настоящего Кодекса, на создание (приобретение) зданий, сооружений, расположенных на земельных участках, на которых осуществляется реализация инвестиционного проекта, на дату включения организации в реестр участников региональных инвестиционных проектов, за исключением указанных в пункте 31 настоящей статьи затрат, понесенных участниками региональных инвестиционных проектов, включенных в реестр участников региональных инвестиционных проектов до 1 января 2019 года; (В редакции  федеральных законов от 23.05.2016 № 144-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nзатраты, понесенные российскими организациями, указанными в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, на создание (приобретение) зданий, сооружений, расположенных на земельных участках, на которых осуществляется реализация инвестиционного проекта, на дату начала осуществления капитальных вложений по инвестиционному проекту, произведенные ранее 1 января 2013 года, а также произведенные ранее трех лет, предшествующих дате обращения организации в налоговый орган с заявлением о применении налоговой льготы в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса, при реализации инвестиционного проекта, удовлетворяющего требованиям, установленным абзацем вторым подпункта 41 пункта 1 настоящей статьи, или ранее пяти лет, предшествующих указанной дате, при реализации инвестиционного проекта, удовлетворяющего требованиям, установленным абзацем третьим подпункта 41 пункта 1 настоящей статьи. (Дополнение абзацем - Федеральный закон от 23.05.2016 № 144-ФЗ)","article_title":"Статья 25.8. Общие положения о региональных инвестиционных проектах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0779b4d8cdbfd25a79ab9d2612b8e60ecefd08ae090086dd9f5c2320a8a2d831"},{"code_id":"NK_RF","article_number":"25.9","version_date":"2000-07-31","article_text":"1. Налогоплательщиком - участником регионального инвестиционного проекта признается:\n\n1) российская организация, которая получила в порядке, установленном настоящей главой, статус участника регионального инвестиционного проекта и которая непрерывно в течение указанных в пунктах 2 - 5 статьи 2843 настоящего Кодекса налоговых периодов применения налоговых ставок, установленных пунктом 15 статьи 284 настоящего Кодекса, отвечает одновременно следующим требованиям:\n\nгосударственная регистрация юридического лица осуществлена на территории субъекта Российской Федерации, в котором реализуется региональный инвестиционный проект;\n\nорганизация не имеет в своем составе обособленных подразделений, расположенных за пределами территории субъекта (территорий субъектов) Российской Федерации, в котором (которых) реализуется региональный инвестиционный проект;\n\nорганизация не применяет специальных налоговых режимов, предусмотренных частью второй настоящего Кодекса;\n\nорганизация не является участником консолидированной группы налогоплательщиков;\n\nорганизация не является некоммерческой организацией, банком, страховой организацией (страховщиком), негосударственным пенсионным фондом, профессиональным участником рынка ценных бумаг, клиринговой организацией;\n\nорганизация не является резидентом особой экономической зоны любого типа, либо территории опережающего развития, либо свободного порта Владивосток, либо Арктической зоны Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nорганизация ранее не была участником регионального инвестиционного проекта и не является участником (правопреемником участника) иного реализуемого регионального инвестиционного проекта;\n\nорганизация не использует право на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций, установленное статьей 2463 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n2) российская организация, которая обратилась в налоговый орган с заявлением о применении налоговой льготы по налогу на прибыль организаций и (или) с заявлением о применении налоговой льготы по налогу на добычу полезных ископаемых в порядке, предусмотренном пунктами 1 и 2 статьи 2512-1 настоящего Кодекса, и которая непрерывно в течение указанных в пункте 2 статьи 2843-1 настоящего Кодекса налоговых периодов применения налоговой ставки, установленной пунктом 15-1 статьи 284 настоящего Кодекса, и (или) в течение налоговых периодов, указанных в пункте 2 статьи 3423-1 настоящего Кодекса, отвечает одновременно следующим требованиям:\n\nместом нахождения организации либо местом нахождения ее обособленного подразделения является территория одного из субъектов Российской Федерации, указанных в подпункте 1 пункта 1 статьи 258 настоящего Кодекса;\n\nорганизация не применяет специальных налоговых режимов, предусмотренных частью второй настоящего Кодекса;\n\nорганизация не является участником консолидированной группы налогоплательщиков;\n\nорганизация не является резидентом особой экономической зоны любого типа, либо территории опережающего развития, либо свободного порта Владивосток, либо Арктической зоны Российской Федерации; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nорганизация не является участником (правопреемником участника) иного реализуемого регионального инвестиционного проекта;\n\nорганизация не использует право на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций, установленное статьей 2463 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n1) в соответствии с подпунктом 1 пункта 1 настоящей статьи со дня включения организации в реестр участников региональных инвестиционных проектов в порядке, установленном настоящей главой;\n\n2) в соответствии с подпунктом 2 пункта 1 настоящей статьи начиная с налогового периода, в котором впервые одновременно соблюдены условия, предусмотренные пунктом 2 статьи 2843-1 настоящего Кодекса. При этом включение организации в реестр участников региональных инвестиционных проектов не требуется;\n\n3) (Подпункт утратил силу  - Федеральный закон от 02.08.2019 № 269-ФЗ)\n\n(Статья в редакции Федерального закона от 23.05.2016 № 144-ФЗ)","article_title":"Статья 25.9. Налогоплательщики - участники региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3059ed2208432bf1837c1b47c7d367bc4a5906fe90063f79daa6fe308d306a0e"},{"code_id":"NK_RF","article_number":"26","version_date":"2000-07-31","article_text":"1. Налогоплательщик может участвовать в отношениях, регулируемых законодательством о налогах и сборах через законного или уполномоченного представителя, если иное не предусмотрено настоящим Кодексом.\n\n2. Личное участие налогоплательщика в отношениях, регулируемых законодательством о налогах и сборах, не лишает его права иметь представителя, равно как участие представителя не лишает налогоплательщика права на личное участие в указанных правоотношениях.\n\n3. Полномочия представителя должны быть документально подтверждены в соответствии с настоящим Кодексом и иными федеральными законами.","article_title":"Статья 26. Право на представительство в отношениях, регулируемых законодательством о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e52206fc7159ba708ec9614122551f0d67bfb60645542b3b51ee16048aff2f6"},{"code_id":"NK_RF","article_number":"27","version_date":"2000-07-31","article_text":"Законными представителями налогоплательщика - иностранной организации признаются лица, уполномоченные представлять указанную организацию на основании документов, подтверждающих право таких лиц на указанное представительство в соответствии с законодательством иностранного государства, на территории которого эта иностранная организация зарегистрирована. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 27. Законный представитель налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6fe972982f109fbc92b4293200a2a44c15510bc8b5cf5a404dd8e31290fc72d"},{"code_id":"NK_RF","article_number":"28","version_date":"2000-07-31","article_text":"Действия (бездействие) законных представителей организации, совершенные в связи с участием этой организации в отношениях, регулируемых законодательством о налогах и сборах, признаются действиями (бездействием) этой организации.","article_title":"Статья 28. Действия (бездействие) законных представителей организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56b9501d8c56cbbc79c22985189b2b34b4eda995879535d976b27455ee6ac7fc"},{"code_id":"NK_RF","article_number":"29","version_date":"2000-07-31","article_text":"Уполномоченный представитель налогоплательщика - индивидуального предпринимателя (физического лица, не являющегося индивидуальным предпринимателем) осуществляет свои полномочия на основании нотариально удостоверенной доверенности, доверенности, приравненной к нотариально удостоверенной в соответствии с гражданским законодательством, или доверенности в форме электронного документа, подписанного электронной подписью доверителя, если иное не предусмотрено абзацем третьим настоящего пункта. (В редакции  федеральных законов от 23.11.2020 № 374-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nУполномоченный представитель, указанный в пункте 51 статьи 23 настоящего Кодекса, осуществляет свои полномочия на основании доверенности в форме электронного документа, подписанного усиленной квалифицированной электронной подписью доверителя. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nЕсли иное не предусмотрено абзацем третьим настоящего пункта, документы, подтверждающие полномочия уполномоченных представителей, должны быть представлены в налоговый орган лицом лично или через представителя либо направлены в налоговый орган в электронной форме в виде электронных документов или электронных образов документов (документов на бумажном носителе, преобразованных в электронную форму путем сканирования с сохранением их реквизитов), подписанных усиленной квалифицированной подписью доверителя. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nФорматы документа, подтверждающего полномочия уполномоченного представителя, и заявления об отзыве доверенности, созданной в форме электронного документа, и порядок их направления в налоговый орган по телекоммуникационным каналам связи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nв ответственный участник этой группы вправе представлять интересы участников указанной консолидированной группы в следующих правоотношениях:\n\n1) в правоотношениях, связанных с регистрацией в налоговых органах договора о создании консолидированной группы налогоплательщиков, а также изменений указанного договора, решения о продлении срока действия договора и его прекращения;\n\n2) в правоотношениях, связанных с принудительным взысканием с участника консолидированной группы налогоплательщиков недоимки по налогу на прибыль организаций по консолидированной группе налогоплательщиков;\n\n3) в правоотношениях, связанных с привлечением организации к ответственности за налоговые правонарушения, совершенные в связи с участием в консолидированной группе налогоплательщиков;\n\n4) в других случаях, когда по характеру совершаемых налоговым органом действий (бездействия) они непосредственно затрагивают права организации, являющейся участником консолидированной группы налогоплательщиков.\n\n(Дополнение пунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 30.06.2003 № 86-ФЗ; от 29.06.2004 № 58-ФЗ; от 28.12.2010 № 404-ФЗ)\n\n(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)","article_title":"Статья 29. Уполномоченный представитель налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b15dd1d9692b8b2495b91e66290b51773a00e88e56b9fb39fe235f2f990bb7c3"},{"code_id":"NK_RF","article_number":"3","version_date":"2000-07-31","article_text":"Не допускается устанавливать дифференцированные ставки налогов и сборов, налоговые льготы в зависимости от формы собственности, гражданства физических лиц или места происхождения капитала.\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nНи на кого не может быть возложена обязанность уплачивать налоги и сборы, а также иные взносы и платежи, обладающие установленными настоящим Кодексом признаками налогов или сборов, не предусмотренные настоящим Кодексом либо установленные в ином порядке, чем это определено настоящим Кодексом.","article_title":"Статья 3. Основные начала законодательства о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2bc4f1db7def4d2addc7658a6325e8a2904ffa9bd193094290ac39b1fd4fdd72"},{"code_id":"NK_RF","article_number":"31","version_date":"2000-07-31","article_text":"1. Налоговые органы вправе:\n\n1) требовать в соответствии с законодательством о налогах и сборах от налогоплательщика, плательщика сбора или налогового агента документы по формам и (или) форматам в электронной форме, установленным государственными органами и органами местного самоуправления, служащие основаниями для исчисления и уплаты (удержания и перечисления) налогов, сборов, а также документы, подтверждающие правильность исчисления и своевременность уплаты (удержания и перечисления) налогов, сборов; (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 29.06.2012 № 97-ФЗ)\n\n2) проводить налоговые проверки в порядке, установленном настоящим Кодексом;\n\n21) контролировать исполнение банками обязанностей, установленных настоящим Кодексом. Порядок контроля за исполнением банками обязанностей, установленных настоящим Кодексом, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации; (Дополнение подпунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n3) производить выемку документов у налогоплательщика, плательщика сбора или налогового агента при проведении налоговых проверок в случаях, когда есть достаточные основания полагать, что эти документы будут уничтожены, сокрыты, изменены или заменены;\n\n4) вызывать на основании письменного уведомления в налоговые органы налогоплательщиков, плательщиков сборов или налоговых агентов для дачи пояснений в связи с уплатой (удержанием и перечислением) ими налогов и сборов либо в связи с налоговой проверкой, а также в иных случаях, связанных с исполнением ими законодательства о налогах и сборах;\n\n5) приостанавливать операции по счетам налогоплательщика, плательщика сбора или налогового агента в банках и налагать арест на имущество налогоплательщика, плательщика сбора или налогового агента в порядке, предусмотренном настоящим Кодексом;\n\n6) в порядке, предусмотренном статьей 92 настоящего Кодекса, осматривать любые используемые налогоплательщиком для извлечения дохода либо связанные с содержанием объектов налогообложения независимо от места их нахождения производственные, складские, торговые и иные помещения и территории, проводить инвентаризацию принадлежащего налогоплательщику имущества. Порядок проведения инвентаризации имущества налогоплательщика при налоговой проверке утверждается Министерством финансов Российской Федерации;\n\n7) определять суммы налогов, подлежащие уплате налогоплательщиками в бюджетную систему Российской Федерации, расчетным путем на основании имеющейся у них информации о налогоплательщике, а также данных об иных аналогичных налогоплательщиках в случаях отказа налогоплательщика допустить должностных лиц налогового органа к осмотру производственных, складских, торговых и иных помещений и территорий, используемых налогоплательщиком для извлечения дохода либо связанных с содержанием объектов налогообложения, непредставления в течение более двух месяцев налоговому органу необходимых для расчета налогов документов, отсутствия учета доходов и расходов, учета объектов налогообложения, ведения учета с нарушением установленного порядка, приведшего к невозможности исчислить налоги, или непредставления налогоплательщиком - иностранной организацией, не осуществляющей деятельность на территории Российской Федерации через постоянное представительство, налоговой декларации по налогу на имущество организаций; (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\n8) требовать от налогоплательщиков, плательщиков сборов, налоговых агентов, их представителей устранения выявленных нарушений законодательства о налогах и сборах и контролировать выполнение указанных требований;\n\n9) взыскивать задолженность в случаях и порядке, которые установлены настоящим Кодексом; (В редакции  федеральных законов от 17.12.2009 № 318-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) требовать от банков документы, подтверждающие факт списания со счетов налогоплательщиков, плательщиков сборов, налоговых агентов и с корреспондентских счетов банков денежных средств, перечисляемых в счет исполнения обязанностей налогоплательщиков, плательщиков сборов, налоговых агентов по уплате налогов, сборов, страховых взносов (в том числе в качестве единого налогового платежа), и перечисления этих денежных средств в бюджетную систему Российской Федерации; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n11) привлекать для проведения налогового контроля специалистов, экспертов и переводчиков;\n\n12) вызывать в качестве свидетелей лиц, которым могут быть известны какие-либо обстоятельства, имеющие значение для проведения налогового контроля;\n\n13) заявлять ходатайства об аннулировании или о приостановлении действия выданных юридическим и физическим лицам лицензий на право осуществления определенных видов деятельности;\n\n14) предъявлять в суды общей юрисдикции, Верховный Суд Российской Федерации или арбитражные суды иски (заявления): (В редакции Федерального закона от 28.06.2014 № 198-ФЗ)\n\nо взыскании задолженности в случаях, предусмотренных настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nо возмещении ущерба, причиненного государству, муниципальному образованию и (или) федеральной территории \"Сириус\" вследствие неправомерных действий банка по списанию денежных средств (драгоценных металлов) со счета налогоплательщика, операции по которому приостановлены налоговым органом, в результате которых стало невозможным взыскание налоговым органом задолженности с налогоплательщика в порядке, предусмотренном настоящим Кодексом; (В редакции  федеральных законов от 27.11.2017 № 343-ФЗ, от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nо досрочном расторжении договора об инвестиционном налоговом кредите;\n\nв иных случаях, предусмотренных настоящим Кодексом;\n\n15) восстанавливать в случае, предусмотренном пунктом 11 статьи 59 настоящего Кодекса, суммы задолженности, признанной безнадежной к взысканию. (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2. Налоговые органы осуществляют также другие права, предусмотренные настоящим Кодексом.\n\n3. Вышестоящие налоговые органы вправе отменять и изменять решения нижестоящих налоговых органов в случае несоответствия указанных решений законодательству о налогах и сборах.\n\nДокументы, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, могут быть переданы налоговым органом лицу, которому они адресованы, или его представителю непосредственно под расписку, через многофункциональный центр предоставления государственных и муниципальных услуг, направлены по почте заказным письмом или переданы в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, либо через личный кабинет налогоплательщика, либо через информационные системы организации, к которым предоставлен доступ налоговому органу, если порядок их передачи прямо не предусмотрен настоящим Кодексом, а также могут быть переданы в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг в соответствии с настоящим Кодексом. Лицам, на которых настоящим Кодексом возложена обязанность представлять налоговую декларацию (расчет) в электронной форме, указанные документы направляются налоговым органом в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота, либо через личный кабинет налогоплательщика, либо через информационные системы организации, к которым предоставлен доступ налоговому органу. (В редакции  федеральных законов от 04.11.2014 № 347-ФЗ, от 02.05.2015 № 113-ФЗ, от 29.09.2019 № 325-ФЗ, от 29.12.2020 № 470-ФЗ, от 14.04.2023 № 125-ФЗ)\n\nВ случаях направления документа налоговым органом по почте заказным письмом датой его получения считается шестой день со дня отправки заказного письма.\n\nВ случае направления документа налоговым органом через личный кабинет налогоплательщика датой его получения считается день, следующий за днем размещения документа в личном кабинете налогоплательщика. (Дополнение абзацем - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nДокумент в электронной форме, подписанный автоматически созданной электронной подписью налогового органа, признается равнозначным документу на бумажном носителе, подписанному собственноручной подписью должностного лица налогового органа. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nВ случае направления документа налоговым органом через многофункциональный центр предоставления государственных и муниципальных услуг датой его получения считается день, следующий за днем получения указанного документа многофункциональным центром предоставления государственных и муниципальных услуг, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ случае направления документа налоговым органом в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг датой его получения считается день, следующий за днем направления документа налоговым органом в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг. (Дополнение абзацем - Федеральный закон от 14.04.2023 № 125-ФЗ)\n\nВ случае направления налоговым органом налогоплательщику, указанному в абзаце первом пункта 51 статьи 23 настоящего Кодекса, документа в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота датой его получения считается шестой день со дня направления такого документа, указанного в подтверждении даты отправки электронного документа. Подтверждение даты отправки электронного документа направляется оператором электронного документооборота в налоговый орган не позднее дня, следующего за днем направления документа налогоплательщику. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nДокументы (сведения), не содержащие налоговую тайну, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, передаются налоговым органом налогоплательщику - физическому лицу, зарегистрированному в единой системе идентификации и аутентификации, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг, если такой порядок передачи документов (сведений), не содержащих налоговую тайну, предусмотрен настоящим Кодексом или если указанные документы (сведения) включены в перечень, утверждаемый в соответствии с абзацем первым пункта 9 настоящей статьи. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nДокументы (сведения), не содержащие налоговую тайну, используемые налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, налогоплательщикам - физическим лицам, зарегистрированным в единой системе идентификации и аутентификации, направленные через личный кабинет на едином портале государственных и муниципальных услуг, на бумажном носителе по почте не направляются, если иное не предусмотрено пунктом 2 статьи 112 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 30.12.2006 № 268-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nналогоплательщику - российской организации (ее филиалу, представительству) - по адресу места ее нахождения (места нахождения ее филиала, представительства), содержащемуся в Едином государственном реестре юридических лиц;\n\nналогоплательщику - иностранной организации - по адресу места осуществления им деятельности на территории Российской Федерации, содержащемуся в Едином государственном реестре налогоплательщиков;\n\nналогоплательщику - иностранной организации (за исключением международной организации, дипломатического представительства), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, - по предоставленному налоговому органу адресу для направления документов, указанных в настоящем пункте, содержащемуся в Едином государственном реестре налогоплательщиков; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nналогоплательщику - иностранной организации, не осуществляющей деятельность на территории Российской Федерации через постоянное представительство и имеющей на территории Российской Федерации объект недвижимого имущества на праве собственности, - по адресу места нахождения указанного объекта недвижимого имущества или по предоставленному налоговому органу адресу; (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nналогоплательщику - индивидуальному предпринимателю, нотариусу, занимающемуся частной практикой, адвокату, учредившему адвокатский кабинет, физическому лицу, не являющемуся индивидуальным предпринимателем, - по адресу места его жительства (места пребывания) или по предоставленному налоговому органу адресу для направления документов, указанных в настоящем пункте, содержащемуся в Едином государственном реестре налогоплательщиков. При отсутствии у физического лица, не являющегося индивидуальным предпринимателем, места жительства (места пребывания) на территории Российской Федерации и отсутствии в Едином государственном реестре налогоплательщиков сведений об адресе для направления этому лицу документов, указанных в настоящем пункте, такие документы направляются налоговым органом по адресу места нахождения одного из принадлежащих такому физическому лицу объектов недвижимого имущества (за исключением земельного участка). (В редакции Федерального закона от 29.07.2018 № 232-ФЗ)\n\nФорма заявления о предоставлении налоговому органу адреса для направления по почте документов, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона о\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\nДо предоставления иностранному лицу, подлежащему постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, доступа к личному кабинету налогоплательщика в соответствии с абзацем вторым пункта 3 статьи 112 настоящего Кодекса документы, которые используются налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, передаются по любому известному налоговому органу адресу электронной почты такого иностранного лица. В этом случае датой получения иностранным лицом соответствующего документа считается день, следующий за днем его передачи по адресу электронной почты. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 244-ФЗ)\n\nДокументы (сведения), представляемые в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг, не позднее дня, следующего за днем их приема, направляются многофункциональным центром предоставления государственных и муниципальных услуг в налоговый орган в форме электронных документов, если иное не предусмотрено настоящим пунктом.\n\nПорядок взаимодействия налоговых органов с многофункциональными центрами предоставления государственных и муниципальных услуг в электронной форме и требования к формированию электронных документов, используемых при таком взаимодействии, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПорядок передачи документов (сведений), принятых многофункциональными центрами предоставления государственных и муниципальных услуг, в налоговые органы на бумажном носителе, порядок передачи по результатам рассмотрения указанных документов (сведений) налоговыми органами документов на бумажном носителе через многофункциональные центры предоставления государственных и муниципальных услуг определяются соглашением взаимодействующих сторон.\n\nВ случае представления физическим лицом в налоговый орган документов (сведений), за исключением налоговых деклараций, через многофункциональный центр предоставления государственных и муниципальных услуг по просьбе этого физического лица, выраженной в письменной форме, о получении по результатам рассмотрения указанных документов (сведений) от налогового органа документа через многофункциональный центр предоставления государственных и муниципальных услуг налоговый орган обязан в срок, не превышающий двух дней после подготовки соответствующего документа, передать такой документ в многофункциональный центр предоставления государственных и муниципальных услуг для его получения физическим лицом на бумажном носителе.\n\nПередача налоговым органом физическому лицу документов, содержащих сведения о нем, составляющие налоговую тайну, на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг осуществляется при наличии письменного согласия на это указанного физического лица, которое может быть выражено им в документе (сведениях), представляемых в налоговый орган через многофункциональный центр предоставления государственных и муниципальных услуг.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПередача налоговым органом налогоплательщику - физическому лицу документов, содержащих сведения о нем, составляющие налоговую тайну, в электронной форме через личный кабинет на едином портале государственных и муниципальных услуг осуществляется при наличии согласия на это указанного налогоплательщика, выраженного им в уведомлении о необходимости получения документов с использованием единого портала государственных и муниципальных услуг.\n\n(Дополнение пунктом - Федеральный закон от 14.04.2023 № 125-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 31. Права налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50b17d230235e1e9d13cb3da3c010e4949edcdc14e60bdafaa143d2bd0711c05"},{"code_id":"NK_RF","article_number":"32","version_date":"2000-07-31","article_text":"1. Налоговые органы обязаны:\n\n1) соблюдать законодательство о налогах и сборах;\n\n2) осуществлять контроль за соблюдением законодательства о налогах и сборах, а также принятых в соответствии с ним нормативных правовых актов;\n\n3) вести в установленном порядке учет организаций и физических лиц;\n\n4) бесплатно информировать (в том числе в письменной форме) налогоплательщиков, плательщиков сборов и налоговых агентов о действующих налогах и сборах, законодательстве о налогах и сборах и о принятых в соответствии с ним нормативных правовых актах, порядке исчисления и уплаты налогов и сборов, правах и обязанностях налогоплательщиков, плательщиков сборов и налоговых агентов, полномочиях налоговых органов и их должностных лиц, а также представлять формы налоговых деклараций (расчетов) и разъяснять порядок их заполнения;\n\n41) передавать налогоплательщикам, указанным в пунктах 2 и 3 статьи 112 настоящего Кодекса, в электронной форме квитанцию о приеме при получении документов, переданных в налоговый орган через личный кабинет налогоплательщика; (Дополнение подпунктом - Федеральный закон от 04.11.2014 № 347-ФЗ) (В редакции Федерального закона от 03.07.2016 № 244-ФЗ)\n\n5) руководствоваться письменными разъяснениями Министерства финансов Российской Федерации по вопросам применения законодательства Российской Федерации о налогах и сборах;\n\n6) доводить до сведения налогоплательщиков, плательщиков сборов и налоговых агентов информацию о реквизитах счета Федерального казначейства, об их изменении и иную информацию, необходимую для заполнения поручений на перечисление налогов, сборов, уплачиваемых не в качестве единого налогового платежа; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n7) осуществлять возврат лицу - налогоплательщику, плательщику сбора или налоговому агенту денежных средств в размере, не превышающем положительное сальдо единого налогового счета такого лица, или осуществлять зачет указанных денежных средств в счет исполнения обязанности другого лица по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) либо в счет исполнения решений налоговых органов, указанных в подпунктах 10 и 11 пункта 5 и подпункте 3 пункта 7 статьи 113 настоящего Кодекса, в порядке, предусмотренном настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n8) соблюдать налоговую тайну и обеспечивать ее сохранение;\n\n9) направлять налогоплательщику, плательщику сбора или налоговому агенту копии акта налоговой проверки и решения налогового органа, а также в случаях, предусмотренных настоящим Кодексом, налоговое уведомление и (или) требование об уплате задолженности; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n10) представлять налогоплательщику, плательщику сбора или налоговому агенту по его запросу, переданному в налоговый орган в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе, справку о наличии по состоянию на дату формирования справки положительного, отрицательного или нулевого сальдо единого налогового счета такого налогоплательщика, плательщика сбора или налогового агента, справку о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, и справку об исполнении обязанности по уплате налогов, сборов, пеней, штрафов, процентов по состоянию на дату формирования справки на основании данных налогового органа в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСправка о наличии положительного, отрицательного или нулевого сальдо единого налогового счета и справка о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, представляются лицу, указанному в пункте 4 статьи 113 настоящего Кодекса (его представителю), в течение пяти дней со дня поступления в налоговый орган соответствующих запросов, справка об исполнении обязанности по уплате налогов, сборов, пеней, штрафов, процентов - в течение десяти дней со дня поступления в налоговый орган соответствующего запроса.\n\nПри этом справка о наличии отрицательного сальдо должна содержать имеющиеся в налоговом органе детализированные сведения об обязанности лица, указанного в пункте 4 статьи 113 настоящего Кодекса, по уплате налогов (авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов).\n\nСправка о принадлежности сумм денежных средств, перечисленных в качестве единого налогового платежа, формируется за период, не превышающий трех лет, предшествующих дню поступления в налоговый орган соответствующего запроса, и должна содержать сведения о всех денежных средствах, поступивших и признаваемых в качестве единого налогового платежа, и иных суммах, признаваемых в качестве единого налогового платежа, с указанием их принадлежности, определенной на дату формирования справки;\n\n(Подпункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n101) (Дополнение подпунктом - Федеральный закон от 16.11.2011 № 321-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n11) (Подпункт утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n12) по заявлению налогоплательщика, плательщика сбора или налогового агента выдавать копии решений, принятых налоговым органом в отношении этого налогоплательщика, плательщика сбора или налогового агента;\n\n13) по заявлению ответственного участника консолидированной группы налогоплательщиков выдавать копии решений, принятых налоговым органом в отношении консолидированной группы налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n14) представлять пользователям выписки из Единого государственного реестра налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n15) представлять в электронной форме в порядке, определяемом соглашением взаимодействующих сторон, в территориальные органы Фонда пенсионного и социального страхования Российской Федерации, Федерального фонда обязательного медицинского страхования сведения о наделении обособленных подразделений (включая филиалы, представительства) российских организаций, созданных на территории Российской Федерации, полномочиями (о лишении полномочий) по начислению выплат и иных вознаграждений в пользу физических лиц, об изменении места нахождения обособленных подразделений (за исключением филиалов, представительств), о прекращении деятельности указанных организаций через такие обособленные подразделения (о закрытии таких обособленных подразделений), о постановке на учет (снятии с учета) в налоговых органах иностранных организаций, осуществляющих деятельность на территории Российской Федерации, международных организаций в качестве плательщиков страховых взносов, физических лиц в качестве адвокатов, нотариусов, занимающихся частной практикой, арбитражных управляющих, занимающихся частной практикой оценщиков, патентных поверенных, медиаторов и иных физических лиц - плательщиков страховых взносов не позднее трех дней, следующих за днем внесения в Единый государственный реестр налогоплательщиков указанных сведений; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 243-ФЗ) (В редакции  федеральных законов от 30.11.2016 № 401-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n16) по заявлению налогоплательщика представлять налогоплательщику (его представителю) документ в электронной форме или на бумажном носителе, подтверждающий статус налогового резидента Российской Федерации, в порядке, по форме и формату, которые утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n17) представлять в электронной форме в порядке, определяемом соглашением взаимодействующих сторон, в территориальные органы Фонда пенсионного и социального страхования Российской Федерации сведения о постановке на учет (снятии с учета) в налоговых органах физических лиц, в том числе индивидуальных предпринимателей, в качестве налогоплательщиков налога на профессиональный доход, признаваемых таковыми в соответствии с Федеральным законом от 27 ноября 2018 года № 422-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Налог на профессиональный доход\", не позднее трех дней, следующих за днем внесения в Единый государственный реестр налогоплательщиков указанных сведений. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  федеральных законов от 28.01.2020 № 5-ФЗ, от 14.07.2022 № 239-ФЗ)\n\n2. Налоговые органы несут также другие обязанности, предусмотренные настоящим Кодексом и иными федеральными законами.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 32. Обязанности налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f951ab496a45a5937d0917aadc6c861f38afd8348c877809a1138b338d013b8"},{"code_id":"NK_RF","article_number":"33","version_date":"2000-07-31","article_text":"Должностные лица налоговых органов обязаны:\n\n1) действовать в строгом соответствии с настоящим Кодексом и иными федеральными законами;\n\n2) реализовывать в пределах своей компетенции права и обязанности налоговых органов;\n\n3) корректно и внимательно относиться к налогоплательщикам, их представителям и иным участникам отношений, регулируемых законодательством о налогах и сборах, не унижать их честь и достоинство. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 33. Обязанности должностных лиц налоговых органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c101bce3215b56566e674b0e7d3232c668883df903b9af6bd2b55d70eb987311"},{"code_id":"NK_RF","article_number":"34.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 29.06.2004 № 58-ФЗ)","article_title":"Статья 34.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f034394fc39cf58740a722f96dd42f7ef1b6f2ccc1e9d3a810c3e95927b8e3a"},{"code_id":"NK_RF","article_number":"34.2","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nн от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 29.06.2004 № 58-ФЗ)","article_title":"Статья 34.2. Полномочия финансовых органов в области налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"242ae03ab281e5f15f9fb77ea16cad754e2b1a04fd6219eb8b8bcfe50c3663e8"},{"code_id":"NK_RF","article_number":"35","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 29.06.2004 № 58-ФЗ)\n\nПричиненные налогоплательщикам, плательщикам сборов, плательщикам страховых взносов и налоговым агентам убытки возмещаются за счет федерального бюджета в порядке, предусмотренном настоящим Кодексом и иными федеральными законами. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ)","article_title":"Статья 35. Ответственность налоговых органов, таможенных органов, а также их должностных лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86ca237da13167275c3c54ce491291955ecf07553a30a76cf76356e997e97b8f"},{"code_id":"NK_RF","article_number":"36","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.12.2010 № 404-ФЗ)\n\n1. По запросу налоговых органов органы внутренних дел участвуют вместе с налоговыми органами в проводимых налоговыми органами выездных налоговых проверках.\n\n(Статья в редакции Федерального закона от 30.06.2003 № 86-ФЗ)","article_title":"Статья 36. Полномочия органов внутренних дел, следственных органов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"287972ab5b8f4163fd92b750d768609dbdaf0078b493cad4e1215dd9c1c5b53a"},{"code_id":"NK_RF","article_number":"37","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ)\n\nПричиненные налогоплательщикам, плательщикам сборов, плательщикам страховых взносов и налоговым агентам при проведении мероприятий, предусмотренных пунктом 1 статьи 36 настоящего Кодекса, убытки возмещаются за счет федерального бюджета в порядке, предусмотренном настоящим Кодексом и иными федеральными законами. (В редакции федеральных законов от 30.06.2003 № 86-ФЗ; от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 37. Ответственность органов внутренних дел, следственных органов и их должностных лиц","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b8da6ca3ba9ef54332720ca42591a617847d8fb1d7348371165201ef84bcd6b3"},{"code_id":"NK_RF","article_number":"38","version_date":"2000-07-31","article_text":"Каждый налог имеет самостоятельный объект налогообложения, определяемый в соответствии с частью второй настоящего Кодекса и с учетом положений настоящей статьи.\n\nДля целей настоящего Кодекса не признаются имуществом имущественные права, за исключением безналичных денежных средств и бездокументарных ценных бумаг.\n\nДля целей настоящего Кодекса цифровая валюта (в том числе цифровая валюта, используемая в качестве средства платежа по внешнеторговым договорам (контрактам) в рамках экспериментального правового режима в сфере цифровых инноваций, установленного в соответствии со статьей 11 Федерального закона от 31 июля 2020 года № 259-ФЗ \"О цифровых финансовых активах, цифровой валюте и о внесении изменений в отдельные законодательные акты Российской Федерации\") признается имуществом. (Дополнение абзацем - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n(Пункт в редакции Федерального закона от 20.07.2020 № 219-ФЗ)\n\nПри определении идентичности товаров учитываются их физические характеристики, качество, функциональное назначение, страна происхождения и производитель, его деловая репутация на рынке и используемый товарный знак.\n\nПри определении идентичности работ (услуг) учитываются характеристики подрядчика (исполнителя), его деловая репутация на рынке и используемый товарный знак.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 227-ФЗ)\n\nОднородными работами (услугами) признаются работы (услуги), которые, не являясь идентичными, имеют сходные характеристики, что позволяет им быть коммерчески и (или) функционально взаимозаменяемыми. При определении однородности работ (услуг) учитываются их качество, товарный знак, репутация на рынке, а также вид работ (услуг), их объем, уникальность и коммерческая взаимозаменяемость.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 38. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6874f9078939ecc6900a2d0443381b14804c4220b5bcf9c3ad5a91d5a77402d"},{"code_id":"NK_RF","article_number":"39","version_date":"2000-07-31","article_text":"1) осуществление операций, связанных с обращением российской или иностранной валюты (за исключением целей нумизматики);\n\n2) передача основных средств, нематериальных активов и (или) иного имущества организации ее правопреемнику (правопреемникам) при реорганизации этой организации;\n\n3) передача основных средств, нематериальных активов и (или) иного имущества некоммерческим организациям на осуществление основной уставной деятельности, не связанной с предпринимательской деятельностью; (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n4) передача имущества, если такая передача носит инвестиционный характер (в частности, вклады в уставный (складочный) капитал хозяйственных обществ и товариществ, вклады по договору простого товарищества (договору о совместной деятельности), договору инвестиционного товарищества, паевые взносы в паевые фонды кооперативов); (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 28.11.2011 № 336-ФЗ)\n\n41) передача имущества и (или) имущественных прав по концессионному соглашению, соглашению о государственно-частном партнерстве, соглашению о муниципально-частном партнерстве в соответствии с законодательством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 30.06.2008 № 108-ФЗ) (В редакции Федерального закона от 25.12.2018 № 493-ФЗ)\n\n5) передача имущества в пределах первоначального взноса участнику хозяйственного общества или товарищества (его правопреемнику или наследнику) при выходе (выбытии) из хозяйственного общества или товарищества, а также при распределении имущества ликвидируемого хозяйственного общества или товарищества между его участниками; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n6) передача имущества в пределах первоначального взноса участнику договора простого товарищества (договора о совместной деятельности), договора инвестиционного товарищества или его правопреемнику в случае выдела его доли из имущества, находящегося в общей собственности участников договора, или раздела такого имущества; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 28.11.2011 № 336-ФЗ)\n\n7) передача жилых помещений физическим лицам в домах государственного или муниципального жилищного фонда при проведении приватизации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n8) изъятие имущества путем конфискации, наследование имущества, а также обращение в собственность иных лиц бесхозяйных и брошенных вещей, бесхозяйных животных, находки, клада в соответствии с нормами Гражданского кодекса Российской Федерации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n81) передача имущества участникам хозяйственного общества или товарищества при распределении имущества и имущественных прав ликвидируемой организации, являющейся иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи или маркетинговым партнером Международного олимпийского комитета в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\". Настоящее положение применяется в случае, если создание и ликвидация организации, являющейся иностранным организатором XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи или маркетинговым партнером Международного олимпийского комитета в соответствии со статьей 31 указанного Федерального закона, осуществляются в период организации XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленный частью 1 статьи 2 указанного Федерального закона; (Дополнение подпунктом - Федеральный закон от 30.07.2010 № 242-ФЗ)\n\n82) передача имущества номинальным владельцем его фактическому владельцу, если такое имущество и его номинальный владелец указаны в специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\n9) иные операции в случаях, предусмотренных настоящим Кодексом. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 39. Реализация товаров, работ или услуг","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30d5ed64435b7b969061e056e595d06f1ed78a69d3cca12342fe4856f91454f2"},{"code_id":"NK_RF","article_number":"4","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ, от 03.07.2016 № 243-ФЗ, от 11.06.2021 № 199-ФЗ)\n\n1) приостановление, отмену или перенос на более поздний срок мероприятий налогового контроля, в том числе проверок полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, а также приостановление течения сроков, предусмотренных настоящим Кодексом, в том числе сроков назначения (проведения) проверок, на период приостановления или переноса указанных мероприятий налогового контроля;\n\n2) продление установленных законодательством Российской Федерации о налогах и сборах сроков уплаты налогов (авансовых платежей по налогам), в том числе предусмотренных специальными налоговыми режимами, сборов, страховых взносов; (В редакции Федерального закона от 26.03.2022 № 67-ФЗ)\n\n3) продление установленных законодательством субъектов Российской Федерации о налогах и сборах и нормативными правовыми актами муниципальных образований о местных налогах и сборах сроков уплаты авансовых платежей по транспортному налогу, налогу на имущество организаций и земельному налогу;\n\n4) продление сроков представления в налоговые органы налоговых деклараций (расчетов), бухгалтерской (финансовой) отчетности и (или) иных документов (сведений);\n\n5) продление сроков направления и исполнения требований об уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов, а также сроков принятия решений о взыскании налогов, сборов, страховых взносов, пеней, штрафов, процентов;\n\n6) дополнительные основания предоставления в 2020, 2022 - 2028 годах отсрочки (рассрочки) по уплате налогов, страховых взносов, пеней, штрафов, процентов, изменение порядка и условий ее предоставления; (В редакции  федеральных законов от 09.03.2022 № 52-ФЗ, от 21.11.2022 № 443-ФЗ, от 19.12.2023 № 611-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n7) основания и условия неприменения или особенности применения способов обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов;\n\n8) основания и условия неприменения ответственности за непредставление (несвоевременное представление) в налоговые органы налоговых деклараций (расчетов), бухгалтерской (финансовой) отчетности и (или) иных документов (сведений);\n\n9) особенности взыскания задолженности за счет денежных средств на счетах налогоплательщика (плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя или налогового агента - организации, индивидуального предпринимателя. (Дополнение подпунктом - Федеральный закон от 19.12.2023 № 611-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)\n\nабря 2024 года (включительно) издавать нормативные правовые акты, предусматривающие особенности неприменения ответственности в 2024 году к лицам, состоящим на учете в налоговых органах по месту нахождения (месту жительства) на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области. (Дополнение пунктом - Федеральный закон от 28.12.2022 № 564-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 611-ФЗ)\n\nВ случае, если в соответствии с настоящим пунктом сроки уплаты налогов, предусмотренных специальными налоговыми режимами, региональных и местных налогов (авансовых платежей по налогам), торгового сбора продлеваются для отдельных категорий налогоплательщиков, при принятии указанных в настоящем пункте нормативных правовых актов и установлении критериев определения этих категорий налогоплательщиков учитываются следующие показатели: основные виды экономической деятельности, которые осуществляют налогоплательщики по состоянию на 1 марта 2020 года (в отношении указанных актов и критериев, принятых в 2020 году), на 1 марта 2022 года (в отношении указанных актов и критериев, принятых в 2022 году); данные, содержащиеся в реестрах, ведение которых осуществляет федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в налоговой или бухгалтерской (финансовой) отчетности. (В редакции Федерального закона от 09.03.2022 № 52-ФЗ)\n\nВ случае определения указанных категорий на основе иных критериев уполномоченный орган исполнительной власти субъекта Российской Федерации формирует соответствующий перечень налогоплательщиков с указанием их идентификационных номеров, который направляется в налоговый орган по субъекту Российской Федерации в электронной форме.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)\n\n(Статья в редакции Федерального закона от 29.06.2004 № 58-ФЗ)","article_title":"Статья 4. Нормативные правовые акты Правительства Российской Федерации, федеральных органов исполнительной власти, органов исполнительной власти субъектов Российской Федерации, исполнительных органов местного самоуправления, исполнительно-распорядительного органа федеральной территории \"Сириус\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f787f2c3e22dfbaabf7fcbb95abf561d840a75911274017a03e9db048a6803a1"},{"code_id":"NK_RF","article_number":"40","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящей статьей, для целей налогообложения принимается цена товаров, работ или услуг, указанная сторонами сделки. Пока не доказано обратное, предполагается, что эта цена соответствует уровню рыночных цен.\n\n1) между взаимозависимыми лицами;\n\n2) по товарообменным (бартерным) операциям;\n\n3) при совершении внешнеторговых сделок; (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n4) при отклонении более чем на 20 процентов в сторону повышения или в сторону понижения от уровня цен, применяемых налогоплательщиком по идентичным (однородным) товарам (работам, услугам) в пределах непродолжительного периода времени. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nРыночная цена определяется с учетом положений, предусмотренных пунктами 4 - 11 настоящей статьи. При этом учитываются обычные при заключении сделок между невзаимозависимыми лицами надбавки к цене или скидки. В частности, учитываются скидки, вызванные:\n\nсезонными и иными колебаниями потребительского спроса на товары (работы, услуги);\n\nпотерей товарами качества или иных потребительских свойств;\n\nистечением (приближением даты истечения) сроков годности или реализации товаров;\n\nмаркетинговой политикой, в том числе при продвижении на рынки новых товаров, не имеющих аналогов, а также при продвижении товаров (работ, услуг) на новые рынки;\n\nреализацией опытных моделей и образцов товаров в целях ознакомления с ними потребителей.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПри определении идентичности товаров учитываются, в частности, их физические характеристики, качество и репутация на рынке, страна происхождения и производитель. При определении идентичности товаров незначительные различия в их внешнем виде могут не учитываться. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nПри определении однородности товаров учитываются, в частности, их качество, наличие товарного знака, репутация на рынке, страна происхождения.\n\nАбзац. (Исключен - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\nПри этом условия сделок на рынке идентичных (а при их отсутствии - однородных) товаров, работ или услуг признаются сопоставимыми, если различие между такими условиями либо существенно не влияет на цену таких товаров, работ или услуг, либо может быть учтено с помощью поправок.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n(Пункт 10 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n10. При отсутствии на соответствующем рынке товаров, работ или услуг сделок по идентичным (однородным) товарам, работам, услугам или из-за отсутствия предложения на этом рынке таких товаров, работ или услуг, а также при невозможности определения соответствующих цен ввиду отсутствия либо недоступности информационных источников для определения рыночной цены используется метод цены последующей реализации, при котором рыночная цена товаров, работ или услуг, реализуемых продавцом, определяется как разность цены, по которой такие товары, работы или услуги реализованы покупателем этих товаров, работ или услуг при последующей их реализации (перепродаже), и обычных в подобных случаях затрат, понесенных этим покупателем при перепродаже (без учета цены, по которой были приобретены указанным покупателем у продавца товары, работы или услуги) и продвижении на рынок приобретенных у покупателя товаров, работ или услуг, а также обычной для данной сферы деятельности прибыли покупателя.\n\nПри невозможности использования метода цены последующей реализации (в частности, при отсутствии информации о цене товаров, работ или услуг, в последующем реализованных покупателем) используется затратный метод, при котором рыночная цена товаров, работ или услуг, реализуемых продавцом, определяется как сумма произведенных затрат и обычной для данной сферы деятельности прибыли. При этом учитываются обычные в подобных случаях прямые и косвенные затраты на производство (приобретение) и (или) реализацию товаров, работ или услуг, обычные в подобных случаях затраты на транспортировку, хранение, страхование и иные подобные затраты.\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 40. Принципы определения цены товаров, работ или услуг для целей налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1d54ce31514437f459378fa4c81cad2174d7aea45e24dd02ba4f75a4f409530"},{"code_id":"NK_RF","article_number":"43","version_date":"2000-07-31","article_text":"К дивидендам также относятся любые доходы, получаемые из источников за пределами Российской Федерации, относящиеся к дивидендам в соответствии с законодательствами иностранных государств. (Дополнение абзацем - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n1) выплаты при ликвидации организации акционеру (участнику) этой организации в денежной или натуральной форме, не превышающие взноса этого акционера (участника) в уставный (складочный) капитал организации; (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) выплаты акционерам (участникам) организации в виде передачи акций этой же организации в собственность;\n\n3) выплаты некоммерческой организации на осуществление ее основной уставной деятельности (не связанной с предпринимательской деятельностью), произведенные хозяйственными обществами, уставный капитал которых состоит полностью из вкладов этой некоммерческой организации. (Дополнение подпунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 43. Дивиденды и проценты","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a688ae912cf8a3ec774abbd55a8ae731d6e1f7229b517f7be51cd0f376d08b0d"},{"code_id":"NK_RF","article_number":"44","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Обязанность по уплате налога или сбора возникает, изменяется и прекращается при наличии оснований, установленных настоящим Кодексом или иным актом законодательства о налогах и сборах.\n\n2. Обязанность по уплате конкретного налога или сбора возлагается на налогоплательщика и плательщика сбора с момента возникновения установленных законодательством о налогах и сборах обстоятельств, предусматривающих уплату данного налога или сбора.\n\n3. Обязанность по уплате налога и (или) сбора прекращается:\n\n1) с уплатой налога и (или) сбора в случаях, предусмотренных настоящим Кодексом; (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 30.11.2016 № 401-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n3) со смертью физического лица - налогоплательщика или с объявлением его умершим в порядке, установленном гражданским процессуальным законодательством Российской Федерации. Задолженность по налогам, указанным в пункте 3 статьи 14 и пунктах 1 и 2 статьи 15 настоящего Кодекса, умершего лица либо лица, объявленного умершим, погашается наследниками в пределах стоимости наследственного имущества в порядке, установленном гражданским законодательством Российской Федерации для оплаты наследниками долгов наследодателя; (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 27.11.2017 № 335-ФЗ)\n\n4) с ликвидацией организации-налогоплательщика - после проведения всех расчетов с бюджетной системой Российской Федерации в соответствии со статьей 49 настоящего Кодекса; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n5) с возникновением иных обстоятельств, с которыми законодательство о налогах и сборах связывает прекращение обязанности по уплате соответствующего налога или сбора. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 44. Возникновение, изменение и прекращение обязанности по уплате налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e49fcae06682b95a4e84d78b9995b49125a4a058e6ab9e16eef03a47b21eb8b"},{"code_id":"NK_RF","article_number":"45","version_date":"2000-07-31","article_text":"1. Налогоплательщик обязан самостоятельно исполнить обязанность по уплате налога посредством перечисления денежных средств в качестве единого налогового платежа, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах.\n\nОбязанность по уплате налога должна быть исполнена в срок, установленный в соответствии с настоящим Кодексом. Налогоплательщик вправе перечислить денежные средства в счет исполнения обязанности по уплате налога до наступления установленного срока. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nПеречисление денежных средств в счет исполнения обязанности налогоплательщика по уплате налога может быть произведено иным лицом. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nИное лицо не вправе требовать возврата уплаченного за налогоплательщика единого налогового платежа и налога, уплаченного не в качестве единого налогового платежа. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2. Если иное не предусмотрено пунктами 4 и 5 настоящей статьи, в случае неуплаты или неполной уплаты налога в установленный срок производится взыскание задолженности в порядке, предусмотренном настоящим Кодексом.\n\n3. Взыскание задолженности с организации или индивидуального предпринимателя производится в порядке, предусмотренном статьями 46 и 47 настоящего Кодекса. Взыскание налога с физического лица, не являющегося индивидуальным предпринимателем, производится в порядке, предусмотренном статьей 48 настоящего Кодекса. Взыскание задолженности в судебном порядке производится:\n\n1) в целях взыскания задолженности, возникшей по итогам проведенной налоговой проверки, числящейся более трех месяцев:\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации зависимыми (дочерними) обществами (предприятиями), - с соответствующих основных (преобладающих, участвующих) обществ (предприятий), когда на их счета в банках поступает выручка за реализуемые товары (работы, услуги) зависимых (дочерних) обществ (предприятий);\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации основными (преобладающими, участвующими) обществами (предприятиями), - с зависимых (дочерних) обществ (предприятий), когда на их счета в банках поступает выручка за реализуемые товары (работы, услуги) основных (преобладающих, участвующих) обществ (предприятий);\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации зависимыми (дочерними) обществами (предприятиями), - с соответствующих основных (преобладающих, участвующих) обществ (предприятий), если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества основному (преобладающему, участвующему) обществу (предприятию) и если такая передача привела к невозможности взыскания указанной задолженности;\n\nза организациями, являющимися в соответствии с гражданским законодательством Российской Федерации основными (преобладающими, участвующими) обществами (предприятиями), - с зависимых (дочерних) обществ (предприятий), если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества зависимому (дочернему) обществу (предприятию) и если такая передача привела к невозможности взыскания указанной задолженности.\n\nЕсли налоговым органом в указанных случаях будет установлено, что выручка за реализуемые товары (работы, услуги) поступает на счета нескольких организаций, или если с момента, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки, произошла передача денежных средств, иного имущества нескольким основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям), взыскание задолженности производится с соответствующих организаций пропорционально доле поступившей им выручки за реализуемые товары (работы, услуги), доле переданных денежных средств, стоимости иного имущества.\n\nПоложения настоящего подпункта также применяются, если налоговым органом в указанных случаях будет установлено, что перечисление выручки за реализуемые товары (работы, услуги), передача денежных средств, иного имущества основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям) были произведены через совокупность взаимосвязанных операций, в том числе в случае, если участники указанных операций не являются основными (преобладающими, участвующими) обществами (предприятиями), зависимыми (дочерними) обществами (предприятиями).\n\nПоложения настоящего подпункта также применяются, если налоговым органом в указанных случаях будет установлено, что перечисление выручки за реализуемые товары (работы, услуги), передача денежных средств, иного имущества производятся лицам, признанным судом иным образом зависимыми с налогоплательщиком, за которым числится задолженность.\n\nПри применении положений настоящего подпункта взыскание может производиться в пределах поступившей основным (преобладающим, участвующим) обществам (предприятиям), зависимым (дочерним) обществам (предприятиям), лицам, признанным судом иным образом зависимыми с налогоплательщиком, за которым числится задолженность, выручки за реализуемые товары (работы, услуги), переданных денежных средств, иного имущества.\n\nСтоимость имущества в указанных в настоящем подпункте случаях определяется как остаточная стоимость имущества, отраженная в бухгалтерском учете организации на момент, когда организация, за которой числится задолженность, узнала или должна была узнать о назначении выездной налоговой проверки или о начале проведения камеральной налоговой проверки;\n\n2) с организации или физического лица, в том числе являющегося индивидуальным предпринимателем, если их обязанность по уплате налога основана на изменении налоговым органом юридической квалификации сделки, совершенной таким налогоплательщиком, или статуса и характера деятельности этого налогоплательщика. (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\nВ случае, указанном в абзаце первом настоящего подпункта, налоговый орган обращается в суд в течение шести месяцев со дня вступления в силу решений, указанных в подпункте 10 пункта 5 статьи 113 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n4. Взыскание задолженности, возникшей в связи с неуплатой или неполной уплатой налога декларантом, признаваемым таковым в соответствии с Федеральным законом от 8 июня 2015 года № 140-ФЗ \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) иным лицом, информация о котором содержится в специальной декларации, представленной в соответствии с указанным Федеральным законом, не производится. Взыскание задолженности на основании настоящего пункта не производится при соблюдении одного из следующих условий:\n\n1) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица в результате совершения до 1 января 2015 года операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 июля 2015 года по 30 июня 2016 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации;\n\n2) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2018 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 марта 2018 года по 28 февраля 2019 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний;\n\n3) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2019 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в период с 1 июня 2019 года по 29 февраля 2020 года, либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний;\n\n4) если обязанность по уплате такого налога возникла у декларанта и (или) иного лица до 1 января 2022 года в результате совершения операций, связанных с приобретением (формированием источников приобретения), использованием либо распоряжением имуществом (имущественными правами) и (или) контролируемыми иностранными компаниями, информация о которых содержится в специальной декларации, представленной в ходе четвертого этапа декларирования в соответствии с Федеральным законом от 8 июня 2015 года № 140-ФЗ \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", либо с открытием и (или) зачислением денежных средств на счета (вклады), информация о которых содержится в такой специальной декларации. При этом положения настоящего подпункта не распространяются на обязанность по уплате налогов, предусмотренных частью второй настоящего Кодекса, подлежащих уплате в отношении прибыли и (или) имущества контролируемых иностранных компаний.\n\n5. Сумма, подлежащая взысканию налоговыми органами на основании судебного акта, не может превышать размер отрицательного сальдо единого налогового счета налогоплательщика на дату исполнения такого судебного акта.\n\n6. Единый налоговый платеж учитывается на едином налоговом счете на основании информации, поступающей из Государственной информационной системы о государственных и муниципальных платежах, предусмотренной Федеральным законом от 27 июля 2010 года № 210-ФЗ \"Об организации предоставления государственных и муниципальных услуг\", со дня:\n\n1) предъявления в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства денежных средств со счета налогоплательщика (со счета иного лица в случае уплат\n\nы им налога за налогоплательщика) в банке при наличии на нем достаточного денежного остатка на день платежа;\n\n2) передачи физическим лицом в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства без открытия счета в банке денежных средств, предоставленных банку физическим лицом, при условии их достаточности для перечисления;\n\n3) отражения на лицевом счете организации, которой открыт лицевой счет, операции по перечислению соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n4) внесения физическим лицом в банк, кассу местной администрации, организацию федеральной почтовой связи либо в многофункциональный центр предоставления государственных и муниципальных услуг наличных денежных средств для их перечисления в бюджетную систему Российской Федерации на счет Федерального казначейства;\n\n5) перечисления судебным приставом-исполнителем денежных средств в качестве единого налогового платежа, взысканных в рамках исполнительного производства в соответствии с Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\". Денежные средства, перечисленные судебным приставом-исполнителем в качестве единого налогового платежа в рамках исполнительного производства в соответствии с Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", признаются уплаченными в счет исполнения требований по постановлению налогового органа о взыскании задолженности налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в бюджетную систему Российской Федерации за счет имущества либо судебного акта, содержащего требования о взыскании задолженности, вне зависимости от определения их принадлежности в соответствии с пунктом 8 настоящей статьи; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n6) предъявления в банк поручения на перечисление в бюджетную систему Российской Федерации на счет Федерального казначейства денежных средств со счета налогоплательщика или со счета иного лица в банке при наличии на нем достаточного денежного остатка на день платежа в счет возмещения ущерба, причиненного бюджетной системе Российской Федерации в результате преступлений, за совершение которых статьями 198 - 1992 Уголовного кодекса Российской Федерации предусмотрена уголовная ответственность. При этом зачет суммы указанных денежных средств в счет исполнения соответствующей обязанности по уплате налога производится в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n7. Обязанность по уплате налога считается исполненной (частично исполненной) налогоплательщиком, если иное не предусмотрено пунктом 13 настоящей статьи:\n\n1) со дня перечисления денежных средств в качестве единого налогового платежа в бюджетную систему Российской Федерации или со дня признания денежных средств в качестве единого налогового платежа при наличии на соответствующую дату учтенной на едином налоговом счете совокупной обязанности в части, в отношении которой может быть определена принадлежность таких сумм денежных средств в соответствии с пунктом 8 настоящей статьи;\n\n2) со дня, на который приходится срок уплаты налога, зачтенного в счет исполнения предстоящей обязанности по уплате такого налога; (В редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\n3) со дня учета на едином налоговом счете совокупной обязанности в соответствии с пунктом 5 статьи 113 настоящего Кодекса при наличии на эту дату положительного сальдо единого налогового счета в части, в отношении которой может быть определена принадлежность сумм денежных средств, уплаченных (перечисленных) в качестве единого налогового платежа, в соответствии с пунктом 8 настоящей статьи;\n\n4) со дня зачета сумм денежных средств, формирующих положительное сальдо единого налогового счета, на основании заявления, представленного в соответствии с абзацем третьим пункта 4 статьи 78 настоящего Кодекса;\n\n5) со дня перечисления денежных средств не в качестве единого налогового платежа в счет исполнения обязанности по уплате государственной пошлины, в отношении уплаты которой арбитражным судом не выдан исполнительный документ, налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности. (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nПеречни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\";\n\n(Подпункт в редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n6) со дня удержания налоговым агентом сумм налога, если обязанность по исчислению и удержанию налога из денежных средств налогоплательщика возложена в соответствии с настоящим Кодексом на налогового агента.\n\n8. Принадлежность сумм денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, определяется налоговыми органами на основании учтенной на едином налоговом счете налогоплательщика суммы его совокупной обязанности с соблюдением следующей последовательности:\n\n1) недоимка по налогу на доходы физических лиц - начиная с наиболее раннего момента ее возникновения;\n\n2) налог на доходы физических лиц - с момента возникновения обязанности по его перечислению налоговым агентом;\n\n3) недоимка по иным налогам, сборам, страховым взносам - начиная с наиболее раннего момента ее возникновения;\n\n4) иные налоги, авансовые платежи, сборы, страховые взносы - с момента возникновения обязанности по их уплате (перечислению);\n\n6) проценты;\n\n7) штрафы.\n\n(Пункт в редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\n1) отзыва лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога, или возврата банком такому лицу неисполненного поручения на перечисление соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n2) отзыва организацией, которой открыт лицевой счет, или возврата органом Федерального казначейства (иным уполномоченным органом, осуществляющим открытие и ведение лицевых счетов) организации неисполненного поручения на перечисление соответствующих денежных средств в бюджетную систему Российской Федерации;\n\n3) возврата местной администрацией, организацией федеральной почтовой связи либо многофункциональным центром предоставления государственных и муниципальных услуг физическому лицу наличных денежных средств, принятых для их перечисления в бюджетную систему Российской Федерации;\n\n4) неправильного указания налогоплательщиком или иным лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога за налогоплательщика, в поручении на перечисление суммы налога номера счета Федерального казначейства и (или) наименования банка получателя, повлекшего неперечисление этой суммы в бюджетную систему Российской Федерации на счет Федерального казначейства;\n\n5) если на день предъявления налогоплательщиком (иным лицом, предъявившим в банк поручение на перечисление в бюджетную систему Российской Федерации денежных средств в счет уплаты налога за налогоплательщика) в банк (орган Федерального казначейства, иной уполномоченный орган, осуществляющий открытие и ведение лицевых счетов) поручения на перечисление денежных средств в счет уплаты налога этот налогоплательщик (иное лицо) имеет иные неисполненные требования, которые предъявлены к его счету (лицевому счету) и в соответствии с гражданским законодательством Российской Федерации исполняются в первоочередном порядке, и если на этом счете (лицевом счете) нет достаточного остатка для удовлетворения всех требований.\n\nПри перечислении суммы денежных средств в счет исполнения обязанности по уплате налогов иным лицом за налогоплательщика в платежном поручении указывается идентификационный номер налогоплательщика, за которого перечислены указанные денежные средства. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45. Исполнение обязанности по уплате налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e59e603c9af1f39c3ddf5a40bd4bc78140cd99312a96b0ea0ba534cf3cb0db8a"},{"code_id":"NK_RF","article_number":"45.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 29.07.2018 № 232-ФЗ) (Утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1022a236d92f41c6e0578965926fd08718eb674d63ddb5c22cff4b1bceb14c25"},{"code_id":"NK_RF","article_number":"45.2","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 29.11.2021 № 379-ФЗ) (Утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 45.2. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0b96b9523744d5a2467e68a849356aa5c24fe96b3df96e71eea480b8e7c36ff"},{"code_id":"NK_RF","article_number":"46","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри отсутствии или недостаточности денежных средств (драгоценных металлов) на счетах инвестиционного товарищества и цифровых рублей на его счете цифрового рубля взыскание производится за счет денежных средств (драгоценных металлов) на счетах управляющих товарищей и цифровых рублей на их счетах цифрового рубля. При этом в первую очередь взыскание обращается на денежные средства (драгоценные металлы) на счетах управляющего товарища, ответственного за ведение налогового учета, цифровые рубли на его счете цифрового рубля. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри отсутствии или недостаточности денежных средств (драгоценных металлов) на счетах управляющих товарищей, их цифровых рублей взыскание обращается на денежные средства (драгоценные металлы) на счетах товарищей, их цифровые рубли пропорционально доле каждого из них в общем имуществе товарищей, определяемой на дату возникновения задолженности. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ случае изменения размера отрицательного сальдо единого налогового счета в реестре решений о взыскании задолженности размещается информация об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, по поручению налогового органа на перечисление цифровых рублей или по поручению налогового органа на перевод электронных денежных средств, в том числе в случае формирования положительного либо нулевого сальдо единого налогового счета. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПорядок ведения реестра решений о взыскании задолженности и размещения в указанном реестре решений о взыскании задолженности, поручений налоговых органов на перечисление суммы задолженности, поручений налогового органа на перечисление цифровых рублей, поручений налогового органа на перевод электронных денежных средств, а также информации об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, по поручению налогового органа на перечисление цифровых рублей или по поручению налогового органа на перевод электронных денежных средств, в том числе в случае формирования положительного либо нулевого сальдо единого налогового счета, и информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nВ поручении налогового органа на перечисление суммы задолженности должны указываться счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, с которых должно быть произведено перечисление денежных средств, и сумма денежных средств, подлежащая перечислению.\n\nРазмещение поручения налогового органа на перечисление суммы задолженности, поручения налогового органа на перечисление цифровых рублей и поручения налогового органа на перевод электронных денежных средств либо информации об изменении суммы задолженности, подлежащей перечислению по поручению налогового органа на перечисление суммы задолженности, в том числе в случае формирования положительного либо нулевого сальдо, в реестре решений о взыскании задолженности признается получением банком, а в отношении цифровых рублей оператором платформы цифрового рубля таких поручений либо информации об изменении суммы задолженности. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nб уплате задолженности. Решение о взыскании, принятое после истечения указанного срока, считается недействительным и исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с заявлением о взыскании задолженности с налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. Заявление может быть подано в суд в течение шести месяцев после истечения срока исполнения требования об уплате задолженности. Пропущенный по уважительной причине срок подачи заявления может быть восстановлен судом. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nРешение о взыскании доводится до сведения налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в течение шести дней после вынесения указанного решения по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. В случае невозможности передачи решения о взыскании указанными способами оно направляется по почте заказным письмом и считается полученным по истечении шести дней со дня направления заказного письма.\n\nВ случае увеличения суммы недоимки, подлежащей взысканию в соответствии с решением о взыскании, соответствующая информация доводится до сведения налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в течение шести дней после изменения в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа, по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nИнформация об изменении суммы задолженности, подлежащей взысканию в соответствии с решением о взыскании, размещается в личном кабинете налогоплательщика одновременно с изменением в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа.\n\nНа период, в течение которого сумма задолженности не учитывается в совокупной обязанности, действие решения о взыскании задолженности приостанавливается до даты восстановления учета суммы задолженности в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса. При этом в случае, если в течение указанного периода формируется отрицательное сальдо единого налогового счета, налоговый орган принимает решение о взыскании задолженности в порядке, предусмотренном абзацем первым настоящего пункта. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nЕсли на момент восстановления учета суммы задолженности в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса имеется неисполненное решение о взыскании задолженности, действие которого не приостановлено в соответствии с абзацем шестым настоящего пункта, действие решения о взыскании задолженности, приостановленного на период, указанный в абзаце шестом настоящего пункта, прекращается. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nВзыскание задолженности в соответствии с абзацем первым настоящего пункта осуществляется налоговым органом путем направления решений о взыскании на бумажном носителе или в электронной форме в орган, осуществляющий открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, по месту открытия лицевого счета налогоплательщика (налогового агента) в размере, не превышающем отрицательное сальдо единого налогового счета.\n\nПри неисполнении налогоплательщиком (налоговым агентом) - организацией решения о взыскании в течение трех месяцев со дня его поступления в орган, осуществляющий открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, этот орган информирует об этом налоговый орган, который направил ему решение о взыскании, в течение десяти дней по истечении указанного срока на бумажном носителе или в электронной форме.\n\nФорма, формат и порядок направления в органы, осуществляющие открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, решения о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) - организации, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Федеральным казначейством.\n\nФорма, формат и порядок направления уведомления о неисполнении решения о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) органами, осуществляющими открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, налоговым органам утверждаются Федеральным казначейством по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВзыскание задолженности с валютных счетов налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится в сумме, эквивалентной сумме платежа в рублях по курсу Центрального банка Российской Федерации, установленному на дату продажи валюты. При взыскании задолженности с валютных счетов налоговый орган наряду с размещением в реестре решений о взыскании задолженности поручения налогового органа на перечисление суммы задолженности размещает в указанном реестре поручение банку на продажу не позднее следующего дня иностранной валюты налогоплательщика (налогового агента) - организации или индивидуального предпринимателя и перечисление в этот же срок денежных средств от продажи иностранной валюты в сумме подлежащей взысканию задолженности на расчетный (текущий) счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя. Расходы, связанные с продажей иностранной валюты, осуществляются за счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\nВзыскание задолженности со счетов в драгоценных металлах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится исходя из стоимости драгоценных металлов, эквивалентной сумме платежа в рублях, которая определяется исходя из учетной цены на драгоценные металлы, установленной Центральным банком Российской Федерации на дату продажи драгоценных металлов. При взыскании задолженности со счетов в драгоценных металлах налоговый орган наряду с размещением в реестре решений о взыскании задолженности поручения налогового органа на перечисление суммы задолженности размещает в указанном реестре поручение банку на продажу не позднее следующего дня драгоценных металлов налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в размере, необходимом для исполнения поручения на перечисление суммы задолженности, и перечисление в этот же срок денежных средств от продажи драгоценных металлов на расчетный (текущий) счет налогоплательщика (налогового агента). Расходы, связанные с продажей драгоценных металлов, осуществляются за счет налогоплательщика (налогового агента).\n\nНе производится взыскание задолженности с депозитного счета (вклада в драгоценных металлах) налогоплательщика (налогового агента), если не истек срок действия депозитного договора (договора банковского вклада в драгоценных металлах).\n\nПри наличии депозитного договора налоговый орган вправе дать банку поручение на перечисление по истечении срока действия депозитного договора денежных средств с депозитного счета на расчетный (текущий) счет налогоплательщика (налогового агента) посредством его размещения в реестре решений о взыскании задолженности, если к этому времени не будет исполнено банком размещенное в реестре решений о взыскании задолженности поручение налогового органа на перечисление суммы задолженности.\n\nПри наличии договора банковского вклада в драгоценных металлах налоговый орган вправе дать банку поручение на продажу драгоценных металлов в размере, необходимом для исполнения поручения на перечисление суммы задолженности, посредством его размещения в реестре решений о взыскании задолженности по истечении срока действия указанного договора и перечисление денежных средств от продажи драгоценных металлов в сумме подлежащей взысканию задолженности на расчетный (текущий) счет налогоплательщика (налогового агента), если к этому времени не будет исполнено банком размещенное в реестре решений о взыскании задолженности поручение налогового органа на перечисление суммы задолженности.\n\nФормы и форматы поручений налоговых органов банкам на продажу иностранной валюты и драгоценных металлов налогоплательщиков (налоговых агентов) - организаций и индивидуальных предпринимателей утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации.\n\nПри недостаточности или отсутствии денежных средств (драгоценных металлов) на счетах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения банком поручения налогового органа на перечисление сумм задолженности такое поручение исполняется по мере поступления денежных средств (драгоценных металлов) на эти счета в течение одного операционного дня такого поступления на рублевые счета, в течение двух операционных дней каждого такого поступления на валютные счета, в течение двух операционных дней каждого такого поступления на счета в драгоценных металлах.\n\n10. При недостаточности или отсутствии денежных средств на счетах налогоплательщика (налогового агента) - организации или индивидуального предпринимателя налоговый орган вправе взыскать задолженность за счет электронных денежных средств.\n\nВзыскание задолженности за счет электронных денежных средств налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится путем направления в банк, в котором находятся электронные денежные средства, поручения налогового органа на перевод электронных денежных средств на счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в банке.\n\nПоручение налогового органа на перевод электронных денежных средств должно содержать указание реквизитов корпоративного электронного средства платежа налогоплательщика (персонифицированных электронных средств платежа) (налогового агента) - организации или индивидуального предпринимателя, с использованием которого должен быть осуществлен перевод электронных денежных средств, указание подлежащей переводу суммы, а также реквизитов счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\nВзыскание задолженности может производиться за счет остатков электронных денежных средств в рублях, а при их недостаточности за счет остатков электронных денежных средств в иностранной валюте. При взыскании задолженности за счет остатков электронных денежных средств в иностранной валюте и указании в поручении налогового органа на перевод электронных денежных средств валютного счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя банк осуществляет перевод электронных денежных средств на этот счет.\n\nПри взыскании задолженности за счет остатков электронных денежных средств в иностранной валюте и указании в поручении налогового органа на перевод электронных денежных средств с рублевого счета налогоплательщика (налогового агента) - организации или индивидуального предпринимателя руководитель (заместитель руководителя) налогового органа одновременно с поручением налогового органа на перевод электронных денежных средств направляет поручение банку на продажу не позднее следующего дня иностранной валюты налогоплательщика (налогового агента) - организации или индивидуального предпринимателя. Расходы, связанные с продажей иностранной валюты, осуществляются за счет налогоплательщика (налогового агента). Банк осуществляет перевод электронных денежных средств на рублевый счет налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в сумме, эквивалентной сумме платежа в рублях по курсу Центрального банка Российской Федерации, установленному на дату перевода электронных денежных средств.\n\nПри недостаточности или отсутствии электронных денежных средств налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения банком поручения налогового органа на перевод электронных денежных средств такое поручение исполняется по мере получения электронных денежных средств.\n\nПоручение налогового органа на перевод электронных денежных средств исполняется банком не позднее одного операционного дня, следующего за днем получения им указанного поручения, если взыскание задолженности производится за счет остатков электронных денежных средств в рублях, и не позднее двух операционных дней, если взыскание налога производится за счет остатков электронных денежных средств в иностранной валюте.\n\nВзыскание задолженности за счет цифровых рублей налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится путем направления оператору платформы цифрового рубля поручения налогового органа на перечисление цифровых рублей.\n\nПоручение налогового органа на перечисление цифровых рублей должно содержать указание реквизитов счета цифрового рубля налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, с которого должно быть произведено перечисление, указание подлежащей перечислению суммы.\n\nПоручение налогового органа на перечисление цифровых рублей исполняется оператором платформы цифрового рубля не позднее одного операционного дня, следующего за днем получения им указанного поручения.\n\nПри недостаточности или отсутствии цифровых рублей налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в день получения оператором платформы цифрового рубля поручения налогового органа на перечисление цифровых рублей такое поручение исполняется по мере получения цифровых рублей.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nПоложения абзаца первого настоящего пункта применяются в отношении налогоплательщика (налогового агента) - организации при поступлении в налоговый орган уведомления органа, осуществляющего открытие и ведение лицевых счетов в соответствии с бюджетным законодательством Российской Федерации, о невозможности исполнения решения налогового органа о взыскании за счет денежных средств, отраженных на лицевых счетах налогоплательщика (налогового агента) - организации.\n\n14. Со дня отзыва у кредитной организации лицензии на осуществление банковских операций взыскание задолженности за счет денежных средств (драгоценных металлов) на счетах в такой кредитной организации производится с учетом положений Федерального закона \"О банках и банковской деятельности\" и Федерального закона от 26 октября 2002 го\n\nда № 127-ФЗ \"О несостоятельности (банкротстве)\".\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 46. Взыскание задолженности за счет денежных средств (драгоценных металлов) на счетах налогоплательщика (плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя или налогового агента - организации, индивидуального предпринимателя в банках, а также за счет его электронных денежных средств и цифровых рублей на счетах цифрового рубля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c38ff45064d8d001905c777d600bf31100ca1845c9df45fb57728f163e8b3f01"},{"code_id":"NK_RF","article_number":"47","version_date":"2000-07-31","article_text":"1. В случае, предусмотренном пунктом 11 статьи 46 настоящего Кодекса, налоговый орган вправе взыскать задолженность за счет имущества, в том числе за счет наличных денежных средств, налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, не утратившего свой статус на дату принятия постановления о взыскании задолженности (далее в настоящей статье - индивидуальный предприниматель), в пределах сумм, не превышающих отрицательное сальдо единого налогового счета, и с учетом сумм, в отношении которых произведено взыскание в соответствии со статьей 46 настоящего Кодекса.\n\nВзыскание задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится на основании постановления налогового органа о взыскании задолженности налогоплательщика (налогового агента) - организации или индивидуального предпринимателя в бюджетную систему Российской Федерации за счет имущества (далее - постановление о взыскании задолженности), размещенного в реестре решений о взыскании задолженности.\n\n2. Направление постановления о взыскании задолженности судебному приставу-исполнителю для исполнения осуществляется в порядке, предусмотренном Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", с учетом особенностей, предусмотренных настоящей статьей.\n\nОдновременно с направлением постановления о взыскании задолженности налоговый орган размещает указанное постановление в реестре решений о взыскании задолженности с указанием сведений о его отправке судебному приставу-исполнителю. При поступлении от судебного пристава-исполнителя постановления о наложении ареста и (или) постановления об обращении взыскания на денежные средства (электронные денежные средства), цифровые рубли налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, находящиеся в банке, на счете цифрового рубля, действие поручения налогового органа на перечисление соответствующей суммы задолженности, размещенного в реестре решений о взыскании задолженности в соответствии со статьей 46 настоящего Кодекса, приостанавливается до исполнения указанного постановления в полном объеме или его отмены. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\n3. Направление судебному приставу и размещение постановления о взыскании задолженности в реестре решений о взыскании задолженности осуществляются в течение десяти месяцев:\n\nлибо с даты размещения в реестре решений о взыскании задолженности решения о взыскании задолженности в размере отрицательного сальдо единого налогового счета, превышающем 30 тысяч рублей;\n\nлибо с даты окончания исполнительного производства по ранее размещенному постановлению при наличии отрицательного сальдо на едином налоговом счете в размере, превышающем 30 тысяч рублей;\n\nлибо с даты возникновения после размещения в реестре решений о взыскании задолженности предшествующего постановления новой суммы задолженности на едином налоговом счете в размере, превышающем 30 тысяч рублей;\n\nлибо по истечении трех лет с даты размещения в реестре решений о взыскании задолженности решения о взыскании задолженности в размере отрицательного сальдо единого налогового счета, не превышающем 30 тысяч рублей.\n\n4. Постановление о взыскании задолженности, размещенное после истечения срока, установленного пунктом 3 настоящей статьи, исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с заявлением о взыскании с налогоплательщика (налогового агента) - организации или индивидуального предпринимателя задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса. Заявление может быть подано в суд в течение двух лет со дня истечения сроков, указанных в пункте 3 настоящей статьи. Пропущенный по уважительной причине срок подачи заявления может быть восстановлен судом.\n\nПостановление о взыскании задолженности, в отношении которой вынесен судебный акт, размещается в реестре решений о взыскании задолженности одновременно с информацией о таком судебном акте, вступившем в законную силу.\n\n5. Постановление о взыскании задолженности должно соответствовать требованиям к исполнительным документам, установленным Федеральным законом от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", а также содержать:\n\n1) наименование налогового органа, выдавшего указанное постановление;\n\n2) дату принятия и номер решения налогового органа о взыскании задолженности;\n\n3) идентификационный номер налогоплательщика, наименование и адрес налогоплательщика (налогового агента) - организации либо фамилию, имя, отчество, паспортные данные, адрес места жительства налогоплательщика (налогового агента) - индивидуального предпринимателя, на чье имущество обращается взыскание;\n\n4) дату выдачи указанного постановления.\n\n6. Исполнительные действия должны быть совершены и требования, содержащиеся в постановлении, исполнены судебным приставом-исполнителем в двухмесячный срок со дня возбуждения соответствующего исполнительного производства.\n\n7. Взыскание задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя производится последовательно в отношении:\n\n1) наличных денежных средств, денежных средств и драгоценных металлов, за исключением счетов в банках, в отношении которых направлены поручения в соответствии со статьей 46 настоящего Кодекса;\n\n2) имущества, не участвующего непосредственно в производстве продукции (товаров), в частности ценных бумаг, валютных ценностей, непроизводственных помещений, легкового автотранспорта, предметов дизайна служебных помещений;\n\n3) готовой продукции (товаров), а также иных материальных ценностей, не участвующих и (или) не предназначенных для непосредственного участия в производстве;\n\n4) сырья и материалов, предназначенных для непосредственного участия в производстве, а также станков, оборудования, зданий, сооружений и других основных средств;\n\n5) имущества, переданного по договору во владение, в пользование или распоряжение другим лицам без перехода к ним права собственности на это имущество, если для обеспечения исполнения обязанности по уплате налога такие договоры расторгнуты или признаны недействительными в установленном порядке;\n\n6) другого имущества, за исключением предназначенного для повседневного личного пользования индивидуальным предпринимателем или членами его семьи, определяемого в соответствии с законодательством Российской Федерации.\n\n8. Взыскание задолженности в части налога, подлежащего уплате участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, в связи с выполнением договора инвестиционного товарищества (за исключением налога на прибыль организаций, возникающего в связи с участием данного товарища в договоре инвестиционного товарищества) производится за счет общего имущества товарищей.\n\nПри отсутствии или недостаточности общего имущества товарищей взыскание производится за счет имущества управляющих товарищей. При этом в первую очередь взыскание обращается на имущество управляющего товарища, ответственного за ведение налогового учета.\n\nВ случае отсутствия или недостаточности имущества управляющих товарищей взыскание обращается на имущество товарищей пропорционально доле каждого из них в общем имуществе товарищей, определяемой на дату возникновения задолженности.\n\n9. В случае взыскания задолженности за счет имущества налогоплательщика (налогового агента), не являющегося денежными средствами, обязанность по уплате налога, сбора, страховых взносов, пеней, штрафов считается исполненной с момента погашения задолженности в пределах сумм денежных средств, вырученных от реализации такого имущества.\n\n10. Должностные лица налоговых органов (таможенных органов) не вправе приобретать имущество налогоплательщика (налогового агента) - организации или индивидуального предпринимателя, реализуемое в порядке исполнения решения о взыскании задолженности за счет имущества налогоплательщика (налогового агента) - организации или индивидуального предпринимателя.\n\n11. Положения настоящей статьи применяются также при взыскании задолженности в части уплаты сборов, страховых взносов, пеней, штрафов, процентов в случаях, предусмотренных настоящим Кодексом.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 47. Взыскание задолженности за счет иного имущества налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов) - организации, индивидуального предпринимателя","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8397fffdc7c4b8b2bee0cdfb5a363877600b30c6c67f248bfaed75198e5ae5a0"},{"code_id":"NK_RF","article_number":"48","version_date":"2000-07-31","article_text":"1. В случае неисполнения налогоплательщиком (плательщиком сбора, плательщиком страховых взносов) - физическим лицом, не являющимся индивидуальным предпринимателем (утратившим статус индивидуального предпринимателя) (далее в настоящей статье - физическое лицо), в установленный срок обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов налоговый орган обращает взыскание на имущество физического лица в размере, не превышающем отрицательное сальдо единого налогового счета, посредством размещения в реестре решений о взыскании задолженности в соответствии со статьями 46 и 47 настоящего Кодекса решения о взыскании задолженности, поручения налогового органа на перечисление суммы задолженности, информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, постановления о взыскании задолженности.\n\nК решениям о взыскании задолженности, поручениям на перечисление суммы задолженности, информации о счетах, по которым подлежат приостановлению операции, и постановлениям о взыскании задолженности, указанным в настоящей статье, применяются правила, предусмотренные статьями 46, 47 и 76 настоящего Кодекса, если иное не предусмотрено настоящей статьей.\n\n2. В целях настоящей статьи принятие решения о взыскании задолженности и его направление физическому лицу осуществляются в течение шести месяцев с даты истечения срока исполнения требования об уплате задолженности.\n\nРешение о взыскании задолженности, принятое после истечения указанного срока, считается недействительным и исполнению не подлежит. В этом случае налоговый орган может обратиться в суд с административным исковым заявлением о взыскании задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 2 пункта 7 статьи 113 настоящего Кодекса, в течение шести месяцев после истечения срока, установленного абзацем первым настоящего пункта для принятия решения о взыскании задолженности. Пропущенный по уважительной причине срок подачи административного искового заявления может быть восстановлен судом.\n\nРешение о взыскании задолженности направляется физическому лицу через личный кабинет налогоплательщика или через личный кабинет на едином портале государственных и муниципальных услуг. В случае невозможности передачи указанными способами такое решение направляется по почте заказным письмом.\n\nФизическому лицу информация об увеличении суммы задолженности, подлежащей взысканию в соответствии с решением о взыскании задолженности, направляется в электронной форме через личный кабинет налогоплательщика или личный кабинет на едином портале государственных и муниципальных услуг в течение шести дней после изменения в реестре решений о взыскании задолженности суммы задолженности, подлежащей перечислению по поручению налогового органа.\n\n3. Взыскание задолженности за счет имущества физического лица производится последовательно в отношении:\n\n1) денежных средств на счетах в банке и электронных денежных средств, переводы которых осуществляются с использованием персонифицированных электронных средств платежа, драгоценных металлов на счетах (во вкладах) в банке, цифровых рублей;\n\n2) наличных денежных средств;\n\n3) имущества, переданного по договору во владение, в пользование или распоряжение другим лицам без перехода к ним права собственности на это имущество, если для обеспечения исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов такой договор расторгнут или признан недействительным в установленном порядке;\n\n4) другого имущества, за исключением предназначенного для повседневного личного пользования физическим лицом или членами его семьи, определяемого в соответствии с законодательством Российской Федерации.\n\n4. Взыскание задолженности за счет имущества физического лица, которое производится в отношении денежных средств на счетах в банке и электронных денежных средств, переводы которых осуществляются с использованием персонифицированных электронных средств платежа, драгоценных металлов на счетах (во вкладах) в банке, цифровых рублей, осуществляется налоговым органом посредством размещения по истечении семи дней со дня направления физическому лицу решения о взыскании задолженности соответствующего поручения налогового органа на перечисление суммы задолженности и информации о счетах, по которым подлежат приостановлению операции в соответствии с пунктом 2 статьи 76 настоящего Кодекса, в реестре решений о взыскании задолженности. Поручение налогового органа на перечисление суммы задолженности и приостановление операций по счетам исполняются банком (а в отношении цифровых рублей - оператором платформы цифрового рубля) в соответствии со статьей 46 настоящего Кодекса с применением порядка, предусмотренного законодательством Российской Федерации об исполнительном производстве и нормами федеральных законов, регулирующими условия и порядок принудительного исполнения судебных актов, актов других органов и должностных лиц, для обращения взыскания на денежные средства по исполнительному документу. При этом:\n\n1) при исполнении банком поручения налогового органа на перечисление суммы задолженности и приостановления операций по счетам не допускается обращение взыскания на виды доходов, в отношении которых установлены ограничения размера удержания и (или) на которые не может быть обращено взыскание в соответствии со статьями 99 и 101 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\";\n\n2) физическое лицо вправе обратиться в банк, исполняющий поручение налогового органа на перечисление суммы задолженности с его счета и приостановление операций по счетам, с заявлением о сохранении заработной платы и иных доходов ежемесячно в порядке и на условиях, которые предусмотрены статьей 8 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\" для исполнения содержащихся в исполнительном документе требований о взыскании денежных средств;\n\n3) поручение налогового органа на перечисление суммы задолженности и приостановление операций по счетам не действуют в отношении специальных избирательных счетов, специальных счетов фондов референдума и иных счетов в части сумм денежных средств, право собственности на которые не принадлежит владельцу соответствующего счета и на которые в соответствии с законодательством Российской Федерации не может быть обращено взыскание по обязательствам владельца этого счета.\n\n5. При неисполнении (частичном неисполнении) поручения налогового органа на перечисление суммы задолженности и при наличии отрицательного сальдо единого налогового счета налоговый орган для взыскания задолженности за счет иного имущества физического лица направляет судебному приставу-исполнителю и одновременно размещает в реестре решений о взыскании задолженности постановление о взыскании задолженности в порядке и сроки, которые установлены статьей 47 настоящего Кодекса.\n\n6. Денежные средства, поступившие в счет исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов в соответствии с настоящей статьей, учитываются в качестве единого налогового платежа и определяются по принадлежности в соответствии со статьей 45 настоящего Кодекса.\n\n7. Должностные лица налоговых органов (таможенных органов) не вправе приобретать имущество физического лица, реализуемое в порядке взыскания налога, сбора, страховых взносов, пеней, штрафов, процентов за счет имущества физического лица.\n\n8. Для применения мер взыскания в соответствии с настоящей статьей в отношении задолженности в размере сумм, не учитываемых в совокупной обязанности в соответствии с подпунктом 101 пункта 5, подпунктами 31 - 33 пункта 7 статьи 113 настоящего Кодекса, налоговый орган обращается в суд с административным исковым заявлением (далее - административное исковое заявление о взыскании задолженности) в следующих случаях:\n\n1) если физическим лицом в течение тридцати дней со дня формирования налоговым органом сообщения об отказе в перерасчете суммы ранее исчисленного налога подана жалоба в отношении сумм налогов, указанных в налоговом уведомлении, либо со дня принятия решения вышестоящего налогового органа об оставлении без удовлетворения жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, представлено уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении. В случае пропуска по уважительной причине срока, предусмотренного настоящим подпунктом, этот срок может быть восстановлен налоговым органом по ходатайству физического лица, подаваемому одновременно с жалобой в отношении сумм налогов, указанных в налоговом уведомлении (уведомлением о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении), если обязанность по уплате соответствующих сумм налогов не исполнена на дату подачи такого ходатайства. По результатам рассмотрения ходатайства о восстановлении пропущенного срока, указанного в настоящем подпункте, налоговый орган выносит решение, которое не позднее трех дней со дня получения такого ходатайства направляется физическому лицу в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг или по почте заказным письмом;\n\n2) если физическим лицом подана жалоба (апелляционная жалоба) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично.\n\n9. Уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, представляется в налоговый орган, направивший налоговое уведомление.\n\nФорма и формат уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nУведомление о несогласии с решением вышестоящего налог\n\nового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, может быть представлено физическим лицом в налоговый орган лично или через представителя либо направлено в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо на бумажном носителе через многофункциональный центр предоставления государственных и муниципальных услуг или по почте заказным письмом.\n\n10. В случаях, предусмотренных пунктом 8 настоящей статьи, налоговый орган обращается в суд с административным исковым заявлением о взыскании задолженности в течение шести месяцев:\n\n1) со дня принятия налоговым органом решения по жалобе в отношении сумм налогов, указанных в налоговом уведомлении, поданной в течение тридцати дней со дня формирования сообщения об отказе в перерасчете сумм ранее исчисленного налога, либо со дня представления физическим лицом уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, в течение тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении такой жалобы без удовлетворения, если размер задолженности превышает три тысячи рублей;\n\n2) со дня принятия налоговым органом решения по жалобе (апелляционной жалобе) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, если размер задолженности превышает три тысячи рублей;\n\n3) со дня превышения общей суммы задолженности, подлежащей взысканию в судебном порядке, трех тысяч рублей;\n\n4) по истечении трех лет с наиболее ранней даты принятия налоговым органом решения по жалобе в отношении сумм налогов, указанных в налоговом уведомлении, поданной в течение тридцати дней со дня формирования сообщения об отказе в перерасчете суммы ранее исчисленного налога, либо с наиболее ранней даты представления физическим лицом уведомления о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, в течение тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении такой жалобы без удовлетворения, если общая сумма задолженности, подлежащая взысканию в судебном порядке, не превысила трех тысяч рублей;\n\n5) по истечении трех лет с наиболее ранней даты принятия налоговым органом решения по жалобе (апелляционной жалобе) на решение о привлечении к ответственности за совершение налогового правонарушения (решение об отказе в привлечении к ответственности за совершение налогового правонарушения), решение об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, если общая сумма задолженности, подлежащая взысканию в судебном порядке, не превысила трех тысяч рублей.\n\n11. К административному исковому заявлению о взыскании задолженности может прилагаться ходатайство налогового органа о применении мер предварительной защиты.\n\nПропущенный по уважительной причине срок подачи административного искового заявления о взыскании задолженности может быть восстановлен судом.\n\n12. В случае исполнения физическим лицом обязанности по уплате соответствующих сумм задолженности, не учитываемых в совокупной обязанности в соответствии с подпунктом 101 пункта 5, подпунктами 31 - 33 пункта 7 статьи 113 настоящего Кодекса, положения пунктов 8 - 11 настоящей статьи не применяются.\n\n13. Действие правил, предусмотренных настоящей статьей, также распространяется на налоговых агентов - физических лиц, утративших статус индивидуального предпринимателя на дату принятия решения о взыскании задолженности или являющихся нотариусами, занимающимися частной практикой, адвокатами, учредившими адвокатские кабинеты, и другими лицами, занимающимися в установленном законодательством Российской Федерации порядке частной практикой.\n\n(Статья в редакции  Федерального закона от 31.07.2025 № 287-ФЗ)","article_title":"Статья 48. Взыскание задолженности за счет имущества налогоплательщика (плательщика сборов, плательщика страховых взносов) - физического лица, не являющегося индивидуальным предпринимателем","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fae62c573d02b335acaa2362867683d7fac26e3fe832779127003617e5b60904"},{"code_id":"NK_RF","article_number":"49","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 49. Исполнение обязанности по уплате налогов, сборов, страховых взносов (пеней, штрафов) при ликвидации организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e8f7509e9e7b22a0adb706c8d845d8a5a06f61adaf6afdb69ec5c68318dcbe3"},{"code_id":"NK_RF","article_number":"5","version_date":"2000-07-31","article_text":"1. Акты законодательства о налогах вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования и не ранее 1-го числа очередного налогового периода по соответствующему налогу, за исключением случаев, предусмотренных настоящей статьей.\n\nАкты законодательства о сборах вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования, за исключением случаев, предусмотренных настоящей статьей.\n\nАкты законодательства о налогах и сборах в части регулирования страховых взносов вступают в силу не ранее чем по истечении одного месяца со дня их официального опубликования и не ранее 1-го числа очередного расчетного периода по страховым взносам, за исключением случаев, предусмотренных настоящей статьей. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nФедеральные законы, вносящие изменения в настоящий Кодекс в части установления новых налогов (за исключением специальных налоговых режимов) и (или) сборов, а также акты законодательства о налогах и сборах субъектов Российской Федерации, нормативные правовые акты представительных органов муниципальных образований, нормативные правовые акты представительного органа федеральной территории \"Сириус\", вводящие налоги, вступают в силу не ранее 1 января года, следующего за годом их принятия, но не ранее одного месяца со дня их официального опубликования. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2006 № 137-ФЗ, от 11.06.2021 № 199-ФЗ, от 25.02.2022 № 18-ФЗ)\n\nАкты законодательства о налогах и сборах, указанные в пунктах 3 и 4 настоящей статьи, могут вступать в силу в сроки, прямо предусмотренные этими актами, но не ранее даты их официального опубликования. (Дополнение абзацем - Федеральный закон от 26.11.2008 № 224-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nдаты утраты налогоплательщиком статуса участника специального инвестиционного контракта;\n\nдаты окончания сроков действия налоговых ставок, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения специального инвестиционного контракта, если дата окончания сроков действия налоговых ставок,  налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения специального инвестиционного контракта, наступает ранее даты утраты налогоплательщиком статуса налогоплательщика - участника специального инвестиционного контракта. (В редакции Федерального закона от 02.08.2019 № 269-ФЗ)\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части налога на прибыль организаций, налога на имущество организаций, транспортного налога, земельного налога и применяются для налогоплательщика - участника специального инвестиционного контракта при условии указания в соответствующем специальном инвестиционном контракте ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов и сборов), установленных для налогоплательщиков - участников специальных инвестиционных контрактов в связи с выполнением ими специального инвестиционного контракта, на которые распространяется действие настоящего пункта. (В редакции Федерального закона от 02.08.2019 № 269-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 23.05.2016 № 144-ФЗ) (В редакции Федерального закона от 03.08.2018 № 300-ФЗ)\n\nдаты утраты налогоплательщиком статуса соответственно резидента территории опережающего развития, резидента свободного порта Владивосток или резидента особой экономической зоны;\n\nдаты окончания сроков действия налоговых ставок, тарифов  страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения соглашения об осуществлении деятельности, указанного в абзаце первом настоящего пункта, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения такого соглашения, наступает ранее даты утраты налогоплательщиком статуса резидента территории опережающего развития, резидента свободного порта Владивосток или резидента особой экономической зоны.\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, транспортного налога, земельного налога и применяются для налогоплательщика - резидента территории опережающего развития, резидента свободного порта Владивосток и резидента особой экономической зоны при условии указания в соответствующем соглашении об осуществлении деятельности ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок, тарифов страховых взносов или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов и сборов), установленных для налогоплательщиков - резидентов территорий опережающего развития, налогоплательщиков - резидентов свободного порта Владивосток и налогоплательщиков - резидентов особых экономических зон в связи с исполнением ими соглашений об осуществлении деятельности, на которые распространяется действие настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 300-ФЗ) (В редакции  Федерального закона от 02.11.2023 № 522-ФЗ)\n\nВ отношении налогоплательщиков, являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с субъектом Российской Федерации, не применяются положения последующих актов законодательства о налогах и сборах в части изменения порядка определения налоговой базы, налоговых ставок, налоговых льгот, порядка и (или) сроков уплаты по налогу на имущество организаций и транспортному налогу.\n\nВ отношении налогоплательщиков (плательщиков сборов), являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с Российской Федерацией и субъектом Российской Федерации, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзаце втором настоящего пункта, а также в части изменения объекта налогообложения, порядка определения налоговой базы, налогового периода, налоговых ставок, порядка исчисления, порядка и (или) сроков уплаты по налогу на прибыль организаций, изменения сроков уплаты и (или) порядка возмещения налога на добавленную стоимость и (или) введения новых налогов и (или) сборов.\n\nВ отношении налогоплательщиков, являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с субъектом Российской Федерации и муниципальным образованием, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзаце втором настоящего пункта, а также в части изменения налоговых ставок, налоговых льгот, порядка и (или) сроков уплаты по земельному налогу.\n\nВ отношении налогоплательщиков (плательщиков сборов), являющихся стороной соответствующего соглашения о защите и поощрении капиталовложений, заключенного с Российской Федерацией, субъектом Российской Федерации и муниципальным образованием, не применяются положения последующих актов законодательства о налогах и сборах в части изменений, указанных в абзацах втором - четвертом настоящего пункта.\n\nВ отношении налогоплательщика, являющегося стороной соглашения о защите и поощрении капиталовложений, одной из сторон которого также является Российская Федерация, и реализующего новый инвестиционный проект в сфере добычи руд цветных металлов (золота) с объемом капитальных вложений не менее 300 миллиардов рублей, включенного в реестр участников региональных инвестиционных проектов, не применяются положения последующих актов законодательства о налогах и сборах в части изменения или отмены порядка определения и применения коэффициента, характеризующего территорию добычи полезного ископаемого, при исчислении налога на добычу полезных ископаемых. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\nОсобенности применения актов законодательства о налогах и сборах, предусмотренные настоящим пунктом, не распространяются на последующие акты законодательства о налогах и сборах, устанавливающие налоговые льготы по налогу на имущество организаций, транспортному и земельному налогам, условия и сроки применения и прекращения действия указанных льгот.\n\nПоложения настоящего пункта применяются в отношении указанных налогоплательщиков (плательщиков сборов) до наступления наиболее ранней из следующих дат:\n\nдаты истечения указанного в реестре срока применения стабилизационной оговорки, установленного соответствующим соглашением о защите и поощрении капиталовложений в соответствии с частями 10 и 11 статьи 10 Федерального закона \"О защите и поощрении капиталовложений в Российской Федерации\";\n\nдаты включения сведений о расторжении соответствующего соглашения о защите и поощрении капиталовложений в реестр.\n\nЕсли иное не предусмотрено настоящим пунктом, положения настоящего пункта применяются в отношении налогоплательщиков (плательщиков сборов) при условии ведения ими раздельного учета объектов налогообложения, налоговой базы и сумм налогов по налогам, подлежащим уплате при исполнении соглашений о защите и поощрении капиталовложений, указанных в абзацах втором - пятом настоящего пункта, и при осуществлении иной хозяйственной деятельности, а также раздельного учета доходов (расходов), полученных (понесенных) при исполнении соглашений, указанных в абзацах третьем и пятом настоящего пункта, и доходов (расходов), полученных (понесенных) при осуществлении иной хозяйственной деятельности.\n\nНалогоплательщик (плательщик сбора), являющийся стороной соглашения о защите и поощрении капиталовложений, в соответствии с Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" признаваемый проектной компанией, раздельный учет, предусмотренный абзацем одиннадцатым настоящего пункта: (В редакции  Федерального закона от 28.06.2022 № 225-ФЗ)\n\nвправе не вести в случае, если он не является одновременно участником консолидированной группы налогоплательщиков;\n\nведет в части, касающейся соблюдения им положений пункта 9 статьи 2781 настоящего Кодекса, в случае, если он одновременно является участником консолидированной группы налогоплательщиков.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 70-ФЗ)\n\nдаты утраты налогоплательщиком статуса международной холдинговой компании;\n\nдаты окончания установленного на дату приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной холдинговой компании в соответствии со статьей 242 настоящего Кодекса срока действия:\n\nналоговых ставок;\n\nпорядка исчисления налогов;\n\nпорядка исчисления налоговых баз.\n\nПоложения актов законодательства субъектов Российской Федерации о налогах и сборах в части налога на имущество организаций и транспортного налога в случае, если такие положения вступили в силу после даты приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной х\n\nолдинговой компании и предусматривают увеличение и (или) отмену пониженных налоговых ставок, а также изменение условий применения указанных налоговых ставок, не применяются в отношении налогоплательщика, признаваемого международной холдинговой компанией в соответствии со статьей 242 настоящего Кодекса, до наступления наиболее ранней из следующих дат:\n\nдаты утраты налогоплательщиком статуса международной холдинговой компании;\n\nдаты окончания установленного на дату приобретения международной компанией (организацией, указанной в пункте 11 статьи 242 настоящего Кодекса) статуса международной холдинговой компании в соответствии со статьей 242 настоящего Кодекса срока действия:\n\nналоговых ставок;\n\nусловий применения указанных налоговых ставок.\n\n(Дополнение пунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\nдаты утраты налогоплательщиком (плательщиком страховых взносов) статуса участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях; (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nдаты окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату заключения указанного договора, наступает ранее даты утраты налогоплательщиком (плательщиком страховых взносов) статуса участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, земельного налога и применяются для налогоплательщика (плательщика страховых взносов) - участника свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях при условии указания в соответствующем договоре об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях ссылок на положения актов законодательства о налогах и сборах в части пониженных налоговых ставок, тарифов страховых взносов или налоговых льгот и иных преференций (включая особый порядок и сроки уплаты, порядок исчисления налогов), установленных для налогоплательщиков (плательщиков страховых взносов) - участников свободной экономической зоны на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях в связи с исполнением ими договоров об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях, на которые распространяется действие настоящего пункта. (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.06.2023 № 268-ФЗ)\n\nдаты исключения резидента из единого реестра резидентов Особой экономической зоны в Калининградской области (далее в настоящем пункте - реестр);\n\nдаты окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату включения юридического лица в реестр, если дата окончания сроков действия налоговых ставок, тарифов страховых взносов, налоговых льгот, порядка исчисления налогов, порядка и сроков уплаты налогов, установленных на дату включения юридического лица в реестр, наступает ранее даты исключения резидента из реестра.\n\nПоложения настоящего пункта распространяются на акты законодательства о налогах и сборах в части страховых взносов, налога на прибыль организаций, налога на имущество организаций, земельного налога и применяются в отношении резидента в части правоотношений, связанных с реализацией инвестиционного проекта в соответствии с Федеральным законом от 10 января 2006 года № 16-ФЗ \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", при условии ведения им раздельного учета доходов (расходов), имущества, объектов налогообложения, полученных (произведенных, созданных, приобретенных) при реализации инвестиционного проекта в соответствии с Федеральным законом от 10 января 2006 года № 16-ФЗ \"Об Особой экономической зоне в Калининградской области и о внесении изменений в некоторые законодательные акты Российской Федерации\", и доходов (расходов), имущества, объектов налогообложения, полученных (произведенных, созданных, приобретенных) при осуществлении иной хозяйственной деятельности.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2025 № 373-ФЗ)\n\nНормативные правовые акты, предусматривающие утверждение новых форм (форматов) налоговых деклараций (расчетов) или внесение изменений в действующие формы (форматы) налоговых деклараций (расчетов), вступают в силу не ранее чем по истечении двух месяцев со дня их официального опубликования.\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)","article_title":"Статья 5. Действие актов законодательства о налогах и сборах во времени","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46e7516bf7b1a43a8f465a9e315b48a9207dbadaa9c84b18e59f2219f7757a6d"},{"code_id":"NK_RF","article_number":"50","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1. Обязанность по уплате налогов реорганизованного юридического лица исполняется его правопреемником (правопреемниками) в порядке, установленном настоящей статьей.\n\nНа правопреемника (правопреемников) реорганизованного юридического лица возлагается также обязанность по уплате причитающихся сумм штрафов, наложенных на юридическое лицо за совершение налоговых правонарушений до завершения его реорганизации. Правопреемник (правопреемники) реорганизованного юридического лица при исполнении возложенных на него настоящей статьей обязанностей по уплате налогов и сборов пользуется всеми правами, исполняет все обязанности в порядке, предусмотренном настоящим Кодексом для налогоплательщиков. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЕсли разделительный баланс не позволяет определить долю правопреемника реорганизованного юридического лица либо исключает возможность исполнения в полном объеме обязанностей по уплате налогов каким-либо правопреемником, и такая реорганизация была направлена на неисполнение обязанностей по уплате налогов, то по решению суда вновь возникшие юридические лица могут солидарно исполнять обязанность по уплате налогов реорганизованного лица. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n11. Правила, предусмотренные настоящей статьей, применяются также в следующих случаях:\n\n1) при исполнении обязанности по уплате сбора, страховых взносов при реорганизации юридического лица;\n\n2) при определении правопреемника (правопреемников) иностранной организации, реорганизованной в соответствии с законодательством иностранного государства;\n\n3) при уплате налогов в связи с перемещением товаров через таможенную границу Евразийского экономического союза;\n\n4) при исполнении обязанности налогового агента при реорганизации юридического лица; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) при определении принадлежности прав и обязанностей иностранной организации, зарегистрированной в едином государственном реестре юридических лиц со статусом международной компании в порядке, предусмотренном Федеральным законом от 3 августа 2018 года № 290-ФЗ \"О международных компаниях и международных фондах\". (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ)\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)","article_title":"Статья 50. Исполнение обязанности по уплате налогов, сборов, страховых взносов (пеней, штрафов) при реорганизации юридического лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8bf8aab1f5e77c5ff813c303dd370fff5a473ac303d698c06314c30ecd784fe3"},{"code_id":"NK_RF","article_number":"51","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Обязанность по уплате налогов и сборов физического лица, признанного судом безвестно отсутствующим, исполняются лицом, уполномоченным органом опеки и попечительства управлять имуществом безвестно отсутствующего.\n\nЛицо, уполномоченное органом опеки и попечительства управлять имуществом безвестно отсутствующего, обязано уплатить всю неуплаченную налогоплательщиком (плательщиком сбора) сумму налогов и сборов, а также причитающиеся на день признания лица безвестно отсутствующим пени и штрафы. Указанные суммы уплачиваются за счет денежных средств физического лица, признанного безвестно отсутствующим. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПри принятии в установленном порядке решения об отмене признания физического лица безвестно отсутствующим или недееспособным приостановленное исполнение обязанности по уплате налогов и сборов возобновляется со дня принятия указанного решения.","article_title":"Статья 51. Исполнение обязанности по уплате налогов, сборов, страховых взносов безвестно отсутствующего или недееспособного физического лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7543a48a7a0d2a0736fa2faaff51618625fb423fadeeabb3ca077b3ff10a96cf"},{"code_id":"NK_RF","article_number":"52","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 03.07.2016 № 243-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nПлательщик страховых взносов самостоятельно исчисляет сумму страховых взносов, подлежащую уплате за расчетный период, исходя из базы для исчисления страховых взносов и тарифа, если иное не предусмотрено настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 243-ФЗ)\n\nПодлежащая уплате сумма сбора исчисляется в соответствии с настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, если обязанность по исчислению суммы налога возлагается на налоговый орган, не позднее 30 дней до наступления срока платежа налоговый орган направляет налогоплательщику налоговое уведомление, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах. (В редакции  Федерального закона от 25.02.2022 № 18-ФЗ)\n\nНалог, подлежащий уплате физическими лицами в отношении объектов недвижимого имущества и (или) транспортных средств, исчисляется налоговыми органами не более чем за три налоговых периода, предшествующих календарному году направления налогового уведомления. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\nВ случае, указанном в абзаце втором настоящего пункта, при условии исполнения налогоплательщиком в установленный срок обязанности, предусмотренной пунктом 21 статьи 23 настоящего Кодекса, исчисление суммы налога производится начиная с того налогового периода, в котором была исполнена эта обязанность. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\nСумма денежных средств, подлежащая перечислению физическим лицом, не являющимся индивидуальным предпринимателем на дату формирования налогового уведомления, в качестве единого налогового платежа в счет исполнения обязанности по уплате налогов, указанных в пункте 3 статьи 13, пункте 3 статьи 14 и пунктах 1 и 2 статьи 15 настоящего Кодекса, определяется налоговым органом с учетом суммы положительного сальдо единого налогового счета налогоплательщика на дату формирования налогового уведомления. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\nПерерасчет, предусмотренный абзацем первым настоящего пункта, не осуществляется, если влечет увеличение ранее уплаченных сумм указанных налогов. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 334-ФЗ)\n\nВ налоговом уведомлении могут быть указаны данные по нескольким подлежащим уплате налогам.\n\nФорма налогового уведомления утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nНалогоплательщик (его законный или уполномоченный представитель) вправе получить налоговое уведомление на бумажном носителе под расписку в любом налоговом органе либо через многофункциональный центр предоставления государственных и муниципальных услуг на основании заявления о выдаче налогового уведомления. Налоговое уведомление передается налогоплательщику (его законному или уполномоченному представителю либо через многофункциональный центр предоставления государственных и муниципальных услуг) в срок не позднее пяти дней со дня получения налоговым органом заявления о выдаче налогового уведомления. (Дополнение абзацем - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nФорма заявления о выдаче налогового уведомления утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции ф\n\nедеральных законов от 29.06.2012 № 97-ФЗ, от 29.09.2019 № 325-ФЗ, от 23.11.2020 № 374-ФЗ)\n\nВ случае, если общая сумма налогов, исчисленных налоговым органом, составляет менее 300 рублей, налоговое уведомление не направляется налогоплательщику, за исключением случая направления налогового уведомления в календарном году, по истечении которого утрачивается возможность направления налоговым органом налогового уведомления в соответствии с абзацем третьим пункта 2 настоящей статьи. (Дополнение абзацем - Федеральный закон от 02.05.2015 № 113-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 52. Порядок исчисления налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8afc391a8229efd03ed5244f3ac8c04a39bc9822ea7b17685db3ea8f9d6105ca"},{"code_id":"NK_RF","article_number":"53","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 02.11.2004 № 127-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nНалоговые ставки по региональным налогам, подлежащим взиманию в федеральной территории \"Сириус\", устанавливаются настоящим Кодексом. Налоговые ставки по местным налогам, подлежащим взиманию в федеральной территории \"Сириус\", устанавливаются нормативными правовыми актами представительного органа федеральной территории \"Сириус\" в пределах, установленных настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)","article_title":"Статья 53. Налоговая база и налоговая ставка, размеры сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94f7fee9bc86051c1464b0cc18eee78554b1bb5893337e82bc83c82e80a44fec"},{"code_id":"NK_RF","article_number":"54","version_date":"2000-07-31","article_text":"1. Налогоплательщики-организации исчисляют налоговую базу по итогам каждого налогового периода на основе данных регистров бухгалтерского учета и (или) на основе иных документально подтвержденных данных об объектах, подлежащих налогообложению либо связанных с налогообложением.\n\nПри обнаружении ошибок (искажений) в исчислении налоговой базы, относящихся к прошлым налоговым (отчетным) периодам, в текущем налоговом (отчетном) периоде перерасчет налоговой базы и суммы налога производится за период, в котором были совершены указанные ошибки (искажения). (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nВ случае невозможности определения периода совершения ошибок (искажений) перерасчет налоговой базы и суммы налога производится за налоговый (отчетный) период, в котором выявлены ошибки (искажения). Налогоплательщик вправе провести перерасчет налоговой базы и суммы налога за налоговый (отчетный) период, в котором выявлены ошибки (искажения), относящиеся к прошлым налоговым (отчетным) периодам, также и в тех случаях, когда допущенные ошибки (искажения) привели к излишней уплате налога. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 26.11.2008 № 224-ФЗ)","article_title":"Статья 54. Общие вопросы исчисления налоговой базы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56204f278703092e3aebab198b02bb8f4ec024f683b07c1a065c974da3185d6e"},{"code_id":"NK_RF","article_number":"54.1","version_date":"2000-07-31","article_text":"1. Не допускается уменьшение налогоплательщиком налоговой базы и (или) суммы подлежащего уплате налога в результате искажения сведений о фактах хозяйственной жизни (совокупности таких фактов), об объектах налогообложения, подлежащих отражению в налоговом и (или) бухгалтерском учете либо налоговой отчетности налогоплательщика.\n\n2. При отсутствии обстоятельств, предусмотренных пунктом 1 настоящей статьи, по имевшим место сделкам (операциям) налогоплательщик вправе уменьшить налоговую базу и (или) сумму подлежащего уплате налога в соответствии с правилами соответствующей главы части второй настоящего Кодекса при соблюдении одновременно следующих условий:\n\n1) основной целью совершения сделки (операции) не являются неуплата (неполная уплата) и (или) зачет (возврат) суммы налога;\n\n2) обязательство по сделке (операции) исполнено лицом, являющимся стороной договора, заключенного с налогоплательщиком, и (или) лицом, которому обязательство по исполнению сделки (операции) передано по договору или закону.\n\n3. В целях пунктов 1 и 2 настоящей статьи подписание первичных учетных документов неустановленным или неуполномоченным лицом, нарушение контрагентом налогоплательщика законодательства о налогах и сборах, наличие возможности получения налогоплательщиком того же результата экономической деятельности при совершении иных не запрещенных законодательством сделок (операций) не могут рассматриваться в качестве самостоятельного основания для признания уменьшения налогоплательщиком налоговой базы и (или) суммы подлежащего уплате налога неправомерным.\n\n4. Положения, предусмотренные настоящей статьей, также применяются в отношении сборов и страховых взносов и распространяются на плательщиков сборов, плательщиков страховых взносов и налоговых агентов.\n\n(Дополнение статьей - Федеральный закон от 18.07.2017 № 163-ФЗ)","article_title":"Статья 54.1. Пределы осуществления прав по исчислению налоговой базы и (или) суммы налога, сбора, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c1a5256464b6e91eef51c10e754f6d5ca08b27920e19c228a553c81add7fb95"},{"code_id":"NK_RF","article_number":"55","version_date":"2000-07-31","article_text":"Если организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) в период времени с 1 января по 30 ноября одного календарного года, первым налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) по 31 декабря этого календарного года.\n\nЕсли организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) в период времени с 1 декабря по 31 декабря одного календарного года, первым налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) по 31 декабря календарного года, следующего за годом создания организации (осуществления государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\nПредусмотренные настоящим пунктом правила не применяются в отношении определения первого налогового периода по налогу на прибыль организаций для иностранных организаций, самостоятельно признавших себя налоговыми резидентами Российской Федерации в порядке, установленном настоящим Кодексом, деятельность которых на дату такого признания не приводила к образованию постоянного представительства в Российской Федерации.\n\n(Пункт в редакции Федерального закона от 18.07.2017 № 173-ФЗ)\n\nЕсли организация создана и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена и утратила силу) в течение календарного года, налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\nЕсли организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) в период времени с 1 декабря по 31 декабря одного календарного года и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя утратила силу) до конца календарного года, следующего за годом создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя), налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\n(Пункт в редакции Федерального закона от 18.07.2017 № 173-ФЗ)\n\nЕсли организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) не менее чем за 10 дней до конца квартала, первым налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до конца квартала, в котором создана организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя).\n\nЕсли организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) менее чем за 10 дней до конца квартала, первым налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до конца квартала, следующего за кварталом, в котором создана организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя).\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 173-ФЗ)\n\nЕсли организация создана и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена и утратила силу) в одном квартале, налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\nЕсли организация создана (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена) менее чем за 10 дней до конца квартала и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя утратила силу) до конца квартала, следующего за кварталом, в котором создана организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя), налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 173-ФЗ)\n\nПри создании организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) первым налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до конца календарного месяца, в котором создана организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя).\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 173-ФЗ)\n\nЕсли организация создана и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена и утратила силу) в одном календарном месяце, налоговым периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 173-ФЗ)\n\nПри создании организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) первым налоговым (расчетным) периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до конца календарного года, в котором создана организация (осуществлена государственная регистрация физического лица в качестве индивидуального предпринимателя).\n\nПри постановке на учет в налоговом органе адвоката, медиатора, нотариуса, занимающегося частной практикой, арбитражного управляющего, оценщика, патентного поверенного и иных лиц, занимающихся в установленном законодательством Российской Федерации порядке частной практикой, первым расчетным периодом для таких лиц является период времени со дня постановки на учет в налоговом органе до конца календарного года, в котором осуществлена постановка на учет в налоговом органе таких лиц.\n\nПри прекращении организации путем ликвидации или реорганизации (прекращении физическим лицом деятельности в качестве индивидуального предпринимателя) последним налоговым (расчетным) периодом для такой организации (такого индивидуального предпринимателя) является период времени с начала календарного года до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрац\n\nии физического лица в качестве индивидуального предпринимателя).\n\nПри снятии с учета в налоговом органе адвоката, медиатора, нотариуса, занимающегося частной практикой, арбитражного управляющего, оценщика, патентного поверенного и иных лиц, занимающихся в установленном законодательством Российской Федерации порядке частной практикой, последним расчетным периодом для таких лиц является период времени с начала календарного года до дня снятия с учета в налоговом органе таких лиц.\n\nЕсли организация создана и прекращена путем ликвидации или реорганизации (государственная регистрация физического лица в качестве индивидуального предпринимателя осуществлена и утратила силу) в течение календарного года, налоговым (расчетным) периодом для такой организации (такого индивидуального предпринимателя) является период времени со дня создания организации (государственной регистрации физического лица в качестве индивидуального предпринимателя) до дня государственной регистрации прекращения организации в результате ликвидации или реорганизации (утраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя).\n\nЕсли постановка на учет и снятие с учета в налоговом органе адвоката, медиатора, нотариуса, занимающегося частной практикой, арбитражного управляющего, оценщика, патентного поверенного и иных лиц, занимающихся в установленном законодательством Российской Федерации порядке частной практикой, осуществлены в течение календарного года, расчетным периодом для таких лиц является период времени со дня постановки на учет в налоговом органе до дня снятия с учета в налоговом органе таких лиц.\n\n(Дополнение пунктом - Федеральный закон от 18.07.2017 № 173-ФЗ)\n\nЕсли иностранная организация самостоятельно признала себя налоговым резидентом Российской Федерации с 1 января календарного года, в котором ею представлено заявление о признании себя налоговым резидентом Российской Федерации, первым налоговым периодом по налогу на прибыль организаций для нее является период времени с 1 января календарного года, в котором представлено указанное заявление, до конца этого календарного года.\n\nЕсли иностранная организация самостоятельно признала себя налоговым резидентом Российской Федерации с даты представления в налоговый орган заявления о признании себя налоговым резидентом Российской Федерации, первым налоговым периодом по налогу на прибыль организаций для нее является период времени с даты представления в налоговый орган указанного заявления до конца календарного года, в котором представлено указанное заявление.\n\nПри этом, если заявление иностранной организации, указанное в абзаце третьем настоящего пункта, о признании себя налоговым резидентом Российской Федерации представлено в день, приходящийся на период с 1 декабря по 31 декабря, первым налоговым периодом по налогу на прибыль организаций для нее является период времени с даты представления в налоговый орган указанного заявления до конца календарного года, следующего за годом, в котором представлено указанное заявление.\n\n(Дополнение пунктом - Федеральный закон от 15.02.2016 № 32-ФЗ)","article_title":"Статья 55. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aad3da232a580a1a321fa3659217be0ba94b1b128cded309cf881a9508a9ee86"},{"code_id":"NK_RF","article_number":"56","version_date":"2000-07-31","article_text":"1. Льготами по налогам и сборам признаются предоставляемые отдельным категориям налогоплательщиков и плательщиков сборов предусмотренные законодательством о налогах и сборах преимущества по сравнению с другими налогоплательщиками или плательщиками сборов, включая возможность не уплачивать налог или сбор либо уплачивать их в меньшем размере.\n\nНормы законодательства о налогах и сборах, определяющие основания, порядок и условия применения льгот по налогам и сборам, не могут носить индивидуального характера.\n\n(Пункт 2 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\nЛьготы по региональным налогам устанавливаются и отменяются настоящим Кодексом и (или) законами субъектов Российской Федерации о налогах, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nЛьготы по местным налогам устанавливаются и отменяются настоящим Кодексом и (или) нормативными правовыми актами представительных органов муниципальных образований о налогах (законами городов федерального значения Москвы, Санкт-Петербурга и Севастополя о налогах), если иное не предусмотрено настоящим пунктом. (В редакции федеральных законов от 29.11.2014 № 379-ФЗ, от 11.06.2021 № 199-ФЗ)\n\nЛьготы по региональным налогам, подлежащим взиманию в федеральной территории \"Сириус\", устанавливаются и отменяются настоящим Кодексом и (или) нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о региональных налогах. Льготы по местным налогам, подлежащим взиманию в федеральной территории \"Сириус\", устанавливаются и отменяются настоящим Кодексом и (или) нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах и сборах. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.07.2004 № 95-ФЗ)","article_title":"Статья 56. Установление и использование льгот по налогам и сборам","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47e34500e7ed6b467d69ed66a5c1e82b8e6842f4d5adfc25893caeade0df3ce3"},{"code_id":"NK_RF","article_number":"57","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nИзменение установленного срока уплаты налога, сбора, страховых взносов допускается только в соответствии с настоящим Кодексом. (В редакции федеральных законов от 03.07.2016 № 243-ФЗ, от 01.04.2020 № 102-ФЗ)","article_title":"Статья 57. Сроки уплаты налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c18ec457930567f8087a6b3d4acad3fa1a15728dd5a22fd424f3220cb5de4f60"},{"code_id":"NK_RF","article_number":"58","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1. Уплата (перечисление) налога, авансовых платежей по налогам в бюджетную систему Российской Федерации осуществляется в качестве единого налогового платежа, если иное не предусмотрено настоящим пунктом.\n\nУплата налога на профессиональный доход и сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, уплачиваемых самостоятельно плательщиками сборов в соответствии с главой 251 настоящего Кодекса, может осуществляться не в качестве единого налогового платежа.\n\nУплата государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ, осуществляется в качестве единого налогового платежа. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nУплата государственной пошлины, не указанной в абзаце третьем настоящего пункта, налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на сверхприбыль  осуществляется не в качестве единого налогового платежа. (В редакции  федеральных законов от 04.08.2023 № 415-ФЗ, от 12.07.2024 № 176-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nУплата страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности осуществляется не в качестве единого налогового платежа. Перечни указанных в настоящем пункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\". (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2. Подлежащая уплате сумма налога уплачивается (перечисляется) налогоплательщиком или налоговым агентом в установленные сроки.\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nНарушение порядка исчисления и (или) уплаты авансовых платежей не может рассматриваться в качестве основания для привлечения лица к ответственности за нарушение законодательства о налогах и сборах.\n\nФизические лица могут уплачивать налоги через кассу местной администрации, кассу исполнительно-распорядительного органа федеральной территории \"Сириус\" либо через организацию федеральной почтовой связи в случае отсутствия банка, а также через многофункциональный центр предоставления государственных и муниципальных услуг, в котором в соответствии с решением высшего исполнительного органа субъекта Российской Федерации организована возможность приема от указанных лиц денежных средств в счет уплаты налогов и их перечисления в бюджетную систему Российской Федерации. (В редакции  федеральных законов от 11.06.2021 № 199-ФЗ, от 19.12.2023 № 595-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.07.2018 № 232-ФЗ)\n\n1) принимать от физических лиц денежные средства в счет уплаты налогов в качестве единого налогового платежа, правильно и своевременно их перечислять с учетом положений, предусмотренных пунктом 42 настоящей статьи, в бюджетную систему Российской Федерации на счет Федерального казначейства по каждому налогоплательщику (налоговому агенту). При этом плата за прием денежных средств и их перечисление в бюджетную систему Российской Федерации не взимается; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2) вести учет денежных средств, принятых в счет уплаты налогов в качестве единого налогового платежа и перечисленных в бюджетную систему Российской Федерации, по каждому налогоплательщику (налоговому агенту); (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n3) выдавать при приеме денежных средств квитанции или иные документы, подтверждающие прием этих денежных средств. Форма квитанции, выдаваемой местной администрацией, исполнительно-распорядительным органом федеральной территории \"Сириус\", утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n4) представлять в налоговые органы (должностным лицам налоговых органов) по их запросам документы, подтверждающие прием от физических лиц денежных средств в счет уплаты налогов в качестве единого налогового платежа и их перечисление в бюджетную систему Российской Федерации. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 232-ФЗ)\n\nДенежные средства, принятые от физического лица в наличной форме организацией федеральной почтовой связи или многофункциональным центром предоставления государственных и муниципальных услуг, а также принятые от местной администрации, исполнительно-распорядительного органа федеральной территории \"Сириус\" в наличной форме организацией федеральной почтовой связи, в течение пяти дней со дня их приема подлежат внесению в банк для их последующего перечисления в бюджетную систему Российской Федерации на счет Федерального казначейства. (В редакции  федеральных законов от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае, если в связи со стихийным бедствием или иным обстоятельством непреодолимой силы денежные средства, принятые от физического лица, не могут быть внесены в установленный срок в банк или организацию федеральной почтовой связи для их перечисления в бюджетную систему Российской Федерации, указанный срок продлевается до устранения таких обстоятельств.\n\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 232-ФЗ)\n\nПрименение мер ответственности не освобождает местную администрацию, исполнительно-распорядительный орган федеральной территории \"Сириус\", организацию федеральной почтовой связи, многофункциональный центр предоставления государственных и муниципальных услуг от обязанности перечислить в бюджетную систему Российской Федерации денежные средства, принятые в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа. (В редакции  федеральных законов от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 232-ФЗ)\n\nТребование о перечислении денежных средств, принятых в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа в бюджетную систему Российской Федерации, должно быть направлено в местную администрацию, исполнительно-распорядительный орган федеральной территории \"Сириус\", организацию федеральной почтовой связи или многофункциональный центр предоставления государственных и муниципальных услуг не позднее трех месяцев со дня выявления не перечисленной в бюджетную систему Российской Федерации суммы денежных средств, принятых в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа, и составления налоговым органом документа о выявлении не перечисленной местной администрацией, исполнительно-распорядительным органом федеральной территории \"Сириус\", организацией федеральной почтовой связи или многофункциональным центром предоставления государственных и муниципальных услуг в бюджетную систему Российской Федерации суммы денежных средств, принятых в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nТребованием о перечислении денежных средств, принятых в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа, местной администрацией, исполнительно-распорядительным органом федеральной территории \"Сириус\", организацией федеральной почтовой связи или многофункциональным центром предоставления государственных и муниципальных услуг признается уведомление соответствующих органа, организации о неперечисленной сумме денежных средств, принятых в счет уплаты и перечисления сумм налогов в качестве единого налогового платежа, а также об обязанности перечислить эту сумму денежных средств в установленный срок. (В редакции  федеральных законов от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 232-ФЗ)\n\nПорядок уплаты федеральных налогов устанавливается настоящим Кодексом.\n\nПорядок уплаты региональных и местных налогов устанавливается соответственно законами субъектов Российской Федерации и нормативными правовыми актами представительных органов муниципальных образований в соответствии с настоящим Кодексом. Порядок уплаты региональных налогов в федеральной территории \"Сириус\" устанавливается настоящим Кодексом. Порядок уплаты местных налогов в федеральной территории \"Сириус\" устанавливается нормативными правовыми актами представительного органа федеральной территории \"Сириус\" в соот\n\nветствии с настоящим Кодексом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nВ случае перерасчета налоговым органом ранее исчисленного налога уплата налога осуществляется по налоговому уведомлению в срок, указанный в налоговом уведомлении. При этом налоговое уведомление должно быть направлено не позднее 30 дней до наступления срока, указанного в налоговом уведомлении. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\nЕсли иное не предусмотрено настоящим пунктом, уведомление об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов представляется в налоговый орган по месту учета не позднее 25-го числа месяца, в котором установлен срок уплаты соответствующих налогов, авансовых платежей по налогам, сборов, страховых взносов, в электронной форме по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи либо через личный кабинет налогоплательщика. Налогоплательщиками, не указанными в пункте 3 статьи 80 настоящего Кодекса, уведомление об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов может быть представлено на бумажном носителе. Индивидуальными предпринимателями уведомление об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов может быть представлено в электронной форме по установленному формату через личный кабинет налогоплательщика в виде документа, подписанного усиленной неквалифицированной электронной подписью, сформированной в порядке, установленном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в соответствии с требованиями Федерального закона от 6 апреля 2011 года № 63-ФЗ \"Об электронной подписи\". (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 27.11.2023 № 539-ФЗ)\n\nОрганизации и индивидуальные предприниматели, исполняющие обязанности налогового агента по налогу на доходы физических лиц, в уведомлении об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов, представляемом в срок, установленный абзацем вторым настоящего пункта, указывают в отношении сумм налога на доходы физических лиц информацию об исчисленных и удержанных ими суммах указанного налога за период с 1-го по 22-е число текущего месяца. В отношении сумм налогов на доходы физических лиц, исчисленных и удержанных налоговыми агентами за период с 23-го числа по последнее число текущего месяца, указанные организации и индивидуальные предприниматели представляют уведомление об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов не позднее 3-го числа следующего месяца, в отношении сумм налогов на доходы физических лиц, исчисленных и удержанных налоговыми агентами за период с 23 декабря по 31 декабря, - не позднее последнего рабочего дня календарного года. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nФорма и форматы уведомления об исчисленных суммах налогов, авансовых платежей по налогам, сборов, страховых взносов утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если сумма авансового платежа, включенная в совокупную обязанность налогоплательщика по налогу за отчетный период, рассчитанная нарастающим итогом с начала налогового периода, меньше суммы авансового платежа по налогу, рассчитанной за предыдущий отчетный период этого же налогового периода, налогоплательщик вправе представить уведомление об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов с указанием суммы авансового платежа с отрицательным значением в размере разницы для уменьшения совокупной обязанности. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае обнаружения налоговым органом факта несоответствия показателей представленных уведомлений об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов контрольным соотношениям, свидетельствующего о нарушении порядка их заполнения, такие уведомления будут считаться не представленными полностью либо в части, о чем сообщается налогоплательщику (налоговому агенту, плательщику страховых взносов) не позднее дня, следующего за днем получения соответствующего уведомления, в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота или через личный кабинет налогоплательщика. В случае, если уведомление об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов было представлено в налоговый орган на бумажном носителе и при этом отсутствует или прекращен доступ налогоплательщика (налогового агента, плательщика страховых взносов) к личному кабинету налогоплательщика, такому налогоплательщику (налоговому агенту, плательщику страховых взносов) сообщается о факте несоответствия указанным контрольным соотношениям по почте заказным письмом не позднее 10 дней, следующих за днем получения уведомления. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nУведомление считается не представленным в части в случае обнаружения налоговым органом факта несоответствия соответствующих показателей представленных уведомлений об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов контрольным соотношениям, свидетельствующего о нарушении порядка их заполнения в части обязанности по отдельному налогу (сбору, авансовому платежу по налогу, страховым взносам). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПеречень контрольных соотношений, указанных в настоящем пункте, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 232-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 58. Порядок уплаты налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3cc6ab41471a61900847d513717df6403ce5e80a712e15a93dd71f3a3bd9efc0"},{"code_id":"NK_RF","article_number":"59","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 14.07.2022 № 263-ФЗ)\n\n1) ликвидации организации в соответствии с законодательством Российской Федерации или законодательством иностранного государства, исключения юридического лица из Единого государственного реестра юридических лиц по решению регистрирующего органа в случае вынесения судебным приставом-исполнителем постановления об окончании исполнительного производства в связи с возвратом взыскателю исполнительного документа по основаниям, предусмотренным пунктом 3 или 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", - в части задолженности, не погашенной по причине недостаточности имущества организации и (или) невозможности ее погашения учредителями (участниками) указанной организации в пределах и порядке, которые установлены законодательством Российской Федерации; (В редакции  федеральных законов от 03.07.2016 № 240-ФЗ, от 30.11.2016 № 401-ФЗ, от 29.07.2018 № 232-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n2) завершения процедуры банкротства гражданина, индивидуального предпринимателя в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\" - в части задолженности, от исполнения обязанности по уплате которой он освобожден в соответствии с указанным Федеральным законом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n21) (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 240-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n3) смерти физического лица или объявления его умершим в порядке, установленном гражданским процессуальным законодательством Российской Федерации, - в части задолженности по всем налогам, сборам, страховым взносам, а в части налогов, указанных в пункте 3 статьи 14 и статье 15 настоящего Кодекса, - в размере, превышающем стоимость его наследственного имущества, в том числе в случае перехода наследства в собственность Российской Федерации;  (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n4) принятия судом акта, в соответствии с которым налоговый орган утрачивает возможность взыскания задолженности в связи с истечением установленного срока ее взыскания, в том числе вынесения им определения об отказе в восстановлении пропущенного срока подачи заявления в суд о взыскании задолженности; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n41) вынесения судебным приставом-исполнителем постановления об окончании исполнительного производства при возврате взыскателю исполнительного документа по основаниям, предусмотренным пунктами 3 и 4 части 1 статьи 46 Федерального закона от 2 октября 2007 года № 229-ФЗ \"Об исполнительном производстве\", если с даты образования задолженности, размер которой не превышает размера требований к должнику, установленного законодательством Российской Федерации о несостоятельности (банкротстве) для возбуждения производства по делу о банкротстве, прошло более пяти лет; (Дополнение подпунктом - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции  федеральных законов от 25.12.2018 № 493-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n42) снятия с учета в налоговом органе иностранного лица в соответствии с пунктом 55 статьи 84 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\n43) принятия судом акта о возвращении заявления о признании должника банкротом или прекращении производства по делу о банкротстве в связи с отсутствием средств, достаточных для возмещения судебных расходов на проведение процедур, применяемых в деле о банкротстве; (Дополнение подпунктом - Федеральный закон от 25.12.2018 № 493-ФЗ)\n\n5) в иных случаях, предусмотренных законодательством Российской Федерации о налогах и сборах.\n\n1) налоговые органы (за исключением случая, предусмотренного подпунктом 3 настоящего пункта); (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n3) таможенные органы, определяемые федеральным органом исполнительной власти, уполномоченным в области таможенного дела, - по налогам, пеням, штрафам, подлежащим уплате в связи с перемещением товаров через таможенную границу Таможенного союза. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nНормативными правовыми актами представительного органа федеральной территории \"Сириус\" могут быть установлены дополнительные основания признания безнадежной к взысканию задолженности в части сумм местных налогов. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 59. Признание задолженности безнадежной к взысканию и ее списание","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84ded58ed7436c89f962c20b7b1ab210d095b0ae0b79b34716e3880788eb75ce"},{"code_id":"NK_RF","article_number":"6","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\n1) издан органом, не имеющим в соответствии с настоящим Кодексом права издавать подобного рода акты, либо издан с нарушением установленного порядка издания таких актов;\n\n2) отменяет или ограничивает права налогоплательщиков, плательщиков сборов, плательщиков страховых взносов, налоговых агентов, их представителей либо полномочия налоговых органов, таможенных органов, установленные настоящим Кодексом; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 24.07.2009 № 213-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n3) вводит обязанности, не предусмотренные настоящим Кодексом, или изменяет определенное настоящим Кодексом содержание обязанностей участников отношений, регулируемых законодательством о налогах и сборах, иных лиц, обязанности которых установлены настоящим Кодексом; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n4) запрещает действия налогоплательщиков, плательщиков сборов, плательщиков страховых взносов, налоговых агентов, их представителей, разрешенные настоящим Кодексом; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n5) запрещает действия налоговых органов, таможенных органов, их должностных лиц, разрешенные или предписанные настоящим Кодексом; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 24.07.2009 № 213-ФЗ)\n\n6) разрешает или допускает действия, запрещенные настоящим Кодексом;\n\n7) изменяет установленные в соответствии с настоящим Кодексом основания, условия, последовательность или порядок действий участников отношений, регулируемых законодательством о налогах и сборах, иных лиц, обязанности которых установлены настоящим Кодексом;  (В редакции федеральных законов от 09.07.1999 № 154-ФЗ, от 01.04.2020 № 102-ФЗ)\n\n8) изменяет содержание понятий и терминов, определенных в настоящем Кодексе, либо использует эти понятия и термины в ином значении, чем они используются в настоящем Кодексе;\n\n9) иным образом противоречит общим началам и (или) буквальному смыслу конкретных положений настоящего Кодекса.","article_title":"Статья 6. Несоответствие нормативных правовых актов настоящему Кодексу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"225366dc6b2800e9b74474c575ac24f1ed9198fda33ca30b8af6d3fd484a5300"},{"code_id":"NK_RF","article_number":"60","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПри предъявлении поручения налогоплательщика - физического лица в обособленное подразделение банка, не имеющее корреспондентского счета (субсчета), срок, установленный абзацем первым настоящего пункта для исполнения банком поручения налогоплательщика, продлевается в установленном порядке на время доставки такого поручения организацией федеральной почтовой связи в обособленное подразделение банка, имеющее корреспондентский счет (субсчет), но не более чем на пять операционных дней.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nФорма и форматы сообщения банка о неисполнении (частичном исполнении) поручения налогоплательщика или поручения налогового органа и порядок его передачи в электронной форме устанавливаются Центральным банком Российской Федерации по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 02.11.2013 № 306-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\nПрименение мер ответственности не освобождает банк от обязанности перечислить в бюджетную систему Российской Федерации неперечисленную им сумму денежных средств. В случае неисполнения банком указанной обязанности в установленный срок к этому банку применяются меры по взысканию неперечисленных сумм за счет денежных средств в порядке, аналогичном порядку, предусмотренному статьей 46 настоящего Кодекса, а за счет иного имущества - в порядке, аналогичном порядку, предусмотренному статьей 47 настоящего Кодекса. (До\n\nполнение абзацем - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции  федеральных законов от 04.11.2005 № 137-ФЗ, от 27.07.2006 № 137-ФЗ, от 27.11.2017 № 343-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nТребованием о перечислении задолженности признается уведомление банка о неперечисленной сумме денежных средств, а также об обязанности перечислить эту сумму в установленный срок.\n\nФорматы требования о перечислении задолженности и порядок направления этого требования в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nПравила, установленные настоящей статьей, применяются также в отношении обязанности банков по исполнению поручений на перечисление единого налогового платежа за третьих лиц.\n\nПравила, установленные настоящей статьей, применяются также в отношении обязанности банков по исполнению поручений налогоплательщиков, плательщиков сборов и распространяются на перечисление в бюджетную систему Российской Федерации налогов и сборов, уплачиваемых не в качестве единого налогового платежа. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 415-ФЗ)\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Наименование в редакции Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 60. Обязанности банков по исполнению поручений на перечисление налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94843a68c93ddb7eeed7a011e87f0bbddfce50061c06faee752dfb3cddec6107"},{"code_id":"NK_RF","article_number":"6.1","version_date":"2000-07-31","article_text":"1. Сроки, установленные законодательством о налогах и сборах, определяются календарной датой, указанием на событие, которое должно неизбежно наступить, или на действие, которое должно быть совершено, либо периодом времени, который исчисляется годами, кварталами, месяцами или днями.\n\n2. Течение срока начинается на следующий день после календарной даты или наступления события (совершения действия), которым определено его начало.\n\n3. Срок, исчисляемый годами, истекает в соответствующие месяц и число последнего года срока.\n\nПри этом годом (за исключением календарного года) признается любой период времени, состоящий из 12 месяцев, следующих подряд.\n\n4. Срок, исчисляемый кварталами, истекает в последний день последнего месяца срока.\n\nПри этом квартал считается равным трем календарным месяцам, отсчет кварталов ведется с начала календарного года.\n\n5. Срок, исчисляемый месяцами, истекает в соответствующие месяц и число последнего месяца срока.\n\nЕсли окончание срока приходится на месяц, в котором нет соответствующего числа, то срок истекает в последний день этого месяца.\n\nЕсли документы либо денежные средства были сданы в организацию связи до 24 часов последнего дня срока, то срок не считается пропущенным.\n\n(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 6.1. Порядок исчисления сроков, установленных законодательством о налогах и сборах","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad80259521a88789c8dae760a095fbae42156bbaac9508adb7746ec0d5e6713e"},{"code_id":"NK_RF","article_number":"61","version_date":"2000-07-31","article_text":"1. Отсрочкой, рассрочкой по уплате задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил (далее в настоящей главе соответственно - отсрочка, рассрочка), инвестиционным налоговым кредитом признается перенос обязанности по их уплате на более поздний срок.\n\n2. Предоставление отсрочки, рассрочки, инвестиционного налогового кредита лицу, претендующему на предоставление такой отсрочки или рассрочки, инвестиционного налогового кредита (далее в настоящей главе - заинтересованное лицо), осуществляется в порядке, установленном настоящей главой, если иное не предусмотрено настоящим Кодексом.\n\nПредоставление отсрочки или рассрочки по уплате государственной пошлины осуществляется с учетом особенностей, предусмотренных главой 253 настоящего Кодекса.\n\n3. Отсрочка или рассрочка может быть предоставлена:\n\n1) по уплате налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения в соответствии с пунктом 9 статьи 64 настоящего Кодекса, - в отношении всей или части подлежащей уплате суммы налога, сбора, страхового взноса;\n\n2) по уплате задолженности - в отношении всей или части суммы отрицательного сальдо единого налогового счета заинтересованного лица при наличии отрицательного сальдо на день принятия уполномоченным органом решения в соответствии с пунктом 9 статьи 64 настоящего Кодекса.\n\n4. Отсрочка или рассрочка предоставляется с начислением процентов на сумму отсрочки или рассрочки, если иное не предусмотрено настоящей главой.\n\nВ случае, если сумма задолженности, указанная в заявлении, меньше суммы отрицательного сальдо единого налогового счета на дату принятия решения о предоставлении отсрочки или рассрочки, отсрочка или рассрочка предоставляется в отношении соответствующих сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, составляющих сумму такой задолженности, в последовательности, установленной пунктом 8 статьи 45 настоящего Кодекса.\n\nОтсрочка или рассрочка может быть предоставлена на сумму, не превышающую сумму, указанную в заявлении заинтересованного лица о предоставлении отсрочки или рассрочки.\n\nПовторное предоставление отсрочки или рассрочки по уплате задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил и по которым ранее уполномоченным органом было принято решение о предоставлении отсрочки или рассрочки, не допускается.\n\nПо основанию, указанному в подпункте 7 пункта 2 статьи 64 настоящего Кодекса, может быть предоставлена только рассрочка.\n\nПри рассмотрении указанных в абзаце первом настоящего пункта заявлений орган, уполномоченный принимать решения о предоставлении отсрочки или рассрочки, инвестиционного налогового кредита, вправе предложить указанному лицу предусмотренные настоящей главой иные условия предоставления отсрочки или рассрочки, инвестиционного налогового кредита, которые уточняются по согласованию с заинтересованным лицом.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 61. Общие условия предоставления отсрочки, рассрочки, инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b9b07edbed5756a492f618ec76afbc751befe9d91d3f9b01242fcbee91bf4a9c"},{"code_id":"NK_RF","article_number":"62","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящим Кодексом, отсрочка или рассрочка, инвестиционный налоговый кредит не могут быть предоставлены в соответствии с настоящей главой, если:\n\n1) в отношении заинтересованного лица возбуждено уголовное дело по признакам преступления, связанного с нарушением законодательства о налогах и сборах, либо в отношении законного представителя (бывшего законного представителя) организации - заинтересованного лица возбуждено уголовное дело по признакам преступления, связанного с нарушением этой организацией законодательства о налогах и сборах;\n\n2) наличие обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов, процентов обжалуется заинтересованным лицом в соответствии с главой 19 настоящего Кодекса в части сумм, указанных в заявлении о предоставлении отсрочки или рассрочки, либо проводится производство по делу о налоговом правонарушении либо по делу об административном правонарушении в области налогов, сборов, страховых взносов, таможенного дела в части налогов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза;\n\n3) заинтересованное лицо собирается выехать за пределы Российской Федерации на постоянное место жительства;\n\n4) в течение трех лет, предшествующих дню подачи заинтересованным лицом заявления о предоставлении в соответствии с настоящей главой отсрочки или рассрочки, инвестиционного налогового кредита, органом, указанным в статье 63 настоящего Кодекса, было вынесено решение о досрочном прекращении действия ранее предоставленной отсрочки или рассрочки, инвестиционного налогового кредита в связи с нарушением условий соответствующего решения либо установлен факт неуплаты соответствующей суммы по истечении срока действия отсрочки или рассрочки, инвестиционного налогового кредита;\n\n5) заинтересованное лицо - организация находится в процессе ликвидации;\n\n6) в отношении заинтересованного лица возбуждено производство по делу о несостоятельности (банкротстве) в соответствии с законодательством Российской Федерации о несостоятельности (банкротстве).\n\n2. При наличии обстоятельств, указанных в пункте 1 настоящей статьи, решение о предоставлении отсрочки или рассрочки, инвестиционного налогового кредита не может быть вынесено, а вынесенное решение подлежит отмене.\n\nОб отмене вынесенного решения в трехдневный срок письменно уведомляется заинтересованное лицо.\n\nЗаинтересованное лицо вправе обжаловать такое решение в порядке, установленном настоящим Кодексом.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 62. Обстоятельства, исключающие предоставление отсрочки или рассрочки по уплате налога и (или) сбора, инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75e13bb4756c8296a4a8f2187bffe02bfb062d56f3c755792e1f37c3d3f8b9a1"},{"code_id":"NK_RF","article_number":"63","version_date":"2000-07-31","article_text":"1. Органами, в компетенцию которых входит принятие решения о предоставлении отсрочки или рассрочки, инвестиционного налогового кредита (далее - уполномоченные органы), являются:\n\n1) налоговый орган, уполномоченный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, если иное не предусмотрено настоящим пунктом;\n\n2) по налогам, подлежащим уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза, - федеральный орган исполнительной власти, осуществляющий функции по контролю и надзору в области таможенного дела, или уполномоченные им таможенные органы;\n\n3) по государственной пошлине (за исключением государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ) - органы (должностные лица), уполномоченные в соответствии с главой 253 настоящего Кодекса совершать юридически значимые действия, за которые подлежит уплате государственная пошлина; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n4) по налогу на прибыль организаций по налоговой ставке, установленной для зачисления указанного налога в бюджеты субъектов Российской Федерации, и региональным налогам в части решений о переносе срока исполнения обязанности по уплате указанных налогов в форме инвестиционного налогового кредита - органы, уполномоченные на это законодательством субъектов Российской Федерации.\n\n2. Отсрочка или рассрочка, инвестиционный налоговый кредит в части сумм налогов и сборов (за исключением государственной пошлины), подлежащих зачислению в бюджеты субъектов Российской Федерации, местные бюджеты, бюджет федеральной территории \"Сириус\", предоставляются на основании решений уполномоченных органов, указанных в пункте 1 настоящей статьи, согласованных с соответствующими финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в течение 10 дней со дня принятия решения об отсрочке или рассрочке.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 63. Органы, уполномоченные принимать решения о предоставлении отсрочки или рассрочки, инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9baf629d968b55c0e33caeda39ba11e98e212f2957c44e1e8991ac554287317a"},{"code_id":"NK_RF","article_number":"64","version_date":"2000-07-31","article_text":"1. Отсрочка или рассрочка предоставляется при наличии оснований, предусмотренных настоящей статьей, на срок, для отсрочек не превышающий одного года либо для рассрочек не превышающий трех лет, соответственно с единовременной или поэтапной уплатой суммы задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения в соответствии с пунктом 9 настоящей статьи, на которую предоставляется отсрочка или рассрочка (далее в настоящей статье - сумма отсрочки или рассрочки), если иное не предусмотрено настоящим Кодексом.\n\nВ случае вступления в силу решения о предоставлении отсрочки или рассрочки в соответствии с пунктом 10 настоящей статьи срок, на который предоставляется отсрочка или рассрочка, исчисляется: (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nс даты принятия уполномоченным органом решения о предоставлении отсрочки или рассрочки - в отношении задолженности;\n\nс установленного срока уплаты соответствующего налога, сбора, страхового взноса - в отношении налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения в соответствии с пунктом 9 настоящей статьи.\n\n2. Отсрочка или рассрочка может быть предоставлена заинтересованному лицу, финансовое положение которого не позволяет уплатить налоги, сборы, страховые взносы, пени, штрафы, проценты в установленный срок, однако имеются достаточные основания полагать, что возможность их уплаты этим лицом возникнет в течение срока, на который предоставляется отсрочка или рассрочка, при наличии хотя бы одного из следующих оснований:\n\n1) причинение этому лицу ущерба в результате стихийного бедствия, технологической катастрофы;\n\n2) непредоставление (несвоевременное предоставление) бюджетных ассигнований и (или) лимитов бюджетных обязательств заинтересованному лицу и (или) недоведение (несвоевременное доведение) предельных объемов финансирования расходов до заинтересованного лица - получателя бюджетных средств в объеме, достаточном для своевременной уплаты налогов, сборов, страховых взносов, а также неперечисление (несвоевременное перечисление) заинтересованному лицу из бюджета денежных средств в объеме, достаточном для своевременной уплаты этим лицом налогов, сборов, страховых взносов, в том числе в счет оплаты оказанных этим лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд;\n\n3) угроза возникновения признаков несостоятельности (банкротства) заинтересованного лица в случае единовременной уплаты им налога, сбора, страхового взноса, пеней, штрафов, процентов;\n\n4) имущественное положение физического лица (без учета имущества, на которое в соответствии с законодательством Российской Федерации не может быть обращено взыскание) исключает возможность единовременной уплаты налога, сбора, страхового взноса, пеней, штрафов, процентов;\n\n5) производство и (или) реализация товаров, работ или услуг заинтересованным лицом носит сезонный характер;\n\n6) наличие оснований для предоставления отсрочки или рассрочки по уплате налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза, установленных правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании;\n\n7) невозможность единовременной уплаты сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, подлежащих уплате в бюджетную систему Российской Федерации по результатам налоговой проверки, определяемая в порядке, предусмотренном пунктом 5 настоящей статьи.\n\n3. Если отсрочка или рассрочка предоставлена по основаниям, указанным в подпунктах 3, 4 и 5 пункта 2 настоящей статьи, на сумму отсрочки или рассрочки начисляются проценты исходя из ставки, равной одной второй ключевой ставки Центрального банка Российской Федерации, действовавшей за период отсрочки или рассрочки по уплате налога и (или) сбора, если иное не предусмотрено правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании в отношении налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза.\n\nЕсли отсрочка или рассрочка предоставлена по основаниям, указанным в подпунктах 1 и 2 пункта 2 настоящей статьи, на сумму отсрочки или рассрочки проценты не начисляются.\n\nВ случае, если рассрочка предоставлена по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, на сумму рассрочки начисляются проценты исходя из ставки, равной ключевой ставке Центрального банка Российской Федерации, действовавшей в период действия рассрочки, если иное не предусмотрено правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании в отношении налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза.\n\nПодлежащие уплате проценты, предусмотренные настоящим пунктом, рассчитываются за каждый календарный день действия отсрочки или рассрочки начиная со дня вступления в силу решения о предоставлении отсрочки или рассрочки в процентах годовых. Проценты, предусмотренные настоящим пунктом, подлежат уплате не позднее дня, следующего за днем уплаты последнего платежа, предусмотренного решением о предоставлении отсрочки или рассрочки. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n4. Заявление о предоставлении отсрочки или рассрочки представляется заинтересованным лицом в соответствующий уполномоченный орган. К заявлению о предоставлении отсрочки или рассрочки прилагаются следующие документы:\n\n1) справки банков о ежемесячных оборотах денежных средств (электронных денежных средств, драгоценных металлов), справки оператора платформы цифрового рубля о ежемесячных оборотах цифровых рублей за каждый месяц из предшествующих месяцу подачи указанного заявления трех месяцев по всем счетам этого лица в банках, счету цифрового рубля (при наличии счета цифрового рубля), в том числе з\n\nакрытым в указанный период, при обращении с заявлением о предоставлении отсрочки или рассрочки по основаниям, указанным в подпункте 4 или 7 пункта 2 настоящей статьи, справки банков о наличии его расчетных документов, помещенных в соответствующую картотеку неоплаченных расчетных документов, с раскрытием содержащейся в них информации либо об их отсутствии в этой картотеке на всех счетах этого лица в банках; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n2) справки банков об остатках денежных средств (электронных денежных средств, драгоценных металлов) на всех счетах этого лица в банках, справки оператора платформы цифрового рубля об остатках цифровых рублей на счете цифрового рубля (при наличии счета цифрового рубля) при обращении с заявлением о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 4 пункта 2 настоящей статьи; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n3) перечень контрагентов - дебиторов этого лица с указанием цен договоров, заключенных с соответствующими контрагентами - дебиторами, и сроков их исполнения. Заинтересованное лицо вправе предоставить аналогичную информацию об иных обязательствах и основаниях их возникновения;\n\n4) документы, подтверждающие наличие оснований предоставления отсрочки или рассрочки, указанные в пункте 5 настоящей статьи.\n\n5. К заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 1 пункта 2 настоящей статьи, прилагается акт оценки причиненного заинтересованному лицу ущерба в результате стихийного бедствия или технологической катастрофы, составленный органом исполнительной власти, органом местного самоуправления или органом публичной власти федеральной территории \"Сириус\", уполномоченным в области гражданской обороны, защиты населения и территорий от чрезвычайных ситуаций.\n\nК заявлению о предоставлении отсрочки или рассрочки заинтересованному лицу - получателю бюджетных средств по основанию, указанному в подпункте 2 пункта 2 настоящей статьи, также прилагается документ финансового органа и (или) главного распорядителя (распорядителя) бюджетных средств, содержащий сведения о сумме бюджетных ассигнований и (или) лимитов бюджетных обязательств, которые не предоставлены (несвоевременно предоставлены) указанному лицу, и (или) о сумме предельных объемов финансирования расходов, которые не доведены (несвоевременно доведены) до этого лица в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов.\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 2 пункта 2 настоящей статьи, заинтересованному лицу - получателю бюджетных средств, которому не перечислены (несвоевременно перечислены) денежные средства из бюджета в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов, в том числе в счет оказанных этим лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд, нужд федеральной территории \"Сириус\", также прилагается документ получателя бюджетных средств либо документ государственного, муниципального заказчика, уполномоченного органа публичной власти федеральной территории \"Сириус\" в сфере закупок для обеспечения нужд федеральной территории \"Сириус\", содержащие сведения о сумме денежных средств, которая не перечислена (несвоевременно перечислена) этому лицу из бюджета в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов, в том числе в счет оплаты оказанных таким лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд, нужд федеральной территории \"Сириус\".\n\nНаличие основания, указанного в подпункте 3 пункта 2 настоящей статьи, устанавливается на дату подачи заявления о предоставлении отсрочки или рассрочки по результатам анализа финансового состояния хозяйствующего субъекта, проведенного органом, уполномоченным в соответствии со статьей 63 настоящего Кодекса принимать решения об отсрочке или рассрочке, в соответствии с методикой, утверждаемой федеральным органом исполнительной власти, уполномоченным осуществлять функции по выработке государственной политики и нормативно-правовому регулированию в сфере несостоятельности (банкротства) и финансового оздоровления.\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 4 пункта 2 настоящей статьи, также прилагаются сведения о движимом и недвижимом имуществе физического лица (за исключением имущества, на которое в соответствии с законодательством Российской Федерации не может быть обращено взыскание).\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 5 пункта 2 настоящей статьи, также прилагается составленный заинтересованным лицом документ, подтверждающий, что в общем доходе от реализации товаров (работ, услуг) такого лица доля его дохода от отраслей и видов деятельности, включенных в утверждаемый Правительством Российской Федерации перечень отраслей и видов деятельности, имеющих сезонный характер, составляет не менее 50 процентов.\n\nНаличие указанного в подпункте 7 пункта 2 настоящей статьи основания для предоставления рассрочки устанавливается уполномоченным органом в случае, если сумма поступлений денежных средств на счета заинтересованного лица в банках за трехмесячный период, предшествующий подаче заявления о предоставлении рассрочки, меньше суммы краткосрочных обязательств заинтересованного лица (с учетом подлежащих уплате в бюджетную систему Российской Федерации по результатам налоговой проверки сумм налога, сбора, страхового взноса, пеней, штрафов, процентов), уменьшенной на величину доходов будущих периодов, по сведениям представленной в установленном порядке в налоговый орган бухгалтерской (финансовой) отчетности на последнюю отчетную дату, при соблюдении предусмотренных настоящим пунктом условий.\n\nРассрочка по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, может быть предоставлена заинтересованному лицу в случае подачи им соответствующего заявления о предоставлении рассрочки не позднее 10 дней после вступления в силу решения по результатам налоговой проверки, а также в случае, если это заинтересованное лицо одновременно удовлетворяет следующим условиям:\n\nсо дня создания организации, регистрации физического лица в качестве индивидуального предпринимателя до дня представления в уполномоченный орган заявления о предоставлении рассрочки прошло не менее одного года;\n\nорганизация не находится в процессе реорганизации или ликвидации.\n\n6. При обращении заинтересованного лица с заявлением о предоставлении отсрочки или рассрочки представляются договор залога имущества или договор поручительства либо банковская гарантия, если иное не предусмотрено настоящим Кодексом.\n\nПри обращении заинтересованного лица с заявлением о предоставлении рассрочки по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, в качестве способа обеспечения исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов указанным лицом представляется банковская гарантия. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nУказанная в настоящем пункте банковская гарантия может быть представлена за налогоплательщика гарантом. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nТребования к банковской гарантии и порядок ее представления гарантом устанавливаются в соответствии со статьей 741 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПо ходатайству заинтересованного лица уполномоченный орган вправе принять решение о временном (на период рассмотрения заявления о предоставлении отсрочки или рассрочки и до вступления решения о предоставлении отсрочки или рассрочки в силу (наступления обстоятельств, указанных в абзаце седьмом пункта 10 настоящей статьи) или до отказа в предоставлении отсрочки или рассрочки) приостановлении уплаты суммы задолженности, указанной в этом заявлении заинтересованного лица. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nВ случае необходимости запроса, в том числе у иных лиц, дополнительной информации в ходе рассмотрения заявления заинтересованного лица о предоставлении отсрочки или рассрочки уполномоченный орган вправе приостановить срок принятия решения о предоставлении отсрочки или рассрочки, но не более чем на 20 календарных дней, о чем выносится соответствующее решение, о принятии которого уведомляется заинтересованное лицо в трехдневный срок с даты его принятия.\n\nНе подлежит рассмотрению заявление заинтересованного лица о предоставлении отсрочки или рассрочки, представленное в уполномоченный орган:\n\nбез указания основания для предоставления отсрочки или рассрочки, предусмотренного пунктом 2 настоящей статьи, суммы задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения об отсрочке или рассрочке, и срока, на который запрашивается отсрочка или рассрочка;\n\nбез приложения документов, указанных в пункте 4 настоящей статьи;\n\nналоговым агентом без учета положений пункта 9 статьи 61 настоящего Кодекса.\n\nДнем вступления в силу решения о предоставлении отсрочки или рассрочки является:\n\nдень его принятия в случае заключения договора залога имущества, договора поручительства либо предоставления банковской гарантии до дня принятия решения о предоставлении отсрочки или рассрочки;\n\nдень заключения договора залога имущества, договора поручительства или предоставления банковской гарантии в случае заключения указанных договоров либо предоставления банковской гарантии в срок не позднее 30 дней со дня принятия решения об отсрочке или рассрочке;\n\nдень получения уполномоченным органом информации о согласовании решения об отсрочке или рассрочке финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса. При отсутствии в уполномоченном органе информации об отказе в согласовании соответствующего решения в течение 10 дней со дня его принятия решение о предоставлении отсрочки или рассрочки считается согласованным в день, следующий за днем истечения установленного для согласования срока.\n\nРешение о предоставлении отсрочки или рассрочки в случае необходимости его согласования (полностью или частично) с финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса не может вступить в силу ранее дня получения уполномоченным органом соответствующего согласования в установленной части. Срок согласования (отказа в согласовании) не должен превышать 10 дней со дня получения финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" решений уполномоченных органов в установленной части. При отсутствии в уполномоченном органе информации о согласовании (отказе в согласовании) соответствующего решения указанными органами власти принятое решение о предоставлении отсрочки или рассрочки считается согласованным в день, следующий за днем истечения установленного для согласования срока.\n\nПри отсутствии в течение 30 календарных дней, следующих за днем принятия решения о предоставлении отсрочки или рассрочки, заключенных договора залога имущества в соответствии со статьей 73 настоящего Кодекса, договора поручительства в соответствии со статьей 74 настоящего Кодекса, предоставленной банковской гарантии в соответствии со статьей 741 настоящего Кодекса либо отказе в согласовании (полностью или частично) финансовыми органами субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса соответствующее решение о предоставлении отсрочки или рассрочки не вступает в силу. Информация о невступлении решения о предоставлении отсрочки или рассрочки в силу доводится до заинтересованного лица в трехдневный срок с даты истечения соответствующего срока либо получения отказа в согласовании финансовыми органами субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса.\n\nОтказ уполномоченного органа в предоставлении отсрочки или рассрочки может быть обжалован заинтересованным лицом в порядке, установленном законодательством Российской Федерации.\n\nНормативными правовыми актами представительного органа федеральной территории \"Сириус\" могут быть установлены дополнительные основания и иные условия предоставления отсрочки и рассрочки по уплате в федеральной территории \"Сириус\" местных налогов и (или) сборов.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 64. Порядок и условия предоставления отсрочки или рассрочки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce3638a3df90af017974a08f5060b9584d435ce980fa3022565570117c08091d"},{"code_id":"NK_RF","article_number":"64.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 26.11.2008 № 224-ФЗ) (Утратила силу - Федеральный закон от 08.03.2015 № 49-ФЗ)","article_title":"Статья 64.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5889e5cecda1285b8b7783826c9f31e2356e12344283b7c0497959b90d92f7b1"},{"code_id":"NK_RF","article_number":"65","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 65. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"874e85b038eba45ec46f4c9aa648a494e0dd2d12f41eef16117bed6c09a151a9"},{"code_id":"NK_RF","article_number":"66","version_date":"2000-07-31","article_text":"Инвестиционный налоговый кредит может быть предоставлен по налогу на прибыль организации, а также по региональным и местным налогам. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nИнвестиционный налоговый кредит может быть предоставлен на срок от одного года до пяти лет.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nУменьшение производится по каждому платежу соответствующего налога, по которому предоставлен инвестиционный налоговый кредит, за каждый отчетный период до тех пор, пока сумма, не уплаченная организацией в результате всех таких уменьшений (накопленная сумма кредита), не станет равной сумме кредита, предусмотренной соответствующим договором. Конкретный порядок уменьшения налоговых платежей определяется заключенным договором об инвестиционном налоговом кредите. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЕсли организацией заключено более одного договора об инвестиционном налоговом кредите, срок действия которых не истек к моменту очередного платежа по налогу, накопленная сумма кредита определяется отдельно по каждому из этих договоров. При этом увеличение накопленной суммы кредита производится вначале в отношении первого по сроку заключения договора, а при достижении этой накопленной суммой кредита размера, предусмотренного указанным договором, организация может увеличивать накопленную сумму кредита по следующему договору.\n\nЕсли организация имела убытки по результатам отдельных отчетных периодов в течение налогового периода либо убытки по итогам всего налогового периода, излишне накопленная по итогам налогового периода сумма кредита переносится на следующий налоговый период и признается накопленной суммой кредита в первом отчетном периоде нового налогового периода. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 66. Инвестиционный налоговый кредит","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b27e4c1b9d0e3b3fe1e078f7d16aa9c08b995e451926ff6485ba4791003f50c"},{"code_id":"NK_RF","article_number":"67","version_date":"2000-07-31","article_text":"1. Инвестиционный налоговый кредит может быть предоставлен организации, являющейся налогоплательщиком соответствующего налога, при наличии хотя бы одного из следующих оснований:\n\n1) проведение этой организацией научно-исследовательских или опытно-конструкторских работ либо технического перевооружения собственного производства, в том числе направленного на создание рабочих мест для инвалидов и (или) повышение энергетической эффективности производства товаров, выполнения работ, оказания услуг, или осуществление мероприятия или мероприятий по снижению негативного воздействия на окружающую среду, предусмотренных пунктом 4 статьи 17 Федерального закона от 10 января 2002 года № 7-ФЗ \"Об охране окружающей среды\"; (В редакции федеральных законов от 23.11.2009 № 261-ФЗ; от 21.07.2014 № 219-ФЗ)\n\n2) осуществление этой организацией внедренческой или инновационной деятельности, в том числе создание новых или совершенствование применяемых технологий, создание новых видов сырья или\n\nматериалов;\n\n3) выполнение этой организацией особо важного заказа по социально-экономическому развитию региона или предоставление ею особо важных услуг населению;\n\n4) выполнение организацией государственного оборонного заказа; (Дополнение подпунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n5) осуществление этой организацией инвестиций в создание объектов, имеющих наивысший класс энергетической эффективности, в том числе многоквартирных домов, и (или) относящихся к возобновляемым источникам энергии, и (или) относящихся к объектам по производству тепловой энергии, электрической энергии, имеющим коэффициент полезного действия более чем 57 процентов, и (или) иных объектов, технологий, имеющих высокую энергетическую эффективность, в соответствии с перечнем, утвержденным Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.11.2009 № 261-ФЗ)\n\n6) (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\n2. Инвестиционный налоговый кредит предоставляется:\n\n1) по основаниям, указанным в подпунктах 1 и 5 пункта 1 настоящей статьи, - на сумму кредита, составляющую 100 процентов стоимости приобретенного заинтересованной организацией оборудования, используемого исключительно для перечисленных в этих подпунктах целей; (В редакции федеральных законов от 23.11.2009 № 261-ФЗ; от 27.07.2010 № 229-ФЗ; от 23.07.2013 № 248-ФЗ)\n\n2) по основаниям, указанным в подпунктах 2 - 4 пункта 1 настоящей статьи, - на суммы кредита, определяемые по соглашению между уполномоченным органом и заинтересованной организацией; (В редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\n3) (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу  - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\n3. Основания для получения инвестиционного налогового кредита должны быть документально подтверждены заинтересованной организацией.\n\nФорма договора об инвестиционном налоговом кредите устанавливается уполномоченным органом принимающим решение о предоставлении инвестиционного налогового кредита. (В редакции Федерального закона от 29.07.2004 № 95-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (Утратил силу - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nДоговор об инвестиционном налоговом кредите должен содержать положения, в соответствии с которыми не допускаются в течение срока его действия реализация или передача во владение, пользование или распоряжение другим лицам оборудования или иного имущества, приобретение которого организацией явилось условием для предоставления инвестиционного налогового кредита, либо определяются условия такой реализации (передачи).\n\nНе допускается устанавливать проценты на сумму кредита по ставке, менее одной второй и превышающей три четвертых ставки рефинансирования Центрального банка Российской Федерации. (В редакции  федеральных законов от 03.12.2011 № 392-ФЗ, от 23.11.2024 № 393-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nКопия договора представляется организацией в налоговый орган по месту ее учета в пятидневный срок со дня заключения договора.\n\nНормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах, подлежащих уплате в федеральной территории \"Сириус\", могут быть установлены иные основания и условия предоставления инвестиционного налогового кредита, включая сроки действия инвестиционного налогового кредита и ставки процентов на сумму кредита. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.03.2012 № 19-ФЗ)","article_title":"Статья 67. Порядок и условия предоставления инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fef7951f5c8bbc92264b4e55b14cec780ac83a90bb0c01f584e471e23c4bd0e7"},{"code_id":"NK_RF","article_number":"68","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПри этом оставшаяся неуплаченной сумма задолженности определяется как разница между суммой задолженности, определенной в решении о предоставлении отсрочки (рассрочки), увеличенной на сумму процентов, исчисленную в соответствии с таким решением о предоставлении отсрочки или рассрочки начиная со дня вступления в силу решения о предоставлении отсрочки или рассрочки за период действия отсрочки (рассрочки), и фактически уплаченными суммами и процентами. (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 68. Прекращение действия отсрочки, рассрочки или инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"071e285286b426442a23badd35c08f657db7dc51160080ffa43dd2b6ed06e3fe"},{"code_id":"NK_RF","article_number":"69","version_date":"2000-07-31","article_text":"1. Неисполнение обязанности по уплате налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов, повлекшее формирование отрицательного сальдо единого налогового счета налогоплательщика, является основанием для направления налоговым органом налогоплательщику требования об уплате задолженности.\n\nТребованием об уплате задолженности признается извещение налогоплательщика о наличии отрицательного сальдо единого налогового счета и сумме задолженности с указанием налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов на момент направления требования, а также об обязанности уплатить в установленный срок сумму задолженности.\n\nПосле восстановления учета на едином налоговом счете сумм, ранее не учтенных в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса, новое требование об уплате задолженности не направляется. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n2. Требование об уплате задолженности также должно содержать:\n\nсведения о сроке исполнения требования;\n\nсведения о мерах по взысканию задолженности и обеспечению исполнения обязанности по уплате налога, авансовых платежей, сборов, страховых взносов, пеней, штрафов, процентов, которые будут применены в случае неисполнения требования налогоплательщиком;\n\nпредупреждение об обязанности налогового органа в соответствии с пунктом 3 статьи 32 настоящего Кодекса направить материалы в следственные органы для решения вопроса о возбуждении уголовного дела (в случае, если размер недоимки позволяет предполагать факт совершения нарушения законодательства о налогах и сборах, содержащего признаки преступления).\n\n3. Требование об уплате задолженности должно быть исполнено в течение восьми дней с даты получения указанного требования, если более продолжительный период времени для уплаты задолженности не указан в этом требовании.\n\nИсполнением требования об уплате задолженности признается уплата (перечисление) суммы задолженности в размере отрицательного сальдо на дату исполнения.\n\nФорматы и порядок направления налогоплательщику требования об уплате задолженности в электронной форме по телекоммуникационным каналам связи устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 69. Требование об уплате задолженности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72d4b044939712aa0cfd8c9fac5c5a6b96a674fd72cd79d37f3b2fcbbad8af5a"}]$law7v023$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
